        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Normalise mode
    if mode is not None:
        mode = mode.upper()
    else:
        mode = "WRITE"

    # Normalise bookmarks to list
    if bookmarks is None:
        bookmarks_list = []
    else:
        if isinstance(bookmarks, (str, bytes)):
            bookmarks_list = [bookmarks]
        else:
            try:
                bookmarks_list = list(bookmarks)
            except TypeError:
                bookmarks_list = [bookmarks]

    # Assemble metadata payload
    payload = {"mode": mode, "bookmarks": bookmarks_list}
    if metadata:
        if not isinstance(metadata, dict):
            raise TypeError("metadata must be a dict")
        payload.update(metadata)
    if timeout is not None:
        payload["timeout"] = timeout
    if db is not None:
        payload["database"] = db
    if imp_user is not None:
        payload["imp_user"] = imp_user

    # Default hooks if None
    dehydration_hooks = dehydration_hooks or {}
    hydration_hooks = hydration_hooks or {}

    # Append BEGIN record to the out queue
    self._output.append("BEGIN", payload, dehydration_hooks, hydration_hooks, handlers)

    # Return a Response object that will drive the transaction lifecycle
    return Response(self._driver, self._output)

