def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    import os, sys, shutil
    if not cmd:
        return cmd
    if os.name != 'nt':
        return cmd
    executable = cmd[0]
    # Skip native Windows executables or scripts
    _, ext = os.path.splitext(executable)
    if ext.lower() in {'.exe', '.bat', '.cmd', '.com'}:
        return cmd
    if not os.path.isfile(executable):
        return cmd
    try:
        with open(executable, 'rb') as f:
            first_line = f.readline().decode(errors='ignore')
    except Exception:
        return cmd
    if not first_line.startswith('#!'):
        return cmd
    # Resolve shebang interpreter path
    interpreter = first_line[2:].strip().split()[0]
    interpreter_path = shutil.which(interpreter)
    if interpreter_path is None:
        interpreter_path = sys.executable
    # Construct new command to run the script via the interpreter
    new_cmd = (interpreter_path, executable) + cmd[1:]
    return new_cmd

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    import os, sys, shlex, shutil

    if not cmd:
        return cmd

    script = cmd[0]
    if not os.path.isfile(script):
        return cmd

    try:
        with open(script, "rb") as f:
            first_line = f.readline().decode(errors="ignore")
    except Exception:
        return cmd

    if not first_line.startswith("#!"):
        return cmd

    # parse the shebang line, handling quoting and arguments
    parts = shlex.split(first_line[2:].strip())
    if not parts:
        return (script, *cmd[1:])

    interpreter = parts[0]
    args = parts[1:]

    # Handle 'env' which forwards the rest of the arguments
    if interpreter in ("env", "/usr/bin/env", "\\usr\\bin\\env"):
        if args:
            interpreter = args[0]
            args = args[1:]

    # On Windows, ensure the interpreter is an executable
    base, ext = os.path.splitext(interpreter)
    if not ext:
        # Common interpreter names that typically have .exe
        if os.path.basename(interpreter).lower() in ("python", "python3", "python3.8", "python3.9"):
            interpreter += ".exe"
        else:
            # Try to locate it in PATH if not absolute
            if not os.path.isabs(interpreter):
                found = shutil.which(interpreter)
                if found:
                    interpreter = found

    # Construct the new command to run on Windows
    new_cmd = [interpreter] + args + [script] + list(cmd[1:])
    return tuple(new_cmd)

