def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if not isinstance(maxsize, int):
        raise TypeError("cache size must be an integer")
    if maxsize <= 0:
        # No caching performed
        def decorating_function(func):
            return func
        return decorating_function

    def decorating_function(user_function):
        cache = {}
        hits = 0
        misses = 0

        def _make_key(args, kw, typed):
            key = args
            if kw:
                key += tuple(sorted(kw.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kw:
                    key += tuple(type(v) for k, v in sorted(kw.items()))
            return key

        def wrapper(*args, **kw):
            nonlocal hits, misses
            key = _make_key(args, kw, typed)
            if key in cache:
                # Move key to be the newest (most recent)
                cache[key] = cache.pop(key)
                hits += 1
                return cache[key]
            else:
                misses += 1
                result = user_function(*args, **kw)
                if len(cache) == maxsize:
                    # Evict most recently used item (the last one)
                    cache.popitem(last=True)
                cache[key] = result
                return result

        def cache_info():
            return {"hits": hits, "misses": misses, "maxsize": maxsize, "currsize": len(cache)}

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            hits = misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorating_function

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm."""
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")

    def decorator(func):
        cache = {}
        freq = {}

        def wrapper(*args, **kwargs):
            try:
                key_args = args
                key_kwargs = tuple(sorted(kwargs.items()))
                if typed:
                    key = (key_args, key_kwargs, tuple(map(type, key_args)),
                           tuple(type(v) for _, v in key_kwargs))
                else:
                    key = (key_args, key_kwargs)
            except TypeError:
                # Unhashable argument; bypass cache
                return func(*args, **kwargs)

            if key in cache:
                # Increment hit count
                freq[key] += 1
                return cache[key]

            # Cache miss; compute result
            result = func(*args, **kwargs)

            if len(cache) >= maxsize:
                # Find least frequently used key(s)
                min_freq = min(freq.values())
                # Evict one key with the lowest frequency
                for k in list(freq):
                    if freq[k] == min_freq:
                        del cache[k]
                        del freq[k]
                        break

            cache[key] = result
            freq[key] = 1
            return result

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        return wrapper

