@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string with limited stack depth and path length.
    """
    import os, traceback

    def _truncate_path(path):
        parts = path.split(os.sep)
        if len(parts) > max_path_level:
            return os.sep.join(parts[-max_path_level:])
        return path

    def _format_frame(frame):
        return f'File "{_truncate_path(frame.filename)}", line {frame.lineno}, in {frame.name}\n    {frame.line}'

    lines = []
    exc = e
    seen = set()
    while exc and exc not in seen:
        seen.add(exc)
        tb = exc.__traceback__
        if tb:
            stack = traceback.extract_tb(tb)
            # keep only the most recent frames up to max_level
            stack = stack[-max_level:]
            for frame in stack:
                lines.append(_format_frame(frame))
        lines.append(f'{exc.__class__.__name__}: {exc}')
        # chain to cause or context if any
        if exc.__cause__:
            chain_desc = 'During handling of the above exception, another exception occurred:'
            lines.append(chain_desc)
            exc = exc.__cause__
        elif exc.__context__ and not exc.__suppress_context__:
            chain_desc = 'During handling of the above exception, another exception occurred:'
            lines.append(chain_desc)
            exc = exc.__context__
        else:
            exc = None
    return "\n".join(lines)

