def minimalBases(classes):
    # Reduce a list of base classes to its ordered minimum equivalent.
    result = []
    for cls in classes:
        # Skip if cls is a subclass (or equal) of any class already in result.
        if isinstance(cls, type):
            if any(issubclass(cls, existing) for existing in result):
                continue
        result.append(cls)
    return tuple(result)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent."""
    result = []
    for cls in classes:
        # Skip duplicates
        if cls in result:
            continue
        # Skip if cls is a subclass of any already-accepted base
        if any(issubclass(cls, base) for base in result):
            continue
        result.append(cls)
    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = []
    for cls in classes:
        if cls in seen:
            continue
        # drop any previously kept base that is a subclass of the new base
        seen = [b for b in seen if not issubclass(b, cls)]
        # skip the new base if it is a subclass of any retained base
        if any(issubclass(cls, b) for b in seen):
            continue
        seen.append(cls)
    return tuple(seen)

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    import inspect
    result = {}
    # Choose which members to inspect
    if all:
        # Inspect all attributes, including inherited
        members = inspect.getmembers(self.__class__, lambda a: not(inspect.isroutine(a)))
    else:
        # Inspect only attributes directly defined in the class (skip private names)
        members = self.__class__.__dict__.items()
    for name, attr in members:
        # Skip special and private names unless 'all' is requested
        if not all and (name.startswith('_')):
            continue
        # Get the description from property docstring if it's a property,
        # otherwise from the object's __doc__ attribute if present.
        if isinstance(attr, property):
            desc = attr.__doc__
        else:
            desc = getattr(attr, "__doc__", None)
        if desc:
            result[name] = desc
    return result

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    attrs = {}
    for name in dir(self.__class__):
        if name.startswith('_'):
            continue
        try:
            obj = getattr(self.__class__, name)
        except AttributeError:
            continue
        if callable(obj):
            continue
        if isinstance(obj, property):
            desc = obj.__doc__
        else:
            desc = getattr(obj, "__doc__", "")
        if desc is None:
            desc = ""
        attrs[name] = desc
    if not all:
        attrs = {k: v for k, v in attrs.items() if v}
    return attrs

def names(self, all=False):  # pylint:disable=redefined-builtin
    """
    Return the attribute names defined by the interface.

    If ``all`` is ``True``, include also inherited names; otherwise
    only return names defined in the current class.
    """
    cls = self.__class__
    def candidate(name, value):
        """Return true if the name/value looks like an interface attribute."""
        # Exclude private/dunder attributes
        if name.startswith('_'):
            return False
        # Exclude methods, functions and classes
        if callable(value):
            return False
        # Exclude descriptors that are likely to be "private" helpers
        # (we don't exclude property objects explicitly)
        return True

    if all:
        attr_names = set()
        for base in cls.__mro__:
            for name, value in vars(base).items():
                if candidate(name, value):
                    attr_names.add(name)
        return sorted(attr_names)
    else:
        return sorted(name for name, value in vars(cls).items()
                      if candidate(name, value))

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    def _extract_names(cls):
        return [
            name
            for name, val in cls.__dict__.items()
            if not name.startswith("_")
            and not isinstance(val, (staticmethod, classmethod))
            and not callable(val)
        ]

    if all:
        seen = set()
        # Traverse MRO from base to derived to preserve typical appearance order
        ordered_names = []
        for base in reversed(self.__class__.__mro__):
            for name in _extract_names(base):
                if name not in seen:
                    seen.add(name)
                    ordered_names.append(name)
        return ordered_names

    return _extract_names(self.__class__)

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for elem in sequence:
        # Expand nested tuples or lists to individual elements
        if isinstance(elem, (tuple, list)):
            output.extend(elem)
        else:
            output.append(elem)
    return output

