def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for decl in sequence or []:
        # Expand tuples and lists into their elements
        if isinstance(decl, (tuple, list)):
            for sub in decl:
                if isinstance(sub, (tuple, list)):
                    # Keep nested tuples as is; flatten those that contain a single element
                    output.append(tuple(sub))
                else:
                    output.append((sub,))
        else:
            output.append((decl,))
    return output

