def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the tracking context
    self.context = {}

    # Reinitialize bins using the configured initial value if provided,
    # otherwise rebuild them from scratch.
    if hasattr(self, 'initial_value') and self.initial_value is not None:
        # Preserve the original number of bins while resetting their values.
        try:
            bin_count = len(self.bins)
        except Exception:
            bin_count = 0
        self.bins = [self.initial_value] * bin_count
    else:
        self.bins = self.make_bins()

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.
    """
    # Prepare lines list
    lines = []

    # Add header if provided
    if header is not None:
        lines.append(str(header))

    # Get iterable of points
    points = None
    if hasattr(self, "points"):
        points = self.points
    elif hasattr(self, "_points"):
        points = self._points
    elif hasattr(self, "__iter__"):
        points = self
    else:
        raise AttributeError("Unable to find points iterable in the graph object")

    for point in points:
        # Determine coordinate and value
        coord = None
        value = None
        if isinstance(point, tuple) or isinstance(point, list):
            if len(point) == 2:
                coord, value = point
            else:
                # If more than 2, assume last is value, rest are coordinates
                coord = point[:-1]
                value = point[-1]
        else:
            # Assume the point itself is the coordinate and value is None
            coord = point
            value = None

        # Build parts list
        parts = []

        # Handle coordinate(s)
        if isinstance(coord, (list, tuple)) and not isinstance(coord, str):
            for c in coord:
                parts.append(str(c))
        else:
            parts.append(str(coord))

        # Handle value(s)
        if value is not None:
            if isinstance(value, (list, tuple)) and not isinstance(value, str):
                for v in value:
                    parts.append(str(v))
            else:
                parts.append(str(value))

        # Join parts with separator
        line = separator.join(parts)
        lines.append(line)

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Cache computed indices for efficiency
    if not hasattr(self, "_err_indices_cache"):
        self._err_indices_cache = {}
    if coord_name in self._err_indices_cache:
        return self._err_indices_cache[coord_name]

    # Attempt to retrieve the error array associated with the coordinate.
    # Expect attribute naming convention: <coord_name>_err
    err_attr = f"{coord_name}_err"
    coord_err = getattr(self, err_attr, None)

    if coord_err is None:
        # No error array found; return empty index array
        indices = np.array([], dtype=int)
    else:
        # For numpy arrays or masked arrays, compute indices where
        # error values are not finite (NaN or inf).
        if isinstance(coord_err, (np.ndarray, np.ma.MaskedArray)):
            indices = np.nonzero(~np.isfinite(coord_err))[0]
        else:
            # If the error attribute is not array-like, default to empty
            indices = np.array([], dtype=int)

    # Store in cache before returning
    self._err_indices_cache[coord_name] = indices
    return indices

