        self._coord_to_err_index = {}
        # If the error array dimensions are stored in `_err_dims` (a list of names),
        # map each to its index.  Fall back on `_err_axes` if available.
        dim_names = getattr(self, "_err_dims", None)
        if dim_names is None:
