    """
    Return a list of indices that correspond to errors for the given coordinate name.
    If no explicit mapping exists, fall back to inspecting the ``_errors`` attribute for
    dictionaries that match the coordinate name; otherwise, return an empty list.
    """
    # First try a pre-computed mapping if available.
    if hasattr(self, "_coord_error_map") and isinstance(self._coord_error_map, dict):
        return self._coord_error_map.get(coord_name, [])

    # Next try a list of error dictionaries that might contain a 'coord' key.
    if hasattr(self, "_errors") and isinstance(self._errors, list):
        return [
            idx
            for idx, err in enumerate(self._errors)
            if isinstance(err, dict) and err.get("coord") == coord_name
        ]

    # If all else fails, return an empty list to signal no error indices.
    return []

def _update_context(self, context):
    """
    Update *context* with the properties of this graph.

    Append indices to *context.error* for each error attribute of the graph.
    Existing values in *context.value* and its subcontexts are preserved.
    """
    # Ensure the context has an error dictionary
    if not hasattr(context, 'error') or context.error is None:
        context.error = {}

    # Start counting from the current number of errors
    next_index = len(context.error)

    # Inspect all attributes that represent errors
    for attr_name in dir(self):
        if not attr_name.startswith('error_'):
            continue

        # Derive a simplified error key (e.g., 'error_E_low' → 'x_low')
        # Attempt to map coordinate names to 'x', 'y', 'z' if such mapping exists.
        # Default to the attribute name without 'error_'.
        base_key = attr_name[6:]
        # Try to replace the first coordinate letter if it exists in the graph
        # This is a heuristic; if the graph defines coordinates, its first three
        # are considered x, y, z respectively.
        try:
            coord_names = getattr(self, 'coordinates')
        except AttributeError:
            coord_names = []

        # Replace a leading coordinate name with 'x', 'y', or 'z'
        if isinstance(coord_names, (list, tuple)) and coord_names:
            for idx, coord in enumerate(coord_names[:3]):
                if base_key.startswith(coord):
                    base_key = base_key.replace(coord, chr(ord('x') + idx), 1)
                    break

        # Lowercase the key
        err_key = base_key.lower()

        # Append the error index if this key is not already recorded
        if err_key not in context.error:
            context.error[err_key] = {"index": next_index}
            next_index += 1
    # Note: values in context.value are intentionally not modified.

def _update_context(self, context):
        """
        Update *context* with the properties of this graph.
        The method gathers all error columns in the graph and registers
        their positions in the *context.error* dictionary.  The error
        keys are generated according to the first three coordinate names
        (indexed as ``x``, ``y`` and ``z``).  Existing entries in
        *context.value* are left untouched.
        """
        # Ensure we have a mutable mapping for errors
        err_dict = getattr(context, 'error', None)
        if err_dict is None:
            # if the context uses dict-style access
            err_dict = context.get('error', {})
        if not isinstance(err_dict, dict):
            err_dict = {}

        # Names of all fields defined by the graph
        try:
            field_names = self.fields
        except AttributeError:
            # Fallback attribute names
            field_names = getattr(self, '_fields', [])
        if not isinstance(field_names, (list, tuple)):
            field_names = list(field_names)

        # Create a map from coordinate name to the simple letter
        coord_map = {}
        for idx, name in enumerate(field_names[:3]):  # only first three
            coord_map[name] = ('x', 'y', 'z')[idx]

        # Iterate over all fields and collect errors
        for idx, name in enumerate(field_names):
            if name.startswith('error_'):
                rest = name[len('error_'):]
                parts = rest.split('_', 1)
