def difference(d1, d2, level=-1):
    """
    Return a dictionary containing items from *d1* that are not present
    in *d2*.  Recursively compares nested dictionaries up to *level*
    depths.  For infinite recursion, *level* should be set to ``-1``.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return {}
    result = {}
    for key, val in d1.items():
        if key not in d2:
            result[key] = val
            continue
        other = d2[key]
        # If both values are dictionaries, recurse if depth allows
        if isinstance(val, dict) and isinstance(other, dict):
            # Decide whether to recurse
            if level != 0:
                new_depth = level - 1 if level > 0 else level
                subdiff = difference(val, other, new_depth)
                if subdiff:
                    result[key] = subdiff
            else:
                # depth exhausted; use dictionary equality check
                if val != other:
                    result[key] = val
        else:
            # Primitive values or mismatched types
            if val != other:
                result[key] = val
    return result

def difference(d1, d2, level=-1):
    def _deep_copy(obj):
        if isinstance(obj, dict):
            return {k: _deep_copy(v) for k, v in obj.items()}
        return obj

    def _diff(a, b, lev):
        res = {}
        for k, v in a.items():
            if k not in b:
                res[k] = _deep_copy(v) if isinstance(v, dict) else v
                continue
            v2 = b[k]
            if v == v2:
                continue
            # values differ
            if isinstance(v, dict) and isinstance(v2, dict) and lev != 0:
                child = _diff(v, v2, lev - 1 if lev > 0 else -1)
                if child:
                    res[k] = child
                else:
                    res[k] = _deep_copy(v) if isinstance(v, dict) else v
            else:
                res[k] = _deep_copy(v) if isinstance(v, dict) else v
        return res

    return _diff(d1, d2, level)

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    def _diff(d1_dict, d2_dict, depth):
        res = {}
        for key, v1 in d1_dict.items():
            if key not in d2_dict:
                res[key] = v1
            else:
                v2 = d2_dict[key]
                if isinstance(v1, dict) and isinstance(v2, dict):
                    # Recurse if allowed
                    if depth == 0:
                        # No further recursion; only include if dict values differ
                        if v1 != v2:
                            res[key] = v1
                    else:
                        subres = _diff(v1, v2, depth - 1 if depth > 0 else depth)
                        if subres:
                            res[key] = subres
                else:
                    if v1 != v2:
                        res[key] = v1
        return res

    # Compute the difference starting at the given level
    diff = _diff(d1, d2, level if level >= 0 else -1)

    # No explicit deep copy is necessary because all non-dict values are
    # copied by value and nested dicts are freshly created.
    return diff

def _validate_labels(labels):
    import re
    key_pattern = re.compile(r'^[a-zA-Z0-9_]+$')
    val_pattern = re.compile(r'^[a-zA-Z0-9_]+$')
    errors = []

    def _validate_value(value, key_prefix):
        if isinstance(value, list):
            for idx, item in enumerate(value):
                _validate_value(item, f"{key_prefix}[{idx}]")
        elif isinstance(value, (str, bytes)):
            if not val_pattern.match(value):
                errors.append({key_prefix: f"Label value '{value}' does not match the regex {val_pattern.pattern}"})
        else:
            errors.append({key_prefix: 'expected string or bytes-like object'})

    for key, value in labels.items():
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
            continue
        if not key_pattern.match(key):
            errors.append({key: f"Label key '{key}' does not match the regex {key_pattern.pattern}"})
        _validate_value(value, key)

    if errors:
        raise ValidationError(errors)

