def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    # Regular expression that keys must match. Adjust this pattern as needed.
    KEY_REGEX = re.compile(r"^[A-Za-z0-9_.-]+$")

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, str):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            if not KEY_REGEX.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex"})

        # Validate value
        if isinstance(value, (list, tuple)):
            for v in value:
                if not isinstance(v, (str, bytes)):
                    errors.append({str(v): "expected string or bytes-like object"})
            # If the entire value is an iterable, we do not further validate its type
        else:
            if not isinstance(value, (str, bytes)):
                # If key was already flagged as an invalid type, avoid duplicate messages
                if not isinstance(key, str):
                    # Use the key's string representation for the error key to avoid
                    # duplication with the key error already added.
                    errors.append({str(value): "expected string or bytes-like object"})

    if errors:
        raise ValidationError(errors)

def validate_key(key):
    import re
    if not isinstance(key, str):
        raise ValidationError("Key must be a string")
    key_pattern = re.compile(r'^[A-Za-z0-9_-]{1,255}$')
    if not key_pattern.fullmatch(key):
        raise ValidationError(f"'{key}' is not a valid key.")
    return key

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively generate a default observer_schema dictionary from a Kubernetes
    resource fragment.  All non-dict and non-list values are replaced by None.
    For the top‑level call (when ``first_level`` is True) the values of the
    identifying fields are preserved from the original manifest.  Those
    identifying fields are:
        - ``apiVersion``
        - ``kind``
        - ``metadata`` entries ``name`` and ``namespace``

    Parameters
    ----------
    manifest_dict : dict
        Partial Kubernetes resource
    first_level : bool, optional
        Indicates whether this is the top‑level call that will produce a
        complete observer_schema for the resource.

    Returns
    -------
    dict
        The generated observer_schema fragment.
    """
    result = {}

    # Identify top‑level identifying fields
    top_level_identifiers = {"apiVersion", "kind"}

    for key, value in manifest_dict.items():
        # Recursive handling of nested dictionaries
        if isinstance(value, dict):
            if first_level and key == "metadata":
                # Preserve name and namespace, set other entries to None
                sub_meta = {}
                for sub_key, sub_val in value.items():
                    if sub_key in ("name", "namespace"):
                        # Preserve the original identifying values
                        sub_meta[sub_key] = sub_val
                    elif isinstance(sub_val, (dict, list)):
                        # Recurse/handle nested structures but reset values
                        sub_meta[sub_key] = (
                            generate_default_observer_schema_dict(sub_val, first_level=False)
                            if isinstance(sub_val, dict)
                            else generate_default_observer_schema_list(sub_val, first_level=False)
                        )
                    else:
                        sub_meta[sub_key] = None
                result[key] = sub_meta
            else:
                # Regular nested dict: recurse normally
                result[key] = generate_default_observer_schema_dict(value, first_level=False)

        # Recursive handling of lists
        elif isinstance(value, list):
            # Assume a helper function exists to process lists
            result[key] = generate_default_observer_schema_list(value, first_level=False)

        # Base case: scalar values
        else:
            if first_level and key in top_level_identifiers:
                # Copy identifying scalar values from the manifest
                result[key] = value
            else:
                # Non‑identifying scalars are replaced with None
                result[key] = None

    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively create a default observer_schema dictionary from a Kubernetes manifest.

    For each key in ``manifest_dict``:
    - If the value is a dict, recurse into it.
    - If the value is a list, delegate to generate_default_observer_schema_list.
    - Otherwise (scalar values), set the value to ``None``.
      When ``first_level`` is ``True`` the values for the identifying fields
      ('kind', 'apiVersion', 'metadata') are kept from the original manifest.
    """
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            result[key] = generate_default_observer_schema_list(value, first_level=False)
        else:
            if first_level and key in ("kind", "apiVersion", "metadata"):
                result[key] = value
            else:
                result[key] = None
    return result

