def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update a list field of the last_applied_manifest
    from the corresponding list in the Kubernetes API response.
    The function assumes that `observer_schema` describes the
    structure of each element in the list, and that
    `update_last_applied_manifest_dict_from_resp` is available
    for nested dictionary updates.

    Args:
        last_applied_manifest (list): A list representing the
            current state of the field in the last applied
            manifest. It may be empty or partially populated.
        observer_schema (list or dict): Schema information
            describing each element in the list. It can be a
            list of schemas (one per element) or a single
            schema applicable to every element.
        response (list): The list of values retrieved from
            the Kubernetes API.

    Returns:
        None. The `last_applied_manifest` is modified in place.
    """
    # Ensure the destination is a list.
    if not isinstance(last_applied_manifest, list):
        return

    # If no response, nothing to update.
    if response is None:
        return

    # Iterate over the items in the response.
    for idx, resp_item in enumerate(response):
        # Make sure the destination list has this index.
        if idx >= len(last_applied_manifest):
            # Append appropriate placeholder based on the type of resp_item.
            if isinstance(resp_item, dict):
                last_applied_manifest.append({})
            elif isinstance(resp_item, list):
                last_applied_manifest.append([])
            else:
                # For primitive types, simply append the value.
                last_applied_manifest.append(resp_item)
                continue

        # If the schema for the element is a dictionary, use the dict updater.
        if isinstance(observer_schema, dict):
            if isinstance(resp_item, dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[idx], observer_schema, resp_item
                )
            else:
                last_applied_manifest[idx] = resp_item

        # If the schema is a list, use the list updater (per-element schema list).
        elif isinstance(observer_schema, list):
            # Determine the per-element schema: either the same schema for all
            # elements or a specific schema at the same index if available.
            element_schema = None
            if idx < len(observer_schema):
                element_schema = observer_schema[idx]
            else:
                # Fall back to a generic element schema if the list is shorter.
                element_schema = observer_schema[-1] if observer_schema else {}

            if isinstance(resp_item, dict):
                # If the back-end schema is dict, apply dict updater.
                if isinstance(element_schema, dict):
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[idx], element_schema, resp_item
                    )
                else:
                    last_applied_manifest[idx] = resp_item
            elif isinstance(resp_item, list):
                # Recursively handle nested lists.
                if isinstance(element_schema, list):
                    update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[idx], element_schema, resp_item
                    )
                else:
                    # If the schema doesn't describe a list, just copy.
                    last_applied_manifest[idx] = resp_item
            else:
                # Primitive types; just assign.
                last_applied_manifest[idx] = resp_item

        # If the schema is some other type, default to direct assignment.
        else:
            last_applied_manifest[idx] = resp_item

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for key, sub_schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Key '{key}' not found in Kubernetes response")
        value = response[key]
        if isinstance(sub_schema, dict):
            sub_last = last_applied_manifest.get(key, {})
            if not isinstance(sub_last, dict):
                sub_last = {}
            update_last_applied_manifest_dict_from_resp(sub_last, sub_schema, value)
            last_applied_manifest[key] = sub_last
        else:
            if key not in last_applied_manifest:
                last_applied_manifest[key] = value)

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for key, subschema in observer_schema.items():
        # Skip fields that are already present in the manifest
        if key in last_applied_manifest:
            continue

        # Check if we have a nested schema
        if isinstance(subschema, dict):
            # Case: explicit type definition
            if subschema.get("type") == "object":
                nested_resp = response.get(key)
                if nested_resp is None:
                    raise KeyError(f"Field '{key}' not present in response")
                last_applied_manifest[key] = {}
                nested_schema = subschema.get("properties", subschema)
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], nested_schema, nested_resp
                )
                continue
            if subschema.get("type") == "array":
                nested_resp = response.get(key)
                if nested_resp is None:
                    raise KeyError(f"Field '{key}' not present in response")
                last_applied_manifest[key] = []
                items_schema = subschema.get("items", subschema)
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], items_schema, nested_resp
                )
                continue

            # If no explicit type, assume a nested object defined by the dict itself
            nested_resp = response.get(key)
            if nested_resp is None:
                raise KeyError(f"Field '{key}' not present in response")
            last_applied_manifest[key] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], subschema, nested_resp
            )
            continue

        # Otherwise, treat it as a leaf field
        if key not in response:
            raise KeyError(f"Field '{key}' not present in response")
        last_applied_manifest[key] = response[key]

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Update a partial last_applied_manifest from a partial Kubernetes response.

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being updated.
        observer_schema (dict): schema describing which fields to observe. Keys are field names.
                                Values are either ``None`` for leaf fields, a nested ``dict`` for nested objects,
                                or a ``list`` containing a single schema element for list fields.
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response.
        TypeError: If the structure of the response does not match the observer_schema.
    """
    for key, subschema in observer_schema.items():
        # ensure field exists in response
        if key not in response:
            raise KeyError(f"Missing observed field '{key}' in response")
        resp_value = response[key]

        # Leaf field
        if subschema is None:
            if key not in last_applied_manifest:
                last_applied_manifest[key] = resp_value
            continue

        # Nested dict
        if isinstance(subschema, dict):
            if not isinstance(resp_value, dict):
                raise TypeError(f"Expected dict for field '{key}', got {type(resp_value).__name__}")
            # Create nested dict if missing
            if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], dict):
                last_applied_manifest[key] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], subschema, resp_value
            )
            continue

        # List of items
        if isinstance(subschema, list):
            if not isinstance(resp_value, list):
                raise TypeError(f"Expected list for field '{key}', got {type(resp_value).__name__}")
            # Ensure the list exists in last_applied_manifest
            if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], list):
                last_applied_manifest[key] = []
            item_schema = subschema[0] if subschema else None
            # Iterate over items
            for idx, item_resp in enumerate(resp_value):
                # Ensure list has enough items
                if idx < len(last_applied_manifest[key]) and isinstance(last_applied_manifest[key][idx], dict):
                    item_local = last_applied_manifest[key][idx]
                else:
                    item_local = {}
                    last_applied_manifest[key].append(item_local)
                if isinstance(item_schema, dict) or item_schema is None:
                    # Recurse for nested or leaf item
                    update_last_applied_manifest_dict_from_resp(
                        item_local, item_schema if isinstance(item_schema, dict) else {}, item_resp
                    )
                else:
                    # Unsupported schema type; copy as is
                    last_applied_manifest[key][idx] = item_resp
            continue

        # Unsupported schema type
        raise TypeError(f"Unsupported schema type for field '{key}': {type(subschema).__name__}")

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.
    """
