def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Helper to safely get attributes from the spec
    def _get_spec_attr(attr, default=None):
        spec = getattr(app, "spec", {})
        if hasattr(spec, attr):
            return getattr(spec, attr)
        if isinstance(spec, dict):
            return spec.get(attr, default)
        return default

    manifest = _get_spec_attr("manifest", [])
    custom_schema = _get_spec_attr("observer_schema", {})

    # The observer schema will map keys of the form "<Kind>/<Name>" to a schema dict
    default_schema = {}
    for resource in manifest:
        kind = resource.get("kind") if isinstance(resource, dict) else None
        name = (
            resource.get("metadata", {}).get("name")
            if isinstance(resource, dict)
            else None
        )
        if not kind or not name:
            continue
        key = f"{kind}/{name}"
        if key in custom_schema:
            # Merge custom schema into output
            default_schema[key] = custom_schema[key]
        else:
            # Create a very simple default schema that watches the resource's status
            default_schema[key] = {
                "kind": kind,
                "api_version": resource.get("apiVersion"),
                "match": {"metadata": {"name": name}},
                "wait_condition": {
                    # Example default: wait until status.currentReplicas equals desiredReplicas
                    "currentReplicas": "status.currentReplicas",
                    "desiredReplicas": "spec.replicas",
                },
            }
    return default_schema

