    manifest = getattr(spec, "manifest", {})
    if not isinstance(manifest, dict):
        # Nothing to process if manifest is not a mapping
        return

    # Ensure we have a dictionary for the observer schemas
    observer_schema = getattr(spec, "observer_schema", None)
