def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.
    """
    import re
    from collections.abc import Mapping, Sequence

    # Preserve original type (bytes or str)
    is_bytes = isinstance(sql, (bytes, bytearray))
    sql_str = sql.decode() if is_bytes else sql

    # If styles are identical, return unchanged
    if getattr(self, "in_style", None) == getattr(self, "out_style", None):
        return (sql if is_bytes else sql_str), params

    # Helper to find placeholders in the SQL string
    def _find_placeholders(s, style):
        if style == "named":
            # Named placeholders might start with : or @
            return re.findall(r'[:@]([A-Za-z_][A-Za-z0-9_]*)', s)
        # Ordinal placeholders, assuming '?' as the placeholder
        return [None] * s.count("?")

    # Determine placeholder names/order based on in_style
    in_names = _find_placeholders(sql_str, getattr(self, "in_style", "named"))

    # Conversion logic
    in_style = getattr(self, "in_style", "named")
    out_style = getattr(self, "out_style", "named")

    if out_style == "named":
        # Replace all ordinal placeholders with %(<name>)s format
        if in_style == "named":
            # Already in named form, leave as is
            formatted_sql = sql_str
            out_params = params
        else:
            # Ordinal to named: create synthetic names
            synthetic_names = [f"param_{i}" for i in range(len(in_names))]
            # Build mapping from synthetic names to values
            if isinstance(params, Sequence) and not isinstance(params, (str, bytes, bytearray)):
                out_params = {synthetic_names[i]: params[i] for i in range(len(synthetic_names))}
            else:
                # If params is a mapping, just use it
                out_params = params
            # Replace '?' with named placeholders
            typ = "%(name)s"
            formatted_sql = ""
            i = 0
            for part in re.split(r'(\?)', sql_str):
                if part == "?":
                    formatted_sql += typ % {"name": synthetic_names[i]}
                    i += 1
                else:
                    formatted_sql += part
    else:  # out_style == "ordinal"
        # Replace all named placeholders with '?'
        if in_style == "named":
            formatted_sql = re.sub(r'[:@][A-Za-z_][A-Za-z0-9_]*', '?', sql_str)
            # Build list of parameters in order of appearance
            if isinstance(params, Mapping):
                out_params = [params[name] for name in in_names]
            else:
                out_params = params
        else:
            formatted_sql = sql_str
            out_params = params

    # Return in original type
    result_sql = formatted_sql.encode() if is_bytes else formatted_sql
    return result_sql, out_params

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Accept both string and Path-like objects
    try:
        from pathlib import Path
        root = Path(path)
    except Exception:
        return False

    # Path must be a directory
    if not root.is_dir():
        return False

    # Basic structure checks: expect a manifest and objects directory
    required_dirs = ['manifest', 'objects']
    for d in required_dirs:
        if not (root / d).exists():
            return False

    # Validate the manifest file
    manifest_file = root / 'manifest' / 'manifest.json'
    if not manifest_file.is_file():
        return False
    try:
        import json
        with manifest_file.open('r', encoding='utf-8') as f:
            manifest_data = json.load(f)
    except Exception:
        return False

    # The manifest should contain a list of files
    if not isinstance(manifest_data, dict):
        return False
    files = manifest_data.get('files')
    if not isinstance(files, list):
        return False

    # Each file entry should specify a digest and path, and the blob should exist
    for entry in files:
        if not isinstance(entry, dict):
            return False
        digest = entry.get('digest')
        rel_path = entry.get('path')
        if not digest or not isinstance(digest, str):
            return False
        if not rel_path or not isinstance(rel_path, str):
            return False
        blob_path = root / 'objects' / digest
        if not blob_path.is_file():
            return False

    # At this point, all mandatory checks passed
    return True

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os
    from pathlib import Path

    try:
        # Handle filesystem path (string) or FS object
        if isinstance(path, str):
            p = Path(path)
            if not p.is_dir():
                return False

            # Required top-level items
            required = ["objects", "storage", "manifest.txt"]
            for r in required:
                if not (p / r).exists():
                    return False

            # Read manifest
            try:
                lines = (p / "manifest.txt").read_text(encoding="utf-8").splitlines()
            except Exception:
                return False

            for line in lines:
                if not line.strip():
                    continue
                parts = line.split()
                if len(parts) < 2:
                    continue
                obj_id, size_str = parts[0], parts[1]
                try:
                    expected_size = int(size_str)
                except ValueError:
                    continue
                obj_path = p / "objects" / obj_id
                if not obj_path.is_dir():
                    return False

                actual = 0
                for root_dir, _, files in os.walk(obj_path):
                    for fname in files:
                        fpath = Path(root_dir) / fname
                        try:
                            actual += fpath.stat().st_size
                        except Exception:
                            return False

                # Warnings permitted if sizes differ
                if actual != expected_size:
                    pass

            return True

        else:
            # Assume pyfilesystem2 FS object
            fs_obj = path

            if not fs_obj.isdir("."):
                return False

            required = ["objects", "storage", "manifest.txt"]
            for r in required:
                if not fs_obj.exists(r):
                    return False

            try:
                content = fs_obj.readtext("manifest.txt")
                lines = content.splitlines()
            except Exception:
                return False

            for line in lines:
                if not line.strip():
                    continue
                parts = line.split()
                if len(parts) < 2:
                    continue
                obj_id, size_str = parts[0], parts[1]
                try:
                    expected_size = int(size_str)
                except ValueError:
                    continue
                obj_path = f"objects/{obj_id}"
                if not fs_obj.isdir(obj_path):
                    return False

                actual = 0
                try:
                    for f in fs_obj.walkfiles(obj_path, True):
                        info = fs_obj.getinfo(f)
                        actual += info.size
                except Exception:
                    return False

                if actual != expected_size:
                    # warnings allowed
                    pass

            return True

    except Exception:
        return False

