def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type checks
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Determine specification version
    spec_version = None
    if extract_spec_version:
        type_value = inventory.get("type")
        # Map known type strings to spec versions
        type_to_version = {
            "v2": "2.0",
            "v3": "3.0",
            "beta": "2.1",
            "alpha": "1.9",
        }
        if isinstance(type_value, str):
            spec_version = type_to_version.get(type_value.lower())
        if not spec_version:
            # Fallback to the instance's default if provided
            if hasattr(self, "spec_version"):
                spec_version = self.spec_version
            else:
                raise ValueError(
                    "Spec version could not be extracted and no default is set"
                )
    else:
        # Use instance's default spec_version
        if hasattr(self, "spec_version"):
            spec_version = self.spec_version
        else:
            raise ValueError("Spec version must be set on the validator instance")

    if not isinstance(spec_version, str):
        raise ValueError("Spec version must be a string")

    # Ensure required keys are present
    required_keys = {"data", "metadata"}
    missing = required_keys - inventory.keys()
    if missing:
        raise ValueError(f"Inventory is missing required keys: {missing}")

    # Validate 'data' content
    data_items = inventory["data"]
    if not isinstance(data_items, list):
        raise ValueError("'data' must be a list")
    for idx, item in enumerate(data_items):
        if not isinstance(item, dict):
            raise ValueError(f"Item {idx} in 'data' must be a dict")
        if "id" not in item:
            raise ValueError(f"Item {idx} in 'data' is missing 'id'")
        # Optionally check numeric id
        if not isinstance(item["id"], (int, str)):
            raise ValueError(f"Item {idx} 'id' must be int or str")

    # Validate 'metadata' content
    metadata = inventory["metadata"]
    if not isinstance(metadata, dict):
        raise ValueError("'metadata' must be a dict")
    if "created" not in metadata:
        raise ValueError("'metadata' missing 'created' timestamp")
    # Simple timestamp format check (YYYY-MM-DD)
    import re

    timestamp_re = re.compile(r"^\d{4}-\d{2}-\d{2}$")
    if not isinstance(metadata["created"], str) or not timestamp_re.match(metadata["created"]):
        raise ValueError("'created' timestamp must be in format YYYY-MM-DD")

    # Perform spec-version specific checks
    if spec_version.startswith("3"):
        # For example, inventory must contain 'extra' key
        if "extra" not in inventory:
            raise ValueError(f"Spec version {spec_version} requires an 'extra' key in inventory")
    elif spec_version.startswith("2"):
        # Ensure 'metadata' contains 'version' field
        if "version" not in metadata:
            raise ValueError(f"Spec version {spec_version} requires 'metadata.version' field")

    # Passed all checks
    return True

