def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(digests_used, set):
        digests_used = set(digests_used)
    needed_digests = set()
    for path in manifest_files:
        try:
            with open(path, "r", encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith("#"):
                        continue
                    # Accept common formats: "checksum=sha256:<hash>" or "digest: <hash>"
                    if "=" in line:
                        _, value = line.split("=", 1)
                    elif ":" in line:
                        _, value = line.split(":", 1)
                    else:
                        continue
                    value = value.strip()
                    if value:
                        needed_digests.add(value)
        except FileNotFoundError:
            raise FileNotFoundError(f"Manifest file not found: {path}")
    missing = needed_digests - digests_used
    unused = digests_used - needed_digests
    if missing or unused:
        msg_parts = []
        if missing:
            msg_parts.append(f"Missing digests: {', '.join(sorted(missing))}")
        if unused:
            msg_parts.append(f"Unused digests: {', '.join(sorted(unused))}")
        raise ValueError("; ".join(msg_parts))
    return None

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        present_digests = set()
        for mf in manifest_files:
            try:
                with open(mf, 'r') as f:
                    data = json.load(f)
            except Exception as exc:
                raise RuntimeError(f"Unable to load manifest '{mf}': {exc}")
            if isinstance(data, dict):
                if 'digests' in data:
                    items = data['digests']
                elif 'digest' in data:
                    items = [data['digest']]
                else:
                    continue
                if isinstance(items, list):
                    present_digests.update(items)
                else:
                    present_digests.add(items)
        missing_in_used = present_digests - set(digests_used)
        if missing_in_used:
            raise ValueError(f"Digests found in manifests but never used: {missing_in_used}")
        missing_in_manifest = set(digests_used) - present_digests
        if missing_in_manifest:
            raise ValueError(f"Digests claimed used but absent in all manifests: {missing_in_manifest}")
        return True

def validate_as_prior_version(self, prior):
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an instance of the same validator class")
    # Assuming each validator has a 'version' attribute and an 'inventory' dict
    current_version = getattr(self, "version", None)
    prior_version = getattr(prior, "version", None)
    if current_version is None or prior_version is None:
        raise AttributeError("Both current and prior validators must define a 'version' attribute")
    if prior_version >= current_version:
        raise ValueError(f"Prior version {prior_version} must be less than current version {current_version}")
    current_inventory = getattr(self, "inventory", {})
    prior_inventory = getattr(prior, "inventory", {})
    if not isinstance(current_inventory, dict) or not isinstance(prior_inventory, dict):
        raise TypeError("'inventory' attribute must be a dictionary")
    for key, prior_val in prior_inventory.items():
        if key not in current_inventory:
            raise ValueError(f"Current inventory missing key '{key}' present in prior version")
        curr_val = current_inventory[key]
        if isinstance(curr_val, (int, float)) and isinstance(prior_val, (int, float)):
            if curr_val < prior_val:
                raise ValueError(f"Current inventory value for '{key}' is less than prior value")
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}

    # Helper to compare versions; assumes numeric versions, falls back to string compare
    def version_ge(v1, v2):
        try:
            return int(v1) >= int(v2)
        except Exception:
            return str(v1) >= str(v2)

    for logical_path, data in inventory.items():
        files = set()

        # Case 1: data is a collection of (ver, files) tuples
        if isinstance(data, (list, tuple)):
            for entry in data:
                # entry could be a tuple or dict
                if isinstance(entry, dict):
                    ver = entry.get("version")
                    file_list = entry.get("content_files", [])
                else:
                    # Assume tuple (ver, file_list)
                    if len(entry) == 2:
                        ver, file_list = entry
                    else:
                        continue
                if ver is None:
                    continue
                if version_ge(ver, version):
                    if isinstance(file_list, (list, set, tuple)):
                        files.update(file_list)
                    else:
                        files.add(file_list)

        # Case 2: data is a dict mapping version -> file list
        elif isinstance(data, dict):
            for ver, file_list in data.items():
                if version_ge(ver, version):
                    if isinstance(file_list, (list, set, tuple)):
                        files.update(file_list)
                    else:
                        files.add(file_list)

        # Case 3: data is a set/list of file paths directly
        elif isinstance(data, (set, list, tuple)):
            files.update(data)

        # Skip entries that didn't yield any files
        if files:
            result[logical_path] = files

    return result

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    def _ver_tuple(v):
        """Convert a version string to a tuple of integers for comparison."""
        parts = v.split('.')
        tuple_parts = []
        for part in parts:
            try:
                tuple_parts.append(int(part))
            except ValueError:
                # Non-numeric part: keep as string for lexicographical comparison
                tuple_parts.append(part)
        return tuple(tuple_parts)

    # Prepare sorted list of (version_key, paths_dict) tuples in ascending order
    sorted_versions = sorted(inventory.items(), key=lambda kv: _ver_tuple(kv[0]))

    mapping = {}
    for ver_key, paths_dict in sorted_versions:
        if _ver_tuple(ver_key) > _ver_tuple(version):
            break  # stop at the target version
        # paths_dict is expected to be: logical_path -> iterable of content files
        for logical_path, content_files in paths_dict.items():
            if logical_path not in mapping:
                mapping[logical_path] = set()
            mapping[logical_path].update(content_files)

    return mapping

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_map = {}
    if version not in inventory:
        return logical_map

    # Base mapping for the requested version
    state_map = inventory[version]
    if isinstance(state_map, dict):
        for logical_path, content in state_map.items():
            if isinstance(content, (set, list)):
                logical_map[logical_path] = set(content)
            else:
                logical_map[logical_path] = {content}

    # Add duplicate references from later versions
    versions = list(inventory.keys())
    try:
        idx = versions.index(version)
    except ValueError:
        idx = -1
    for later_version in versions[idx + 1 :]:
        later_state = inventory.get(later_version, {})
        if isinstance(later_state, dict):
            for logical_path, content in later_state.items():
                if isinstance(content, (set, list)):
                    files = set(content)
                else:
                    files = {content}
                if logical_path in logical_map:
                    logical_map[logical_path].update(files)
                else:
                    logical_map[logical_path] = files

    return logical_map

def get_logical_path_map(inventory, version):
    """
    Return a mapping from logical paths defined in the specified version of the inventory
    to the set of content files that belong to that path.  The resulting set will also
    include any duplicate files that show up in later versions of the inventory.

    Parameters
    ----------
    inventory : dict
        Mapping of version identifiers to a dictionary that maps logical paths to
        one or more content file paths.  The precise structure of the nested
        dictionaries is flexible: the value associated with a logical path can
        be a single string, a list/tuple/set of strings, or another dictionary
        whose values are strings.
    version : hashable
        The version that describes the state you are interested in.

    Returns
    -------
    dict
        Keys are logical path strings and values are ``set`` objects containing
        one or more file path strings.
    """
    # Helper to normalise a value that may represent one or many files.
    def _files_to_set(value):
        if isinstance(value, (list, tuple, set)):
            return set(value)
        # If value is a mapping, extract all string values.
        if isinstance(value, dict):
            return {v for v in value.values() if isinstance(v, str)}
        # Primitive value
        if isinstance(value, str):
            return {value}
        # Unexpected type – ignore gracefully.
        return set()

    # If the requested version isn't in the inventory, return an empty mapping.
    if version not in inventory:
        return {}

    # Determine the order of versions: try numeric ordering, fall back to standard
    # lexicographic ordering if conversion fails.  This allows us to iterate
    # over all versions from the given one up through the latest.
    def _sort_key(v):
        try:
            return int(v)
        except Exception:
            return str(v)

    ordered_versions = sorted(inventory.keys(), key=_sort_key)

    # Find the index of the requested version within the ordered list.
    try:
        start_index = ordered_versions.index(version)
    except ValueError:
        # The version isn't present in the ordering list (shouldn't happen).
        return {}

    # Build the result by scanning from the requested version through the rest.
    result = {}
    for v in ordered_versions[start_index:]:
        state_map = inventory.get(v, {})
        if not isinstance(state_map, dict):
            continue
        for logical_path, files_val in state_map.items():
            file_set = _files_to_set(files_val)
            if not file_set:
                continue
            if logical_path in result:
                result[logical_path].update(file_set)
            else:
                # Only include the logical path at the requested version or
                # if it already existed in that version (i.e., duplicates from
                # later versions).
                if v == version or logical_path in inventory[version]:
                    result[logical_path] = set(file_set)
    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Identify the logical paths that exist in the requested version
    base_paths = set()

    # First look for a "states" section keyed by version
    states = inventory.get("states", {})
    if isinstance(states, dict):
        version_state = states.get(version, {})
        if isinstance(version_state, dict):
            for lp in version_state:
                base_paths.add(lp)

    # Fall back to a list of entries if present
    for entry in inventory.get("entries", []):
        if entry.get("version") == version:
            lp = entry.get("logical_path")
            if lp:
                base_paths.add(lp)

    # If no base paths found, return an empty map
    if not base_paths:
        return {}

    # Create the mapping
    path_map = {lp: set() for lp in base_paths}

    # Populate mapping from entries
    for entry in inventory.get("entries", []):
        lp = entry.get("logical_path")
        if lp in path_map:
            files = entry.get("content_file") or entry.get("content_files") or entry.get("file")
            if files:
                if isinstance(files, (list, set, tuple)):
                    path_map[lp].update(files)
                else:
                    path_map[lp].add(files)

    # Populate mapping from states (each version may contain files)
    for ver, state in states.items():
        if isinstance(state, dict):
            for lp, files in state.items():
                if lp in path_map:
                    if isinstance(files, (list, set, tuple)):
                        path_map[lp].update(files)
                    else:
                        path_map[lp].add(files)

    return path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and make sure that only files
    listed in the manifest are referenced.
    """
    # If no fixity block, nothing to validate
    if not fixity:
        return

    # Determine the container of file entries
    if isinstance(fixity, dict):
        files = fixity.get("file", [])
    elif isinstance(fixity, (list, tuple)):
        files = fixity
    else:
        raise ValueError(f"Unexpected type for fixity block: {type(fixity).__name__}")

    # The file entries should be a list/tuple
    if not isinstance(files, (list, tuple)):
        raise ValueError("Fixity block must contain a list of file entries")

    # Normalize manifest to a set for O(1) lookups
    manifest_set = set(manifest_files)

    # Track any file refs that are not in the manifest
    unknown_refs = []

    for entry in files:
        if not isinstance(entry, dict):
            continue  # skip malformed entry
        path = entry.get("path")
        if not path:
            continue  # skip entries without a path
        if path not in manifest_set:
            unknown_refs.append(path)

    if unknown_refs:
        missing = ", ".join(unknown_refs)
        raise ValueError(f"Fixity block references unknown files: {missing}")

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Ensure fixity is a dictionary
        if not isinstance(fixity, dict):
            raise ValueError(f"Fixity block must be a dict, got {type(fixity).__name__}")

        # Build a set of file names present in the manifest
        if isinstance(manifest_files, dict):
            manifest_set = set(manifest_files.keys())
        else:
            try:
                manifest_set = set(manifest_files)
            except Exception as exc:
                raise ValueError("manifest_files must be an iterable or mapping") from exc

        # Verify that every file referenced in the fixity block exists in the manifest
        for file_name in fixity:
            if file_name not in manifest_set:
                raise ValueError(f"File '{file_name}' listed in fixity not found in the manifest")

        # Validate the checksum structure for each file
        for file_name, checksums in fixity.items():
            if not isinstance(checksums, dict):
                raise ValueError(
                    f"Checksum entry for '{file_name}' must be a dict, got {type(checksums).__name__}"
                )
            if 'checksum' not in checksums:
                raise ValueError(f"Checksum entry for '{file_name}' missing required 'checksum' key")
            checksum_val = checksums['checksum']

            # Allow a single checksum string or a dict of algorithms
            if isinstance(checksum_val, str):
                if not all(c in '0123456789abcdefABCDEF' for c in checksum_val):
                    raise ValueError(f"Invalid checksum string for '{file_name}': not hex")
            elif isinstance(checksum_val, dict):
                if not checksum_val:
                    raise ValueError(f"No checksums specified for '{file_name}'")
                for algo, val in checksum_val.items():
                    if not isinstance(val, str) or not val:
                        raise ValueError(
                            f"Checksum for algorithm '{algo}' of file '{file_name}' must be a non-empty string"
                        )
                    if not all(c in '0123456789abcdefABCDEF' for c in val):
                        raise ValueError(
                            f"Invalid checksum value for algorithm '{algo}' of file '{file_name}': not hex"
                        )
            else:
                raise ValueError(f"Checksum for '{file_name}' must be a string or dict")

        # If all validations pass, the method completes without error.

def validate_fixity(self, fixity, manifest_files):
        """
        Validate the structure of a fixity block and ensure that
        it only references files present in the manifest.

        :param fixity: dict representing a fixity entry.
        :param manifest_files: iterable of file paths included in the manifest.
        :raises ValueError: if the fixity block is malformed or refers to
                            an unknown file.
        :return: True if validation passes.
        """
        # Normalise manifest for fast lookup
        if isinstance(manifest_files, (list, tuple)):
            manifest_set = set(manifest_files)
        else:
            manifest_set = frozenset(manifest_files)

        if not isinstance(fixity, dict):
            raise ValueError(f"Fixity block must be a dict, got {type(fixity).__name__}")

        # Required keys
        required_keys = {"file_path", "hashes"}
        missing = required_keys - fixity.keys()
        if missing:
            raise ValueError(f"Fixity block missing required keys: {missing}")

        file_path = fixity["file_path"]
        if not isinstance(file_path, str):
            raise ValueError(f"'file_path' must be a string, got {type(file_path).__name__}")

        if file_path not in manifest_set:
            raise ValueError(f"Fixity block references unknown file: '{file_path}'")

        hashes = fixity["hashes"]
        if not isinstance(hashes, list):
            raise ValueError(f"'hashes' must be a list, got {type(hashes).__name__}")

        if not hashes:
            raise ValueError("No hash entries provided in fixity block")

        allowed_algos = {"md5", "sha1", "sha256", "sha512"}
        for idx, h in enumerate(hashes):
            if not isinstance(h, dict):
                raise ValueError(f"Hash entry #{idx} is not a dict")
            if "algorithm" not in h or "value" not in h:
                raise ValueError(f"Hash entry #{idx} missing 'algorithm' or 'value' keys")
            algo = h["algorithm"]
            value = h["value"]
            if not isinstance(algo, str):
                raise ValueError(f"'algorithm' in hash entry #{idx} must be string")
            if algo.lower() not in allowed_algos:
                raise ValueError(f"Unsupported hash algorithm '{algo}' in entry #{idx}")
            if not isinstance(value, str) or not value:
                raise ValueError(f"'value' in hash entry #{idx} must be a non-empty string")

        # All checks passed
        return True

