def _group_files_by_xml_filename(source, xmls, files):
    import os
    grouping = {}
    # Ensure file lookup is efficient
    files_set = set(files)

    for xml in xmls:
        # Normalize xml path relative to source
        xml_path = os.path.join(source, xml) if source else xml
        base = os.path.splitext(os.path.basename(xml_path))[0]
        matched = [xml_path]

        for f in files_set:
            if f == xml:
                continue
            f_path = os.path.join(source, f) if source else f
            if os.path.splitext(os.path.basename(f_path))[0] == base:
                matched.append(f_path)

        grouping[base] = matched

    return grouping

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Mapping from the basename of each XML file to a dictionary with keys:
        - 'xml' : full path to the XML file
        - 'refs' : list of full paths to all other files that share that basename
    """
    data = {}
    for root, _, files in os.walk(folder):
        for filename in files:
            base, ext = os.path.splitext(filename)
            full_path = os.path.join(root, filename)
            if base not in data:
                data[base] = {'xml': None, 'refs': []}
            if ext.lower() == ".xml":
                data[base]['xml'] = full_path
            else:
                data[base]['refs'].append(full_path)
    # Remove entries that have no XML file (if any)
    return {k: v for k, v in data.items() if v['xml'] is not None}

def _eval_file(prefix, file_path):
    import os
    # Get file extension
    _, ext = os.path.splitext(file_path)
    ext = ext.lower()
    # Define which extensions correspond to renditions
    rendition_extensions = {'.png', '.jpg', '.jpeg', '.gif', '.bmp', '.tiff', '.svg'}
    # Default to asset if not a known rendition extension
    file_type = 'rendition' if ext in rendition_extensions else 'asset'
    # Build return dictionary
    result = {'type': file_type, 'path': file_path}
    # Update global packages structure if it exists
    try:
        pkg = globals().get('packages')
        if pkg is not None:
            pkg.setdefault(file_type, []).append({'prefix': prefix, 'path': file_path})
    except Exception:
        pass  # ignore if packages is not available
    return result

def add_rendition(self, lang, file_path):
        """
        Register a rendition for a given language.
        The mapping will be stored internally as a dictionary where
        keys are language codes (including 'original') and values
        are file paths. Example:
            self._renditions = {
                'original': 'artigo02.pdf',
                'en': 'artigo02-en.pdf',
            }
        """
        # Ensure the renditions storage is initialized
        if not hasattr(self, "_renditions"):
            self._renditions = {}

        # Store the file path for the specified language key
        self._renditions[lang] = str(file_path)

def add_rendition(self, lang, file_path):
        """
        {
            "original": "artigo02.pdf",
            "en": "artigo02-en.pdf",
        }
        """
        # Ensure renditions dictionary exists
        if not hasattr(self, 'renditions'):
            self.renditions = {}
        # Extract filename component
        import os
        basename = os.path.basename(file_path)
        name, ext = os.path.splitext(basename)
        # Attempt to strip language suffix (e.g., "-en")
        parts = name.split('-')
        if parts and parts[-1] == lang:
            original_name = '-'.join(parts[:-1])
        else:
            original_name = name
        original_file = original_name + ext
        # Store the rendition mapping
        if original_file not in self.renditions:
            self.renditions[original_file] = {}
        self.renditions[original_file][lang] = file_path.

