    for xpath in pubdate_xpaths:
        try:
            results = node.xpath(xpath)
        except Exception:
            continue
        if results:
            first = results[0]
            try:
                # Return text of the matched element if possible
                return first.text
            except Exception:
                # If not an Element, just return its string representation
                return str(first)
    return None

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            results = node.xpath(xpath)
        except Exception:
            continue
        if results:
            first = results[0]
            # If it's an element node, get its text content
            if hasattr(first, "text_content"):
                return first.text_content().strip()
            elif hasattr(first, "text"):
                return first.text.strip()
            else:
                return str(first).strip()
    return None

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    pad = ' ' * (indent * 4)
    lines = []
    for key, val in sorted(vars(self).items()):
        if hasattr(val, 'pretty'):
            val_str = val.pretty(indent + 1, debug)
        elif isinstance(val, (list, tuple, set)):
            inner_pad = ' ' * ((indent + 1) * 4)
            items = []
            for item in val:
                if hasattr(item, 'pretty'):
                    items.append(item.pretty(indent + 2, debug))
                else:
                    items.append(repr(item))
            val_str = f'{type(val).__name__}([' + ',\n' + inner_pad + ',\n' + inner_pad + ']'
        else:
            val_str = repr(val)
        lines.append(f'{pad}    {key}={val_str}')
    content = '\n'.join(lines)
    return f'{pad}{self.__class__.__name__}(\n{content}\n{pad})'

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    import pprint
    if debug:
        header = f"{' ' * indent}<{self.__class__.__name__} id={id(self)}>"
        body = pprint.pformat(self.__dict__, indent=indent + 2)
        return f"{header}\n{body}"
    return pprint.pformat(self.__dict__, indent=indent)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    if debug:
        header = f'{indent_str}{self.__class__.__name__}@{id(self):#x}'
    else:
        header = f'{indent_str}{self.__class__.__name__}'

    # Helper to format nested values
    def _format(value, current_indent):
        if hasattr(value, 'pretty') and callable(getattr(value, 'pretty')):
            return value.pretty(current_indent, debug)
        elif isinstance(value, dict):
            items = []
            for k, v in value.items():
                k_str = repr(k)
                v_str = _format(v, current_indent + 4)
                items.append(' ' * (current_indent + 4) + f'{k_str}: {v_str}')
            return '{\n' + ',\n'.join(items) + f'\n{" " * current_indent}' + '}'
        elif isinstance(value, (list, tuple, set, frozenset)):
            opening = '[' if isinstance(value, list) else '(' if isinstance(value, tuple) else '{'
            closing = ']' if isinstance(value, list) else ')' if isinstance(value, tuple) else '}'
            items = [_format(v, current_indent + 4) for v in value]
            return opening + '\n' + ',\n'.join(' ' * (current_indent + 4) + item for item in items) + f'\n{" " * current_indent}' + closing
        else:
            return repr(value)

    if hasattr(self, '__dict__'):
        attrs = []
        for key, val in self.__dict__.items():
            val_str = _format(val, indent + 4)
            attrs.append(' ' * (indent + 4) + f'{key} = {val_str}')
        body = '\n' + ',\n'.join(attrs) + f'\n{indent_str}'
        return header + '(' + body + ')'
    else:
        # Fallback for objects without __dict__
        return header + '(' + repr(self) + ')'

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    lines = []
    ind = "    " * indent
    lines.append(f"{ind}{self.__class__.__name__}")
    for attr, val in sorted(self.__dict__.items()):
        if hasattr(val, "pretty") and callable(val.pretty):
            if debug:
                lines.append(f"{ind}    {attr} = (type={type(val).__name__}, id={id(val)})")
                lines.append(val.pretty(indent + 1, debug))
            else:
                lines.append(f"{ind}    {attr} =")
                lines.append(val.pretty(indent + 2, debug))
        elif isinstance(val, (list, tuple)):
            lines.append(f"{ind}    {attr} = [")
            for item in val:
                if hasattr(item, "pretty") and callable(item.pretty):
                    lines.append(item.pretty(indent + 3, debug))
                else:
                    lines.append(f"{ind}        {repr(item)}")
            lines.append(f"{ind}    ]")
        elif isinstance(val, dict):
            lines.append(f"{ind}    {attr} = {{")
            for k, v in val.items():
                if hasattr(v, "pretty") and callable(v.pretty):
                    lines.append(f"{ind}        {repr(k)}: ")
                    lines.append(v.pretty(indent + 3, debug))
                else:
                    lines.append(f"{ind}        {repr(k)}: {repr(v)}")
            lines.append(f"{ind}    }}")
        else:
            if debug:
                lines.append(f"{ind}    {attr} = {repr(val)} (type={type(val).__name__}, id={id(val)})")
            else:
                lines.append(f"{ind}    {attr} = {repr(val)}")
    return "\n".join(lines)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    lines = [f"{indent_str}{self.__class__.__name__}:"]
    if debug:
        lines.append(f"{indent_str}  <debug: id={id(self)}>")
    for key, value in sorted(vars(self).items()):
        val_repr = repr(value)
        lines.append(f"{indent_str}  {key} = {val_repr}")
    return '\n'.join(lines)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def _simplify(expr):
        # If expression is atomic, return it unchanged
        if not hasattr(expr, "args") or not hasattr(expr, "func"):
            return expr

        # Recursively simplify arguments
        new_args = tuple(_simplify(arg) for arg in expr.args)

        # If the expression is a logical binary operator
        if expr.func in (And, Or):
            # Ensure we work with simplified arguments
            left, right = new_args[0], new_args[1]

            # Identity: A & A or A | A -> A
            if left == right:
                return left

            # Absorption: A & (A | B) or (A | B) & A
            if expr.func is And:
                # pattern A & (A | B)
                if hasattr(right, "func") and right.func is Or:
                    if left == right.args[0] or left == right.args[1]:
                        return left
                # pattern (A | B) & A
                if hasattr(left, "func") and left.func is Or:
                    if right == left.args[0] or right == left.args[1]:
                        return right
                # Negative absorption: A & (~A | B) -> A & B
                if hasattr(right, "func") and right.func is Or:
                    # Check if left is a negation of one child of right
                    if hasattr(left, "func") and left.func is Not and right.args[0] == left.args[0]:
                        return And(left.args[0], right.args[1])
                    if hasattr(left, "func") and left.func is Not and right.args[1] == left.args[0]:
                        return And(left.args[0], right.args[0])
                if hasattr(left, "func") and left.func is Or:
                    if hasattr(right, "func") and right.func is Not and left.args[0] == right.args[0]:
                        return And(right.args[0], left.args[1])
                    if hasattr(right, "func") and right.func is Not and left.args[1] == right.args[0]:
                        return And(right.args[0], left.args[0])
            elif expr.func is Or:
                # Absorption: A | (A & B)
                if hasattr(right, "func") and right.func is And:
                    if left == right.args[0] or left == right.args[1]:
                        return left
                if hasattr(left, "func") and left.func is And:
                    if right == left.args[0] or right == left.args[1]:
                        return right
                # Negative absorption: A | (~A & B) -> A | B
                if hasattr(right, "func") and right.func is And:
                    if hasattr(left, "func") and left.func is Not and right.args[0] == left.args[0]:
                        return Or(left.args[0], right.args[1])
                    if hasattr(left, "func") and left.func is Not and right.args[1] == left.args[0]:
                        return Or(left.args[0], right.args[0])
                if hasattr(left, "func") and left.func is And:
                    if hasattr(right, "func") and right.func is Not and left.args[0] == right.args[0]:
                        return Or(right.args[0], left.args[1])
                    if hasattr(right, "func") and right.func is Not and left.args[1] == right.args[0]:
                        return Or(right.args[0], left.args[0])

            # If no absorption applied, rebuild the expression with possibly simplified args
            if new_args != expr.args:
                return expr.func(*new_args)
            return expr

        # For all other expressions, rebuild if any subexpression changed
        if new_args != expr.args:
            return expr.func(*new_args)
        return expr

    return [_simplify(arg) for arg in args]

def absorb(self, args):
    """
    Applies absorption and negative absorption to a sequence of boolean expressions.
    The method supports SymPy expressions for logical operators. It returns a new list
    of expressions with the simplifications applied.
    """
    # Helper that applies absorption once to a single expression
    def _absorb_once(expr):
        # Only attempt when expr is a binary operation (And, Or) with arguments
        if not hasattr(expr, "args") or not hasattr(expr, "func"):
            return expr

        # Reduce subexpressions first
        reduced_args = tuple(_absorb_once(a) for a in expr.args)
        if reduced_args != expr.args:
            expr = expr.func(*reduced_args)

        # Extract the function name for quick checks
        func = expr.func

        # Absorption for AND
        if func == And:
            # Check for A & (A | B)
            for left, right in ((l, r) for l in expr.args for r in expr.args if l != r):
                if getattr(right, "func", None) == Or and left in right.args:
                    return left
                # Negative absorption: A & (~A | B) = A & B
                if getattr(right, "func", None) == Or:
                    not_terms = [a for a in right.args if isinstance(a, Not)]
                    # if negative of left appears
                    if any(n.args[0] == left for n in not_terms):
                        # remaining terms besides the Not
                        remaining = [a for a in right.args if a not in not_terms]
                        if not remaining:
                            return left
                        return And(left, *remaining)

        # Absorption for OR
        if func == Or:
            # Check for A | (A & B)
            for left, right in ((l, r) for l in expr.args for r in expr.args if l != r):
                if getattr(right, "func", None) == And and left in right.args:
                    return left
                # Negative absorption: A | (~A & B) = A | B
                if getattr(right, "func", None) == And:
                    not_terms = [a for a in right.args if isinstance(a, Not)]
                    if any(n.args[0] == left for n in not_terms):
                        remaining = [a for a in right.args if a not in not_terms]
                        if not remaining:
                            return left
                        return Or(left, *remaining)

        return expr

    # Apply absorption to each expression in the list
    return [_absorb_once(e) for e in args]

def on(self, hook):
    def decorator(func):
        if not hasattr(self, "_registry"):
            self._registry = {}
        self._registry.setdefault(hook, []).append(func)
        return func
    return decorator

def normalized(self):
    import math
    attrs = {}
    # copy current attributes
    for key in ("years", "months", "weeks", "days", "hours", "minutes", "seconds", "microseconds"):
        val = getattr(self, key, None)
        if val is None:
            continue
        attrs[key] = val
    # Normalize days to hours
    if "days" in attrs:
        days_val = attrs.pop("days")
        whole, frac = math.modf(days_val)
        attrs["days"] = int(whole)
        attrs["hours"] = attrs.get("hours", 0) + frac * 24
    # Normalize hours to minutes
    if "hours" in attrs:
        h_val = attrs.pop("hours")
        whole, frac = math.modf(h_val)
        attrs["hours"] = int(whole)
        attrs["minutes"] = attrs.get("minutes", 0) + frac * 60
    # Normalize minutes to seconds
    if "minutes" in attrs:
        m_val = attrs.pop("minutes")
        whole, frac = math.modf(m_val)
        attrs["minutes"] = int(whole)
        attrs["seconds"] = attrs.get("seconds", 0) + frac * 60
    # Normalize seconds to microseconds
    if "seconds" in attrs:
        s_val = attrs.pop("seconds")
        whole, frac = math.modf(s_val)
        attrs["seconds"] = int(whole)
        attrs["microseconds"] = attrs.get("microseconds", 0) + frac * 1e6
    # Drop remaining fractional microseconds
    if "microseconds" in attrs:
        mu_val = attrs.pop("microseconds")
        whole, _ = math.modf(mu_val)
        attrs["microseconds"] = int(whole)
    # Build result, omitting zero values unless they are underspecified
    result_kwargs = {
        k: v
        for k, v in attrs.items()
        if v != 0 or k in ("days", "hours", "minutes", "seconds", "microseconds")
    }
    return type(self)(**result_kwargs)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        # If `unicode` is not defined, we are on Python 3
        unicode
    except NameError:
        return namefunc
    def wrapper(*args, **kwargs):
        name = namefunc(*args, **kwargs)
        if isinstance(name, unicode):
            return name.encode('utf-8')
        return name
    return wrapper

