    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper(*args, **kwargs):
        val = namefunc(*args, **kwargs)
        try:
            # In Python 2, unicode objects need to be encoded to bytes
            if isinstance(val, unicode):
                return val.encode('utf-8')
        except NameError:
            # In Python 3, unicode type does not exist; leave value unchanged
            pass
        return val
    return wrapper

