def get_versions():
    """Get version information or return default if unable to do so."""
    result = {
        'full-revisionid': None,
        'dirty': False,
        'version': '0.0.0',
    }
    try:
        # Prefer importlib.metadata if available
        from importlib.metadata import version as _im_version, PackageNotFoundError
        try:
            pkg_name = __package__ if __package__ else __name__
            result['version'] = _im_version(pkg_name)
        except PackageNotFoundError:
            # Fall back to pkg_resources
            try:
                import pkg_resources
                pkg_name = __package__ if __package__ else __name__
                result['version'] = pkg_resources.get_distribution(pkg_name).version
            except Exception:
                pass
        # Try to fetch the full git revision and dirty state if on a git repo
        try:
            import subprocess, os
            cwd = os.path.dirname(__file__) or '.'
            result['full-revisionid'] = subprocess.check_output(
                ['git', 'rev-parse', 'HEAD'],
                cwd=cwd,
                stderr=subprocess.DEVNULL
            ).decode().strip()
            status = subprocess.check_output(
                ['git', 'status', '--porcelain'],
                cwd=cwd,
                stderr=subprocess.DEVNULL
            ).decode().strip()
            result['dirty'] = bool(status)
        except Exception:
            pass
    except Exception:
        pass
    return result

def get_versions():
    """
    Get version information or return a default value if unable to obtain it.
    """
    try:
        sys = __import__("sys")
        platform = __import__("platform")
        importlib_metadata = __import__("importlib.metadata") if True else None

        versions = {
            "python": sys.version,
            "python_version": sys.version_info[:],
            "platform": platform.platform(),
            "architecture": sys.maxsize.bit_length(),
        }

        # Try to get the git commit hash if available
        try:
            # __import__ can load a module; use subprocess to run git
            subprocess = __import__("subprocess")
            commit = subprocess.check_output(["git", "rev-parse", "HEAD"], stderr=subprocess.DEVNULL)
            versions["git_commit"] = commit.decode().strip()
        except Exception:
            versions["git_commit"] = None

        # Try to get versions of commonly used libraries
        for lib in ("numpy", "pandas", "scipy"):
            try:
                mod = __import__(lib)
                versions[f"{lib}_version"] = getattr(mod, "__version__", None)
            except Exception:
                versions[f"{lib}_version"] = None

        return versions
    except Exception:
        # If anything fails, return a simple default structure
        return {"default": True}

def get_versions():
    """Get version information or return default if unable to do so."""
    default = {"full": "0+unknown", "base": "0", "dirty": False}
    try:
        try:
            from importlib.metadata import version
        except Exception:
            from importlib_metadata import version
        pkg_name = __name__.split(".")[0]
        ver = version(pkg_name)
        base = ver.split("+")[0]
        return {"full": ver, "base": base, "dirty": False}
    except Exception:
        return default

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Python 3.8+ provides importlib.metadata
        from importlib.metadata import version, PackageNotFoundError
        package_name = __name__.partition('.')[0]
        return version(package_name)
    except Exception:
        try:
            # Fallback to pkg_resources for older environments
            import pkg_resources
            return pkg_resources.get_distribution(__name__.partition('.')[0]).version
        except Exception:
            # Default value if all attempts fail
            return "0+unknown"

def get_versions():
    """
    Get version information or return default if unable to determine.
    Returns a dictionary with 'version' (str) and 'commit' (str or None).
    The function first attempts to query Git metadata; if that fails, it falls back
    to a predefined default value.
    """
    import subprocess
    # Default version info if we cannot determine the real value
    default = {"version": "0+unknown", "commit": None}
    try:
        # Get the short commit hash
        short_hash = subprocess.check_output(
            ["git", "rev-parse", "--short", "HEAD"],
            stderr=subprocess.DEVNULL,
        ).decode().strip()
    except Exception:
        # Not a git repository or git not available
        return default

    # Attempt to get an exact tag pointing at HEAD
    try:
        tag = subprocess.check_output(
            ["git", "describe", "--tags", "--exact-match"],
            stderr=subprocess.DEVNULL,
        ).decode().strip()
        version = tag
    except Exception:
        # Fallback: use descriptive reference (tag or abbreviated commit hash)
        try:
            describe = subprocess.check_output(
                ["git", "describe", "--tags", "--dirty", "--always"],
                stderr=subprocess.DEVNULL,
            ).decode().strip()
            version = describe
        except Exception:
            # If all else fails, use the commit hash as the version
            version = short_hash

    return {"version": version, "commit": short_hash}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Normalize pieces to dictionary
    if isinstance(pieces, dict):
        v = pieces
    else:
        keys = ("major", "minor", "patch", "prerelease", "build")
        v = {k: pieces[i] if i < len(pieces) else "" for i, k in enumerate(keys)}

    major = str(v.get("major", "0"))
    minor = str(v.get("minor", "0"))
    patch = str(v.get("patch", "0"))
    prerelease = v.get("prerelease", "")
    build = v.get("build", "")

    # Semver style
    if style == "semver":
        base = f"{major}.{minor}.{patch}"
        result = base
        if prerelease:
            result += f"-{prerelease}"
        if build:
            result += f"+{build}"
        return result

    # PEP 440 style
    if style == "pep440":
        base = f"{major}.{minor}"
        if patch and patch != "0":
            base += f".{patch}"
        result = base
        if prerelease:
            mapping = {"alpha": "a", "beta": "b", "rc": "rc"}
            for key, val in mapping.items():
                if prerelease.startswith(key):
                    suffix = prerelease[len(key):]
                    result += f"{val}{suffix}"
                    break
        return result

    # Compact style (omit trailing zeros)
    if style == "compact":
        parts = [major]
        if minor or patch:
            parts.append(minor)
        if patch:
            parts.append(patch)
        result = ".".join(parts)
        if prerelease:
            result += f"-{prerelease}"
        if build:
            result += f"+{build}"
        return result

    # Default to full semver representation
    base = f"{major}.{minor}.{patch}"
    result = base
    if prerelease:
        result += f"-{prerelease}"
    if build:
        result += f"+{build}"
    return result

def render(pieces, style):
    """
    Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : Sequence[int]
        The individual numeric components of a version, e.g. [1, 2, 3].
    style : str | callable
        Defines how the pieces are formatted. Supported string values:
        - 'semantic': dot‑separated, trailing zeros omitted (e.g. 1.2 → "1.2").
        - 'full': all pieces are rendered regardless of trailing zeros.
        - 'short': only the first component is returned.
        - 'numeric': tuple representation like "(1, 2, 3)".
        If a callable is provided, it receives the list of pieces and should return a string.

    Returns
    -------
    str
        The formatted version string.
    """
    if pieces is None:
        raise ValueError("pieces cannot be None")
    if not isinstance(pieces, (list, tuple)):
        raise TypeError("pieces must be a list or tuple of integers")
    if not all(isinstance(p, int) for p in pieces):
        raise TypeError("all elements in pieces must be integers")

    # Default style if not specified
    if style is None:
        style = "semantic"

    # If a callable formatting function is supplied, delegate to it
    if callable(style):
        return style(pieces)

    if not isinstance(style, str):
        raise TypeError("style must be a string or a callable")

    style = style.lower()

    if style == "semantic":
        # Remove trailing zeros to mimic semantic versioning
        trimmed = list(pieces)
        while trimmed and trimmed[-1] == 0:
            trimmed.pop()
        if not trimmed:
            return "0"
        return ".".join(str(p) for p in trimmed)

    if style == "full":
        return ".".join(str(p) for p in pieces)

    if style == "short":
        return str(pieces[0]) if pieces else ""

    if style == "numeric":
        return str(tuple(pieces))

    raise ValueError(f"Unsupported style: {style}")

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if style == "json":
        import json
        return json.dumps(pieces, indent=2, sort_keys=True)
    elif style == "yaml" or style == "yml":
        try:
            from yaml import safe_dump
            return safe_dump(pieces, default_flow_style=False, sort_keys=True)
        except Exception:
            # Fallback if PyYAML isn't available
            return str(pieces)
    elif style == "plain":
        lines = []
        for key, value in pieces.items():
            lines.append(f"{key}: {value}")
        return "\n".join(lines)
    else:
        # Default to plain string representation
        return str(pieces)

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if style == "plain":
        # plain text: just concatenate the pieces
        return "".join(pieces)
    elif style == "html":
        # wrap each piece in a span element for HTML output
        return "".join(f"<span>{p}</span>" for p in pieces)
    elif style == "markdown":
        # place each piece on its own line for simple markdown
        return "\n".join(pieces)
