def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Execute the specified command(s) with given arguments.
    `commands` may be a string or a list of command parts. `args` should be a list of arguments.
    Returns a subprocess.CompletedProcess instance.
    """
    import subprocess

    # Build full command list
    if isinstance(commands, str):
        cmd = [commands] + list(args)
    else:
        cmd = list(commands) + list(args)

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as exc:
        # If verbose, show error output
        if verbose:
            if not hide_stderr and exc.stderr:
                print(exc.stderr, end='')
            print(f"\nCommand {exc.cmd} failed with exit code {exc.returncode}")
        raise

    # Optional verbose output
    if verbose:
        if result.stdout:
            print(result.stdout, end='')
        if result.stderr and not hide_stderr:
            print(result.stderr, end='')

    return result

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list, ensuring it's a list of str
    if args is None:
        args = []
    if isinstance(commands, str):
        cmd = [commands] + list(args)
    else:
        cmd = list(commands) + list(args)

    # Setup environment variables
    env_vars = None
    if env is not None:
        env_vars = os.environ.copy()
        env_vars.update(env)

    # Configure stderr handling
    stderr_pipe = subprocess.PIPE if not hide_stderr else subprocess.DEVNULL

    if verbose:
        print(f"Running command: {' '.join(cmd)}")
        if cwd:
            print(f"Working directory: {cwd}")

    try:
        proc = subprocess.Popen(
            cmd,
            cwd=cwd,
            env=env_vars,
            stdout=subprocess.PIPE,
            stderr=stderr_pipe,
            text=True
        )
        stdout, stderr = proc.communicate()
        if proc.returncode != 0:
            err_msg = f"Command '{' '.join(cmd)}' exited with code {proc.returncode}"
            if not hide_stderr and stderr:
                err_msg += f"\nStderr: {stderr}"
            if verbose:
                print(err_msg)
            raise RuntimeError(err_msg)
        if verbose:
            print(f"Command succeeded. Output:\n{stdout}")
        return stdout
    except FileNotFoundError as e:
        raise RuntimeError(f"Executable not found: {commands}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to run command '{' '.join(cmd)}': {e}") from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
