        cmd = ' '.join(map(str, commands))
    else:
        cmd = str(commands)
    if args:
        if isinstance(args, (list, tuple)):
            cmd += ' ' + ' '.join(map(str, args))
        else:
            cmd += ' ' + str(args)
    if verbose:
        print(f"Running: {cmd}", file=sys.stderr)
    result = subprocess.run(
        cmd,
        shell=True,
        cwd=cwd,
        env=env,
        capture_output=True,
        text=True
    )
