    elif hasattr(self, 'children'):
        objs = getattr(self, 'children')
    else:
        # If no obvious container, assume the instance itself is a single object
        objs = [self]

    # Normalise to a sequence
    if isinstance(objs, dict):
        objs = list(objs.values())
    elif not isinstance(objs, (list, tuple)):
        objs = [objs]

