        # Validate the object if requested
        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    is_valid = obj.validate()
                elif hasattr(obj, 'is_valid'):
                    is_valid = obj.is_valid()
                # If no explicit validation method, assume valid
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Warning: failure during object validation of {obj!r}: {exc}")

