def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os, json, hashlib

    # Locate the storage root directory; fall back to an attribute named 'storage_root' or 'root'.
    root = getattr(self, "storage_root", None) or getattr(self, "root", None)
    if not root or not os.path.isdir(root):
        raise ValueError("Storage root directory is not defined or does not exist.")

    num_objects = 0
    good_objects = 0
    warnings = []

    # Walk through the directory tree
    for dirpath, dirnames, filenames in os.walk(root):
        for fname in filenames:
            # Skip hidden files or special meta files if any
            if fname.startswith("."):
                continue

            path = os.path.join(dirpath, fname)
            num_objects += 1

            try:
                # Attempt to read the object content
                with open(path, "r", encoding="utf-8") as f:
                    try:
                        data = json.load(f)
                    except Exception:
                        # If the file is not JSON, treat it as a raw object
                        data = None

                valid = True

                # Optional object validation
                if validate_objects:
                    validator = getattr(self, "validate_object", None)
                    if validator and data is not None:
                        # If a custom validator returns False, mark as invalid
                        if not validator(data):
                            valid = False

                # Optional digest check
                if check_digests:
                    stored_digest = None
                    if isinstance(data, dict):
                        stored_digest = data.get("digest")
                    if stored_digest:
                        hasher = hashlib.sha256()
                        with open(path, "rb") as fh:
                            for chunk in iter(lambda: fh.read(8192), b""):
                                hasher.update(chunk)
                        computed_digest = hasher.hexdigest()
                        if computed_digest != stored_digest:
                            warnings.append(f"Digest mismatch for {path}")
                            valid = False

                if valid:
                    good_objects += 1

            except Exception as exc:
                warnings.append(f"Error validating {path}: {exc}")

    # Print warnings if requested
    if show_warnings and warnings:
        for warn in warnings:
            print(warn)

    return num_objects, good_objects

