def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os, json, errno

    # Determine the root path from common attribute names
    root_path = getattr(self, "root_path", None)
    if root_path is None:
        root_path = getattr(self, "path", None)
    if root_path is None:
        raise AttributeError("No root path attribute defined on the object (expected 'root_path' or 'path').")

    root_path = os.path.abspath(root_path)

    # Create the root directory if it doesn't exist
    try:
        os.makedirs(root_path, exist_ok=True)
    except OSError as exc:
        if exc.errno != errno.EEXIST:
            raise

    # Create the OCFL internal directory
    ocfl_dir = os.path.join(root_path, ".ocfl")
    try:
        os.makedirs(ocfl_dir, exist_ok=True)
    except OSError as exc:
        if exc.errno != errno.EEXIST:
            raise

    # Write a minimal OCFL configuration file
    config_path = os.path.join(ocfl_dir, "ocfl.json")
    if not os.path.exists(config_path):
        config = {
            "ocflVersion": "1.0",
            "format": "ocfl",
            "checksumAlgorithm": "sha256"
        }
        with open(config_path, "w", encoding="utf-8") as f:
            json.dump(config, f, indent=4)

    # Create the objects root directory (where individual objects will be stored)
    objects_dir = os.path.join(root_path, "objects")
    try:
        os.makedirs(objects_dir, exist_ok=True)
    except OSError as exc:
        if exc.errno != errno.EEXIST:
            raise

    # Optional: Create a lock file to signal the root is initialized
    lock_path = os.path.join(ocfl_dir, "storage.lock")
    if not os.path.exists(lock_path):
        with open(lock_path, "w", encoding="utf-8") as f:
            f.write("OCFL storage root initialized.\n")

    # Store an internal flag for future reference
    self._initialized = True
    return True

def next_version(version):
    """Next version identifier following existing pattern.
    Works for both zero‑prefixed (e.g. '007') and non‑zero‑prefixed (e.g. '123') numeric strings.
    """
    if not isinstance(version, str):
        raise TypeError('Version must be a string')
    if not version.isdigit():
        raise ValueError('Version must contain only digits')
    # Compute next numeric value
    next_num = int(version) + 1
    # Preserve original width (zero‑padding) when appropriate
    width = len(version)
    return str(next_num).zfill(width)

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Root inventory must already be loaded into self.root_inventory as a dict {path: digest}
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise RuntimeError("Root inventory not available or in wrong format")

    seen_paths = set()
    mismatched_digests = {}

    for vdir in version_dirs:
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory.json in version directory '{vdir}'")

        with open(inv_path, "r", encoding="utf-8") as f:
            inv_data = json.load(f)

        # Handle two common inventory formats:
        # 1) a list of objects: [{ "path": "...", "digest": "..." }, ...]
        # 2) a mapping { "path": "<digest>", ... }
        if isinstance(inv_data, dict):
            current_paths = set(inv_data.keys())
            digests = inv_data
        elif isinstance(inv_data, list):
            current_paths = set()
            digests = {}
            for entry in inv_data:
                if not isinstance(entry, dict) or "path" not in entry or "digest" not in entry:
                    raise ValueError(f"Invalid inventory entry in '{inv_path}': {entry}")
                current_paths.add(entry["path"])
                digests[entry["path"]] = entry["digest"]
        else:
            raise ValueError(f"Unknown inventory structure in '{inv_path}'")

        # Ensure that this version's inventory includes all items from previous versions
        missing_earlier = seen_paths - current_paths
        if missing_earlier:
            raise ValueError(
                f"Inventory '{vdir}' missing items present in earlier versions: {sorted(missing_earlier)}"
            )

        # Update the set of seen paths
        seen_paths.update(current_paths)

        # Record mismatched digests relative to root inventory
        for path, digest in digests.items():
            root_digest = self.root_inventory.get(path)
            if root_digest is not None and root_digest != digest:
                mismatched_digests[path] = (root_digest, digest)

    # Store mismatched digests for later validation
    self.mismatched_digests = mismatched_digests
    return mismatched_digests

