def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure the root inventory has been loaded
    if not hasattr(self, 'root_inventory') or not isinstance(self.root_inventory, dict):
        raise RuntimeError('Root inventory is not set or not a dictionary')

    # Root path containing the version directories
    if not hasattr(self, 'root_path'):
        raise AttributeError('root_path attribute must be defined on self')

    # Keep record of digests that differ from the root inventory
    self.different_digests = {}
    # Cumulative set of items seen so far (path -> digest)
    cumulative = {}

    for ver_dir in version_dirs:
        inv_path = os.path.join(self.root_path, ver_dir, 'inventory.json')
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f'Missing inventory in version directory: {ver_dir}')

        with open(inv_path, 'r', encoding='utf-8') as f:
            try:
                inv_data = json.load(f)
            except Exception as e:
                raise ValueError(f'Failed to parse inventory in {ver_dir}: {e}')

        if not isinstance(inv_data, dict):
            raise ValueError(f'Inventory in {ver_dir} must be a JSON object mapping paths to digests')

        # Ensure all previous items are present in the current inventory
        missing_items = set(cumulative) - set(inv_data)
        if missing_items:
            missing = ', '.join(sorted(missing_items))
            raise ValueError(f'Inventory in {ver_dir} missing previous items: {missing}')

        # Compare digests with the root inventory and record differences
        for path, digest in inv_data.items():
            root_digest = self.root_inventory.get(path)
            if root_digest is not None and digest != root_digest:
                self.different_digests.setdefault(path, []).append(
                    (ver_dir, digest, root_digest)
                )

        # Update cumulative inventory
        cumulative.update(inv_data)
