import os, glob

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if os.path.isfile(path):
        return 'file'
    if not os.path.isdir(path):
        return f'not a directory: {path}'
    # Find Namaste files (0=*)
    namaste_files = glob.glob(os.path.join(path, "0=*"))
    if not namaste_files:
        # Directory has no Namaste file
        items = os.listdir(path)
        if not items:
            return f'empty directory: {path}'
        return f'no Namaste file (0=*) found in {path}'
    if len(namaste_files) > 1:
        return f'multiple Namaste files found in {path}: {namaste_files}'
    # Pick the single Namaste file
    namaste_file = namaste_files[0]
    try:
        with open(namaste_file, 'r', encoding='utf-8') as f:
            first_line = f.readline().strip()
    except Exception as e:
        return f'cannot read Namaste file {namaste_file}: {e}'
    # Determine type based on content clues
    up = first_line.upper()
    if 'ROOT' in up or 'STORAGE_ROOT' in up:
        return 'root'
    if 'OBJECT' in up:
        return 'object'
    # Fallback: try to parse JSON-ish structure if present
    if first_line.startswith('{'):
        try:
            import json
            data = json.loads(first_line)
            if data.get('objectType') == 'root':
                return 'root'
            if data.get('objectType') == 'object':
                return 'object'
        except Exception:
            pass
    # Unknown content
    snippet = first_line[:30] + ('…' if len(first_line) > 30 else '')
    return f'unknown Namaste file content: {snippet}'.strip()

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if os.path.isfile(path):
        return 'file'

    if not os.path.isdir(path):
        return f'error: path does not exist or is not a directory ({path})'

    namaste_files = [f for f in os.listdir(path) if f.startswith('0=')]
    if not namaste_files:
        return 'error: no Namaste file found in directory'

    # read the first non-empty, non-comment line from the first Namaste file
    try:
        first_file = os.path.join(path, namaste_files[0])
        with open(first_file, 'r', encoding='utf-8') as fh:
            for raw_line in fh:
                line = raw_line.strip()
                if not line or line.startswith('#'):
                    continue
                # Decide based on keywords in the line
                lower = line.lower()
                if 'storage' in lower and 'root' in lower:
                    return 'root'
                if 'object' in lower:
                    return 'object'
                # Fallback: use the entire line as an indicator
                if 'storage' in lower:
                    return 'root'
                if 'object' in lower:
                    return 'object'
                # If line looks like a format identifier, guess object
                if '=' in line:
                    return 'object'
                break
    except Exception as exc:
        return f'error: could not read Namaste file ({exc})'

    return f'error: unable to determine type from Namaste file ({namaste_files[0]})'

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not bug_ids:
        return params
    # Normalize bug_ids to an iterable
    if not isinstance(bug_ids, (list, tuple, set)):
        bug_ids = [bug_ids]
    # Convert all IDs to strings and join them with commas
    ids_str = ",".join(str(bug_id) for bug_id in bug_ids)
    # Add or append the ids to the params dictionary
    if "ids" in params:
        params["ids"] += "," + ids_str
    else:
        params["ids"] = ids_str
    return params

def amend_bzparams(self, params, bug_ids):
    """
    Amends the Bugzilla parameters dictionary `params` with the supplied
    `bug_ids`. The `bug_ids` can be a single value or any iterable of IDs.
    This method normalises the IDs, removes duplicates, keeps numeric IDs
    sorted numerically and finally stores them as a comma‑separated string
    under the key 'ids' in `params`.

    :param dict params: Existing Bugzilla parameters.
    :param bug_ids: Single ID or iterable of IDs to add.
    :return: The amended parameters dictionary.
    """
    if bug_ids is None:
        return params

    # Normalise the incoming IDs to a list of string IDs
    if isinstance(bug_ids, (list, tuple, set)):
        bug_id_list = [str(bid) for bid in bug_ids if bid is not None]
    else:
        bug_id_list = [str(bug_ids)]

    # Retrieve any IDs already present in the params
    existing_ids = []
    if 'ids' in params:
        val = params['ids']
        if isinstance(val, str):
            existing_ids = [s for s in val.split(',') if s]
        else:
            existing_ids = [str(v) for v in val]

    # Merge, deduplicate and sort
    all_ids = set(existing_ids + bug_id_list)

    def sort_key(x):
        try:
            return int(x)
        except ValueError:
            return x

    sorted_ids = sorted(all_ids, key=sort_key)
    params['ids'] = ','.join(sorted_ids)
    return params

def deep_merge_nodes(nodes):
    '''
    Deep merge a list of (ScalarNode, value_node) tuples, handling duplicate keys.
    MappingNode values are recursively merged; otherwise, the latter value wins.
    '''
    def merge_mapping_nodes(a, b):
        # Recursively merge two MappingNode objects
        merged = []
        key_index = {}
        for i, (k, v) in enumerate(a.value):
            merged.append((k, v))
            key_index[k.value] = i
        for k_b, v_b in b.value:
            key = k_b.value
            if key in key_index:
                idx = key_index[key]
                k_a, v_a = merged[idx]
                if isinstance(v_a, MappingNode) and isinstance(v_b, MappingNode):
                    merged_value = merge_mapping_nodes(v_a, v_b)
                    merged[idx] = (k_b, merged_value)
                else:
                    merged[idx] = (k_b, v_b)
            else:
                merged.append((k_b, v_b))
                key_index[key] = len(merged) - 1
        return MappingNode(tag=a.tag, value=merged)

    merged_keys = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_keys:
            old_key_node, old_value_node = merged_keys[key]
            if isinstance(old_value_node, MappingNode) and isinstance(value_node, MappingNode):
                new_value_node = merge_mapping_nodes(old_value_node, value_node)
            else:
                new_value_node = value_node
            merged_keys[key] = (key_node, new_value_node)
        else:
            merged_keys[key] = (key_node, value_node)

    result = []
    seen = set()
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in seen:
            result.append(merged_keys[key])
            seen.add(key)
    return result

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, Node) tuples, performing deep merges for
    MappingNode values with duplicate keys. If duplicate keys have non-mapping
    values, the value from the later tuple overwrites the earlier one.
    """
    def merge_nodes(a, b):
        """Recursively merge two ruamel.yaml node values."""
        # If both are MappingNode, deep merge their entries
        if isinstance(a, ruamel.yaml.nodes.MappingNode) and isinstance(b, ruamel.yaml.nodes.MappingNode):
            # Build a lookup of existing entries from a
            lookup = {k_node.value: (k_node, v_node) for k_node, v_node in a.value}
            # Merge entries from b
            for k_node, v_node in b.value:
                key = k_node.value
                if key in lookup:
                    existing_key_node, existing_v_node = lookup[key]
                    merged_val = merge_nodes(existing_v_node, v_node)
                    lookup[key] = (existing_key_node, merged_val)
                else:
                    lookup[key] = (k_node, v_node)
            # Preserve order: start with entries from a, then new ones from b
            merged_entries = []
            seen_keys = set()
            for k_node, v_node in a.value:
                key = k_node.value
                merged_entries.append(lookup[key])
                seen_keys.add(key)
            for k_node, v_node in b.value:
                key = k_node.value
                if key not in seen_keys:
                    merged_entries.append(lookup[key])
            return ruamel.yaml.nodes.MappingNode(a.tag, merged_entries)
        # For non-mapping values, the later one wins
        return b

    result = []
    index_by_key = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in index_by_key:
            idx = index_by_key[key]
            existing_key_node, existing_val_node = result[idx]
            merged_val = merge_nodes(existing_val_node, val_node)
            result[idx] = (existing_key_node, merged_val)
        else:
            index_by_key[key] = len(result)
            result.append((key_node, val_node))
    return result

def deep_merge_nodes(nodes):
    def is_mapping(node):
        return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'

    def merge_values(a, b):
        if is_mapping(a) and is_mapping(b):
            merged_map = {}
            order = []

            def process(node):
                for k_node, v_node in node.value:
                    key = k_node.value
                    if key in merged_map:
                        merged_map[key] = merge_values(merged_map[key], v_node)
                    else:
                        merged_map[key] = v_node
                        order.append(key)

            process(a)
            process(b)
            # Build new mapping items keeping the first key node seen for each key
            new_items = []
            seen = set()
            for node in a.value + b.value:
                k_node, _ = node
                key = k_node.value
                if key in seen:
                    continue
                seen.add(key)
                new_items.append((k_node, merged_map[key]))
            return type(a)(tag=a.tag, value=new_items)
        else:
            return b

    merged_dict = {}
    order_keys = []
    key_node_map = {}

    for k_node, v_node in nodes:
        key = k_node.value
        if key in merged_dict:
            merged_dict[key] = merge_values(merged_dict[key], v_node)
        else:
            merged_dict[key] = v_node
            order_keys.append(key)
            key_node_map[key] = k_node

    return [(key_node_map[k], merged_dict[k]) for k in order_keys]

def deep_merge_nodes(nodes):
    """
    Merge duplicate keys in a list of (ScalarNode, value) tuples.
    If both values are MappingNode, merge them recursively.
    Otherwise the later value replaces the earlier one.
    """
    def merge_mapping_nodes(map_a, map_b):
        # Merge two MappingNodes in place, return the merged node.
        # Keep the order of map_a, append new keys from map_b.
        new_pairs = list(map_a.value)  # copy the list of (key, value)
        key_index = {k_node.value: i for i, (k_node, _) in enumerate(new_pairs)}
        for key_b, val_b in map_b.value:
            k = key_b.value
            if k in key_index:
                idx = key_index[k]
                val_a = new_pairs[idx][1]
                if (
                    hasattr(val_a, "tag")
                    and "tag:yaml.org,2002:map" in val_a.tag
                    and hasattr(val_b, "tag")
                    and "tag:yaml.org,2002:map" in val_b.tag
                ):
                    merged_val = merge_mapping_nodes(val_a, val_b)
                    new_pairs[idx] = (new_pairs[idx][0], merged_val)
                else:
                    new_pairs[idx] = (new_pairs[idx][0], val_b)
            else:
                new_pairs.append((key_b, val_b))
                key_index[k] = len(new_pairs) - 1
        map_a.value = new_pairs
        return map_a

    merged = {}
    order = []
    for key_node, val_node in nodes:
        k = getattr(key_node, "value", None)
        if k in merged:
            existing = merged[k]
            if (
                hasattr(existing, "tag")
                and "tag:yaml.org,2002:map" in existing.tag
                and hasattr(val_node, "tag")
                and "tag:yaml.org,2002:map" in val_node.tag
            ):
                merged[k] = merge_mapping_nodes(existing, val_node)
            else:
                merged[k] = val_node
        else:
            merged[k] = val_node
            order.append(k)

    result = []
    for key_node, _ in nodes:
        k = getattr(key_node, "value", None)
        if k in merged:
            result.append((key_node, merged[k]))
            del merged[k]
    return result

