def parse_arguments(*unparsed_arguments):
    import argparse
    parser = argparse.ArgumentParser()
    namespace, _ = parser.parse_known_args(unparsed_arguments)
    return {'global': namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed = {}
    unknown_sets = {}
    for name, parser in subparsers.items():
        ns, remainder = parser.parse_known_args(unparsed_arguments)
        parsed[name] = ns
        unknown_sets[name] = set(remainder)
    remaining = [
        arg for arg in unparsed_arguments
        if all(arg in unknown_sets[name] for name in subparsers)
    ]
    return parsed, remaining

def deep_merge_nodes(nodes):
    """
    Merge a list of scalar/mapping node pairs, deep‑merging duplicate scalar keys.
    If a key appears twice with mapping values, their mappings are recursively
    merged; otherwise the latter value wins.
    """
    def _merge_mapping_nodes(a, b):
        kvs = []
        dict_vals = {}
        # Add entries from a first
        for key_node, val_node in a.value:
            kvs.append((key_node, val_node))
            dict_vals[key_node.value] = (key_node, val_node)
        # Merge entries from b
        for key_node, val_node in b.value:
            k = key_node.value
            if k in dict_vals:
                old_key_node, old_val_node = dict_vals[k]
                if isinstance(val_node, ruamel.yaml.nodes.MappingNode) and isinstance(old_val_node, ruamel.yaml.nodes.MappingNode):
                    merged_val = _merge_mapping_nodes(old_val_node, val_node)
                else:
                    merged_val = val_node
                # Replace in dict and kvs
                dict_vals[k] = (old_key_node, merged_val)
                for idx, (k_node, v_node) in enumerate(kvs):
                    if k_node.value == k:
                        kvs[idx] = (k_node, merged_val)
                        break
            else:
                kvs.append((key_node, val_node))
                dict_vals[k] = (key_node, val_node)
        return ruamel.yaml.nodes.MappingNode(tag=a.tag, value=kvs)

    seen = {}
    order = []
    for key_node, val_node in nodes:
        k = key_node.value
        if k in seen:
            old_key_node, old_val_node = seen[k]
            if isinstance(val_node, ruamel.yaml.nodes.MappingNode) and isinstance(old_val_node, ruamel.yaml.nodes.MappingNode):
                merged_val = _merge_mapping_nodes(old_val_node, val_node)
            else:
                merged_val = val_node
            seen[k] = (old_key_node, merged_val)
        else:
            seen[k] = (key_node, val_node)
            order.append(k)

    return [(seen[k][0], seen[k][1]) for k in order]

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, Node) tuples that may contain duplicate keys.
    Duplicate keys trigger a merge of MappingNode values; otherwise the latest value wins.
    """
    # helper to merge two MappingNodes
    def merge_mapping_nodes(node1, node2):
        return ruamel.yaml.nodes.MappingNode(tag=node1.tag, value=merge_mapping_values(node1.value, node2.value))

    # helper to merge two lists of MappingNode children (list of (ScalarNode, Node))
    def merge_mapping_values(vals1, vals2):
        merged = {}
        order = []

        # process first list
        for k, v in vals1:
            merged[k.value] = (k, v)
            order.append(k.value)

        # process second list
        for k, v in vals2:
            key = k.value
            if key in merged:
                existing_val = merged[key][1]
                if isinstance(existing_val, ruamel.yaml.nodes.MappingNode) and isinstance(v, ruamel.yaml.nodes.MappingNode):
                    merged_val = merge_mapping_nodes(existing_val, v)
                else:
                    merged_val = v
                merged[key] = (k, merged_val)
            else:
                merged[key] = (k, v)
                order.append(key)

        return [merged[k] for k in order]

    # merge top-level nodes
    merged_dict = {}
    order = []

    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_dict:
            old_val = merged_dict[key][1]
            if isinstance(old_val, ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                merged_val = merge_mapping_nodes(old_val, value_node)
            else:
                merged_val = value_node
            merged_dict[key] = (key_node, merged_val)
        else:
            merged_dict[key] = (key_node, value_node)
            order.append(key)

    return [merged_dict[k] for k in order]

def deep_merge_nodes(nodes):
    """Deep merge a list of (ScalarNode, value) tuples, returning a merged list."""
    # Helper to merge two MappingNode values
    def _merge_mapping(existing, incoming):
        # Build a dict of existing elements: key string -> (key_node, val_node)
        existing_dict = {k_node.value: (k_node, v_node) for k_node, v_node in existing.value}
        for k_node, v_node in incoming.value:
            key = k_node.value
            if key in existing_dict:
                existing_key_node, existing_val_node = existing_dict[key]
                if isinstance(existing_val_node, MappingNode) and isinstance(v_node, MappingNode):
                    merged_val = _merge_mapping(existing_val_node, v_node)
                    existing_dict[key] = (existing_key_node, merged_val)
                else:
                    # last wins for non-mapping values
                    existing_dict[key] = (existing_key_node, v_node)
            else:
                existing_dict[key] = (k_node, v_node)
        # Reassemble as list
        merged_pairs = [(k, v) for k, v in existing_dict.values()]
        return MappingNode(tag=existing.tag, value=merged_pairs)

    # Main merge dict: key string -> (key_node, val_node)
    merged = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in merged:
            existing_key_node, existing_val_node = merged[key]
            if isinstance(existing_val_node, MappingNode) and isinstance(val_node, MappingNode):
                merged_val_node = _merge_mapping(existing_val_node, val_node)
                merged[key] = (existing_key_node, merged_val_node)
            else:
                merged[key] = (existing_key_node, val_node)
        else:
            merged[key] = (key_node, val_node)

    # Return merged list preserving insertion order
    return [(k, v) for _, (k, v) in merged.items()]

def deep_merge_nodes(nodes):
    """
    Merge nodes of type (ScalarNode, MappingNode|other) on duplicate keys. If two values are both
    MappingNode, merge them recursively. Otherwise, the later value wins.
    """
    result = []
    key_map = {}
    key_order = []

    for key_node, value_node in nodes:
        key = key_node.value

        if key in key_map:
            existing = key_map[key]
            if (
                isinstance(existing, ruamel.yaml.nodes.MappingNode)
                and isinstance(value_node, ruamel.yaml.nodes.MappingNode)
            ):
                # Merge mapping node values recursively
                merged_pairs = deep_merge_nodes(existing.value + value_node.value)
                key_map[key] = ruamel.yaml.nodes.MappingNode(
                    tag=existing.tag, value=merged_pairs
                )
            else:
                # The last value wins
                key_map[key] = value_node
        else:
            key_map[key] = value_node
            key_order.append((key_node, key))

    # Preserve the first occurrence order
    for key_node, key in key_order:
        result.append((key_node, key_map[key]))

    return result

