def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    import pkgutil
    subcmds = set()
    opt_strings = set()
    try:
        import borgmatic
        # Try to find a parser function in known borgmatic modules
        parser = None
        known_funcs = (
            ("cli", "get_parser"),
            ("cli", "build_parser"),
            ("__main__", "build_parser"),
            ("__main__", "get_parser"),
        )
        for mod_name, func_name in known_funcs:
            try:
                mod = __import__(f"borgmatic.{mod_name}", fromlist=[func_name])
                if hasattr(mod, func_name):
                    parser = getattr(mod, func_name)()
                    if parser:
                        break
            except Exception:
                continue

        # If we can't build a parser directly, try to load the main module and call its main
        if not parser:
            try:
                main_mod = __import__("borgmatic.__main__")
                if hasattr(main_mod, "main"):
                    # Main is defined to take args; we supply an empty list but capture the parser
                    # by monkey-patching argparse.Namespace to return the parser
                    import argparse
                    original_parse_args = argparse.ArgumentParser.parse_args

                    def fake_parse_args(self, args=None, namespace=None):
                        return original_parse_args(self, args or [], namespace)

                    try:
                        argparse.ArgumentParser.parse_args = fake_parse_args
                        # Running main with no args will create the parser but not terminate
                        try:
                            main_mod.main([])
                        except SystemExit:
                            pass
                        parser = main_mod.parser if hasattr(main_mod, "parser") else None
                    finally:
                        argparse.ArgumentParser.parse_args = original_parse_args
            except Exception:
                pass

        # If we found a parser, extract subcommands and option strings
        if parser:
            # Subcommands – check for a subparsers action
            subparsers = (
                getattr(parser, "_subparsers", None)
            )
            if subparsers and hasattr(subparsers, "choices"):
                subcmds.update(subparsers.choices.keys())
            # All options
            for action in getattr(parser, "_actions", []):
                if action.option_strings:
                    opt_strings.update(action.option_strings)

        # If still empty, introspect other modules under borgmatic for click groups
        if not subcmds:
            for _, mod_name, _ in pkgutil.iter_modules(borgmatic.__path__):
                try:
                    mod = __import__(f"borgmatic.{mod_name}", fromlist=["cli"])
                    if hasattr(mod, "cli"):
                        # Try to get click subcommands
                        try:
                            from click import CommandCollection
                            if isinstance(mod.cli, CommandCollection):
                                subcmds.update(mod.cli.commands.keys())
                        except Exception:
                            pass
                except Exception:
                    continue
    except Exception:
        # If any step fails, we default to an empty completion
        pass

    # Build the completion script
    lines = [
        "_borgmatic_completion() {",
        "    local cur prev words cword",
        "    cur=\"${COMP_WORDS[COMP_CWORD]}\"",
        "    prev=\"${COMP_WORDS[COMP_CWORD-1]}\"",
        "",
        "    case $COMP_CWORD in",
    ]

    if subcmds:
        sub_list = " ".join(sorted(subcmds))
        lines.extend([
            "        1)",
            f"            COMPREPLY=( $(compgen -W \"{sub_list}\" -- \"$cur\") );;",
        ])
    else:
        lines.extend([
            "        1)",
            "            COMPREPLY=();;",
        ])

    # Provide option completions for any position after the first word
    if opt_strings:
        opt_list = " ".join(sorted(opt_strings))
        lines.extend([
            "        *)",
            f"            COMPREPLY=( $(compgen -W \"{opt_list}\" -- \"$cur\") );;",
        ])
    else:
        lines.extend([
            "        *)",
            "            COMPREPLY=();;",
        ])

    lines.extend([
        "    esac",
        "}",
        "",
        "complete -F _borgmatic_completion borgmatic",
    ])

    return "\n".join(lines)

