def _replace_url_args(url, url_args):
    """
    Replace any custom string URL items with values in args.

    Handles placeholders of the form {key} or <key>.
    If a key is not present in url_args, the placeholder is left unchanged.
    """
    if not url_args:
        return url

    import re

    def _sub(match):
        key = match.group(1)
        if key in url_args:
            return str(url_args[key])
        return match.group(0)

    # Replace {key}
    url = re.sub(r'{(\w+)}', _sub, url)
    # Replace <key>
    url = re.sub(r'<(\w+)>', _sub, url)

    return url

