def vertex3tuple(vertices):
    """Return 3-point tuples for each vertex of a closed polygon.

    For each vertex *i*, the function returns a tuple
    (previous_vertex, current_vertex, next_vertex) where
    "previous" and "next" wrap around the ends of the list.
    """
    n = len(vertices)
    if n == 0:
        return []
    return [
        (vertices[(i - 1) % n], vertices[i], vertices[(i + 1) % n])
        for i in range(n)
    ]

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Number must be non-negative")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two symbols")
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while number:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])
    result = ''.join(reversed(digits))
    if padding is not None and padding > len(result):
        pad_len = padding - len(result)
        result = alphabet[0] * pad_len + result
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two symbols.")
    sign = ""
    if number < 0:
        sign = "-"
        number = -number
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while number:
            digits.append(alphabet[number % base])
            number //= base
        digits.reverse()
    if padding is None or padding <= len(digits):
        padded = "".join(digits)
    else:
        padded = alphabet[0] * (padding - len(digits)) + "".join(digits)
    return sign + padded

