    """
    if not alphabet or len(alphabet) < 2:
        raise ValueError("Alphabet must contain at least two elements")
    base = len(alphabet)
    if number == 0:
        result = alphabet[0]
    else:
        sign = ""
        if number < 0:
            sign = "-"
            number = -number
