def subclasses(cls):
    """
    Return all subclasses of a class, recursively.
    """
    subs = set()
    def _collect(c):
        for sub in c.__subclasses__():
            if sub not in subs:
                subs.add(sub)
                _collect(sub)
    _collect(cls)
    return list(subs)

