def regex_dict(item):
    """
    Convert wildcard patterns in dictionary keys to compiled regular expressions.
    Only the keys are converted; the corresponding values are preserved unchanged.
    """
    # Helper to translate a wildcard pattern (e.g., '*.cpp') into a regex string.
    def _wildcard_to_regex(pattern):
        # Start with the beginning of the string anchor.
        regex_parts = ['^']
        for ch in pattern:
            if ch == '*':
                regex_parts.append('.*')
            elif ch == '?':
                regex_parts.append('.')
            else:
                regex_parts.append(re.escape(ch))
        regex_parts.append('$')
        return ''.join(regex_parts)

    # Build a new dictionary with compiled regex keys.
    new_dict = {}
    for key, value in item.items():
        regex_pattern = _wildcard_to_regex(key)
        new_dict[re.compile(regex_pattern)] = value
    return new_dict

def regex_dict(item):
    """Convert filename keys containing wildcards into regex keys, leaving values intact."""
    new_item = {}
    for key, val in item.items():
        # Convert only if key contains a wildcard '*'
        if '*' in key or '?' in key:
            # Escape all regex metacharacters except '*' and '?'
            escaped = re.escape(key)
            # Replace escaped wildcards with regex equivalents
            escaped = escaped.replace(r'\*', '.*').replace(r'\?', '.')
            # Anchor the pattern
            new_key = f'^{escaped}$'
        else:
            new_key = key
        new_item[new_key] = val
    return new_item

