                i += 1
                while i < n:
                    if text[i] == '"':
                        i += 1
                        break
                    if text[i] == '\\':
                        bs_count = 0
                        while i < n and text[i] == '\\':
                            bs_count += 1
                            i += 1
                        if i < n and text[i] == '"':
                            buf.extend(['\\'] * (bs_count // 2))
                            if bs_count % 2:
                                buf.append('"')
                                i += 1
                            else:
                                i += 1
                        else:
                            buf.extend(['\\'] * bs_count)
                    else:
                        buf.append(text[i])
                        i += 1
                tokens.append(''.join(buf))
            else:
                while i < n and not text[i].isspace():
                    if text[i] == '\\':
                        i += 1
                        if i < n:
                            buf.append(text[i])
                            i += 1
                    else:
                        buf.append(text[i])
                        i += 1
                tokens.append(''.join(buf))
        return tokens

    if platform == 0 or platform == 'windows' or platform.lower() == 'windows':
        return _windows_split(s)

    if platform == 'this':
        try:
            import sys
            if sys.platform.startswith('win'):
                return _windows_split(s)
            else:
                return [m.group(1) if m.group(1) is not None else
                        m.group(2) if m.group(2) is not None else
                        m.group('token')
                        for m in posix_regex.finditer(s)]
        except Exception:
            return [m.group(1) if m.group(1) is not None else
                    m.group(2) if m.group(2) is not None else
                    m.group('token')
                    for m in posix_regex.finditer(s)]

    raise ValueError(f'Unsupported platform value: {platform}')

