def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX or simple parser.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys

    # Determine platform code
    if platform == 'this':
        platform_code = 1 if not sys.platform.startswith('win') else 0
    else:
        platform_code = int(platform)

    # POSIX: use shlex with posix=True
    if platform_code == 1:
        import shlex
        try:
            return shlex.split(s, posix=True)
        except ValueError as exc:
            raise ValueError(f"POSIX spli…") from exc  # truncated for brevity

    # Windows: simple custom parser (not full-featured but adequate for typical cases)
    def _win_split(cmd):
        args = []
        arg = []
        i = 0
        length = len(cmd)
        in_quote = False
        while i < length:
            ch = cmd[i]
            if ch == '\\':
                # Count consecutive backslashes
                bs_count = 0
                while i < length and cmd[i] == '\\':
                    i += 1
                    bs_count += 1
                if i < length and cmd[i] == '"':
                    # Escape sequence before a quote
                    arg.append('\\' * (bs_count // 2))
                    if bs_count % 2 == 1:
                        arg.append('"')
                    i += 1   # consume the quote
                    in_quote = not in_quote
                else:
                    arg.append('\\' * bs_count)
            elif ch == '"':
                in_quote = not in_quote
                i += 1
            elif ch.isspace() and not in_quote:
                if arg:
                    args.append(''.join(arg))
                    arg = []
                i += 1
            else:
                arg.append(ch)
                i += 1
        if arg:
            args.append(''.join(arg))
        return args

    return _win_split(s)

