def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq = str(frequency).strip().lower()
    if freq in ('', 'always'):
        return None
    # Split into number and unit; allow multiple spaces
    parts = freq.split(None, 1)
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: '{frequency}'")
    num_str, unit = parts
    try:
        number = int(num_str)
    except ValueError:
        try:
            number = float(num_str)
        except ValueError:
            raise ValueError(f"Cannot parse number in frequency: '{frequency}'")
    unit_map = {
        'day': 'days', 'days': 'days',
        'week': 'weeks', 'weeks': 'weeks',
        'hour': 'hours', 'hours': 'hours',
        'minute': 'minutes', 'minutes': 'minutes',
        'second': 'seconds', 'seconds': 'seconds',
        'ms': 'milliseconds', 'millisecond': 'milliseconds', 'milliseconds': 'milliseconds',
        'microsecond': 'microseconds', 'microseconds': 'microseconds',
        'month': 'days', 'months': 'days',   # approximate as days: 30 days? optional
        'year': 'days', 'years': 'days',     # approximate as days: 365 days? optional
    }
    if unit not in unit_map:
        raise ValueError(f"Unknown time unit in frequency: '{frequency}'")
    # Map to timedelta keyword; for month/year approximate as days if needed
    kw = unit_map[unit]
    # Handle approximate month/year
    if kw == 'days' and unit in ('month', 'months'):
        # assume 30 days per month
        number = number * 30
    elif kw == 'days' and unit in ('year', 'years'):
        number = number * 365
    # Build kwargs
    delta_kwargs = {kw: number}
    return datetime.timedelta(**delta_kwargs)

def parse_frequency(frequency):
    """
    Parse a frequency string like "3 weeks" into a datetime.timedelta.
    If frequency is None or "always", returns None.
    Raises ValueError if parsing fails.
    """
    if frequency is None:
        return None
    freq = frequency.strip().lower()
    if freq == "always":
        return None
    import re
    match = re.fullmatch(r'(\d+(?:\.\d+)?)\s*(\w+)', freq)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")
    value_str, unit = match.group(1), match.group(2)
    try:
        value = int(float(value_str))
    except Exception as exc:
        raise ValueError(f"Invalid numeric value in frequency: {value_str!r}") from exc
    unit_map = {
        'day': 'days', 'days': 'days', 'd': 'days',
        'hour': 'hours', 'hours': 'hours', 'h': 'hours',
        'minute': 'minutes', 'minutes': 'minutes', 'min': 'minutes', 'mins': 'minutes', 'm': 'minutes',
        'second': 'seconds', 'seconds': 'seconds', 's': 'seconds',
        'week': 'weeks', 'weeks': 'weeks', 'w': 'weeks',
    }
    unit_key = unit_map.get(unit)
    if unit_key is None:
        raise ValueError(f"Unknown unit '{unit}' in frequency: {frequency!r}")
    return datetime.timedelta(**{unit_key: value})

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Direct string comparison for the canonical name
    if host is None:
        return False
    if host.lower() == "localhost":
        return True
    # Resolve host to addresses
    try:
        addr_info = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for family, _, _, _, sockaddr in addr_info:
        # IPv4 loopback
        if family == socket.AF_INET:
            ip = sockaddr[0]
            # Any address in 127.0.0.0/8 is loopback
            if ip.startswith("127."):
                return True
        # IPv6 loopback
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            if ip == "::1":
                return True
    return False

