def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        if os.name != 'nt':
            return False
        # Check typical Git Bash environment variables
        if os.environ.get('OSTYPE', '').lower().startswith('msys'):
            return True
        if os.environ.get('MSYSTEM'):
            return True
        # Some installations may set PATH to include msys or mingw
        path = os.environ.get('PATH', '').lower()
        if 'msys' in path or 'mingw' in path:
            return True
        return False
    except Exception:
        return False

def oneline(script, separator=" && "):
    """Convert a multi‑line script into a single‑line command suitable for SSH."""
    if not script:
        return ""
    # Normalize indentation
    dedented = textwrap.dedent(script)
    # Remove leading/trailing whitespace and skip empty lines
    lines = [line.strip() for line in dedented.splitlines() if line.strip()]
    # Join the cleaned lines with the specified separator
    return separator.join(lines)

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    if isinstance(matcher, str):
        # Parse the matcher. Accept formats like "VAR" or "VAR=default"
        if '=' in matcher:
            key, default = matcher.split('=', 1)
            key = key.strip()
            default = default.strip()
        else:
            key = matcher.strip()
            default = None
    else:
        raise TypeError(f"Matcher must be a string, got {type(matcher).__name__}")

    value = os.environ.get(key)
    if value is not None:
        return value
    if default is not None:
        return default
    raise KeyError(f"Required environment variable '{key}' is not defined and no default was provided.")

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    parsed = urllib.parse.urlparse(image_href)
    if parsed.scheme not in ("http", "https"):
        raise ValueError(f"Unsupported scheme in image href: {parsed.scheme}")
    use_ssl = parsed.scheme == "https"
    netloc = parsed.netloc
    path = parsed.path.rstrip("/")
    if not path:
        raise ValueError("Image href does not contain a path for image id.")
    image_id = path.split("/")[-1]
    if not image_id:
        raise ValueError("Could not extract image id from href.")
    return image_id, netloc, use_ssl

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    parsed = urllib.parse.urlparse(image_href)
    scheme = parsed.scheme
    if scheme not in ("http", "https"):
        raise ValueError(f"Unsupported scheme: {scheme}")
    netloc = parsed.netloc
    if not netloc:
        raise ValueError(f"Missing netloc in URL: {image_href}")
    image_id = parsed.path.lstrip("/")
    if not image_id:
        raise ValueError(f"Missing image id in path: {image_href}")
    use_ssl = scheme == "https"
    return image_id, netloc, use_ssl

