def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a compiled regex pattern.
    If `strip` is True, leading/trailing whitespace is removed before processing.
    The string is escaped to be treated as a literal, and the resulting regex
    pattern matches the entire string (anchored at start and end).
    """
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    if strip:
        pattern = pattern.strip()
    if pattern == "":
        # Match an empty string
        regex = r"^$"
    else:
        # Escape the pattern so that all regex metacharacters are treated literally,
        # and anchor the pattern to match the whole input string.
        regex = r"^" + re.escape(pattern) + r"$"
    return re.compile(regex)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the full command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]
    if args:
        # If args is a list/tuple, extend; otherwise, treat as single string
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        else:
            cmd.append(args)
    if verbose:
        print("Running command:", " ".join(cmd))
    # Set up subprocess run parameters
    run_kwargs = {
        "cwd": cwd,
        "env": env,
        "text": True,
    }
    if hide_stderr:
        run_kwargs["stdout"] = subprocess.PIPE
        run_kwargs["stderr"] = subprocess.DEVNULL
    else:
        run_kwargs["capture_output"] = True
    try:
        result = subprocess.run(cmd, **run_kwargs)
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd[0]}") from e
    return result

