def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import os
    import sys
    import subprocess
    import shlex

    # Build command list
    if isinstance(commands, str):
        cmd_list = shlex.split(commands)
    else:
        try:
            cmd_list = list(commands)
        except TypeError:
            raise ValueError("commands must be a string or an iterable of strings")

    # Append args
    if args:
        if isinstance(args, str):
            args_list = shlex.split(args)
        elif isinstance(args, (list, tuple)):
            args_list = list(args)
        else:
            raise ValueError("args must be a string or an iterable of strings")
        cmd_list.extend(args_list)

    # Prepare environment
    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary if provided")
    env_vars = os.environ.copy()
    if env:
        env_vars.update(env)

    # Verbose output
    if verbose:
        sys.stdout.write(f"Executing command: {' '.join(cmd_list)}\n")
        if cwd:
            sys.stdout.write(f"Working directory: {cwd}\n")

    # Execute command
    result = subprocess.run(
        cmd_list,
        cwd=cwd,
        env=env_vars,
        capture_output=True,
        text=True
    )

    # Output results
    if verbose:
        if result.stdout:
            sys.stdout.write(result.stdout)
        if result.stderr and not hide_stderr:
            sys.stderr.write(result.stderr)

    # Return useful information
    return {
        "returncode": result.returncode,
        "stdout": result.stdout,
        "stderr": result.stderr
    }

