def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    log_records = []
    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()
            # Attempt to parse the configuration as a Python literal (dictionary)
            config = eval(content, {"__builtins__": None}, {})
            if not isinstance(config, dict):
                raise ValueError("Parsed configuration is not a dictionary")
        except Exception as exc:
            record = logging.LogRecord(
                "config_loader",
                logging.ERROR,
                fname,
                0,
                f"Error parsing '{fname}': {exc}",
                None,
                None
            )
            log_records.append(record)
            continue

        # Resolve environment variables in string values if requested
        if resolve_env:
            try:
                import os
                for key, value in config.items():
                    if isinstance(value, str):
                        # Replace occurrences of $VAR or ${VAR} with environment value
                        import re
                        pattern = r'\$(\w+)|\${(\w+)}'
                        def repl(match):
                            var_name = match.group(1) or match.group(2)
                            return os.getenv(var_name, match.group(0))
                        new_value = re.sub(pattern, repl, value)
                        config[key] = new_value
            except Exception:
                # Ignore any failures during env resolution
                pass

        # Apply overrides if supplied
        if overrides and isinstance(overrides, dict):
            for key, override_value in overrides.items():
                if key in config:
                    config[key] = override_value

        configs[fname] = config

    return configs, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
      - dict of configuration filename to corresponding parsed configuration
      - sequence of logging.LogRecord instances containing any parse errors
    """
    import json
    import os
    import logging

    configurations = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                config = json.load(f)
        except Exception as exc:
            # create a LogRecord for the parse error
            record = logging.makeRecord(
                name=__name__,
                level=logging.ERROR,
                fn=filename,
                lno=0,
                msg=f"Failed to parse '{filename}': {exc}",
                args=(),
                exc_info=None
            )
            error_records.append(record)
            continue

        # Apply overrides if provided
        if overrides:
            for key, value in overrides.items():
                config[key] = value

        # Resolve environment variables if requested
        if resolve_env:
            def resolve(value):
                if isinstance(value, dict):
                    return {k: resolve(v) for k, v in value.items()}
                if isinstance(value, list):
                    return [resolve(v) for v in value]
                if isinstance(value, str):
                    # Replace ${VAR} or $VAR patterns
                    return os.path.expandvars(value)
                return value

            config = resolve(config)

        configurations[filename] = config

    return configurations, error_records

