def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type)."""
    from collections.abc import Sequence, Mapping
    # If seq is a mapping (e.g., dict), use its values as the sequence
    if isinstance(seq, Mapping):
        seq = seq.values()
    # Handle byte-like objects separately (bytes, bytearray) – treat them as a single sequence
    if isinstance(seq, (bytes, bytearray)):
        return seq, type(seq)
    # For plain strings, convert to a list of characters (keeping the original type returned)
    if isinstance(seq, str):
        return list(seq), type(seq)
    # If seq is already a Sequence (e.g., list, tuple, range), return it unchanged
    if isinstance(seq, Sequence):
        return seq, type(seq)
    # For any other iterable, materialise it into a list
    try:
        seq_list = list(seq)
        return seq_list, type(seq_list)
    except TypeError:
        # seq is not iterable – wrap it in a list to provide a sequence
        return [seq], type([seq])

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Treat None as empty sequence
    if seq is None:
        return (), type(None)

    # Strings, bytes and other immutable types are considered sequences
    # but we leave them untouched.
    if isinstance(seq, (str, bytes)):
        return seq, type(seq)

    # Built‑in sequence containers (list, tuple, set, frozenset) are also left untouched.
    if isinstance(seq, (list, tuple, set, frozenset)):
        return seq, type(seq)

    # Fall back to materialising the iterable.
    try:
        seq_list = list(seq)
    except TypeError:
        # `seq` is not iterable – treat it as a single element.
        seq_list = [seq]
    return seq_list, list

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    If *seq* has a ``read`` method, it will be read (optionally using *bufsize*),
    otherwise non-sequential values will be converted to ``list``.
    The type returned is the type of the elements in the sequence,
    or the type of the sequence itself when it is a string-like object.
    """
    # Handle file-like objects
    if hasattr(seq, "read"):
        try:
            data = seq.read() if bufsize is None else seq.read(bufsize)
        except Exception:
            data = seq.read()
        result_seq = data
        seq_type = type(data)
        return result_seq, seq_type

    # Sequence types that can be returned unchanged
    seq_types = (str, bytes, bytearray, list, tuple, set, frozenset)
    if isinstance(seq, seq_types):
        result_seq = seq
    else:
        # Try to convert to list; if fails, keep original
        try:
            result_seq = list(seq)
        except Exception:
            result_seq = seq

    # Determine the element type
    if isinstance(result_seq, (str, bytes, bytearray)):
        elem_type = type(result_seq)
    else:
        try:
            elem_type = type(result_seq[0]) if result_seq else type(None)
        except Exception:
            elem_type = type(result_seq)

    return result_seq, elem_type

def _get_seq_with_type(seq, bufsize=None):
    # Determine whether seq is already a sequence type
    is_sequence = hasattr(seq, "__len__") and hasattr(seq, "__getitem__")
    if is_sequence:
        return seq, type(seq)
    # Try to construct a sequence from an iterable
    try:
        seq_list = list(seq)
        if bufsize is not None:
            seq_list = seq_list[:bufsize]
    except Exception as exc:
        raise TypeError("Provided seq must be a sequence or iterable") from exc
    return seq_list, type(seq)

def scale(self, other=None, recompute=False):
    """
    Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute the integral if needed
    def _compute_scale():
        try:
            # Assume histogram stores counts in a list/array named `counts`
            return sum(self.counts)
        except AttributeError:
            # Fallback: we try to iterate over a generic iterable `bins`
            try:
                return sum(bin.count for bin in self.bins)
            except AttributeError:
                # Last resort: sum over `data` or `values`
                try:
                    return sum(self.data)
                except AttributeError:
                    raise AttributeError("Unable to compute scale: no recognized data attribute.")
    # Retrieve or compute the current scale
    if other is None:
        if recompute or not hasattr(self, "_scale"):
            self._scale = _compute_scale()
        return self._scale
    # Rescaling process
    if not isinstance(other, (int, float)):
        raise TypeError("Argument 'other' must be a number to rescale the histogram.")
    current_scale = self.scale(recompute=recompute)
    if current_scale == 0:
        # Mimic the custom exception from the module if available
        try:
            from .errors import LenaValueError
            raise LenaValueError("Cannot rescale histogram with zero scale.")
        except Exception:
            raise ValueError("Cannot rescale histogram with zero scale.")
    # Determine the scaling factor
    factor = other / current_scale
    # Apply scaling to the underlying data
    try:
        # If histogram has a mutable list of counts
        if hasattr(self, "counts"):
            self.counts = [c * factor for c in self.counts]
        elif hasattr(self, "bins"):
            for bin in self.bins:
                bin.count = getattr(bin, "count", 0) * factor
        elif hasattr(self, "data"):
            self.data = [v * factor for v in self.data]
        else:
            raise AttributeError("Histogram data structure unknown; cannot rescale.")
    except TypeError:
        # In case the data is stored in a NumPy array or similar
        try:
            self.data *= factor
        except Exception:
            raise
    # Update the stored scale
    self._scale = other
    return self

def scale(self, other=None, recompute=False):
    """
    Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for
    subsequent use (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must
    explicitly recompute the scale if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute the integral of the bin contents
    def _integral():
        if hasattr(self, "_counts"):
            return sum(self._counts)
        # Fallback: look for an array/sequence of values stored in `data`
        if hasattr(self, "data") and hasattr(self.data, "__iter__"):
            return sum(self.data)
        # As a last resort, try a public `sum` method if it exists
        if hasattr(self, "sum") and callable(self.sum):
            return self.sum()
        # If none of the above, raise an informative error
        raise AttributeError("Histogram object has no accessible count storage")

    # ------------------------------------------------------------------
    # Retrieve or compute the current scale
    if other is None:
        if self._scale is None or recompute:
            self._scale = _integral()
        return self._scale

    # ------------------------------------------------------------------
    # Rescale the histogram to the new total scale `other`
    current_scale = self.scale(recompute=recompute)

    if current_scale == 0:
        raise LenaValueError("Cannot rescale histogram with zero scale")

    factor = other / current_scale

    # Apply the scaling factor to each bin content
    if hasattr(self, "_counts"):
        for i in range(len(self._counts)):
            self._counts[i] *= factor
    elif hasattr(self, "data") and hasattr(self.data, "__iter__"):
        # Use slice assignment if possible
        for i in range(len(self.data)):
            self.data[i] *= factor
    elif hasattr(self, "scale_bins") and callable(self.scale_bins):
        # Generic interface: assume user provides a method to scale bins
        self.scale_bins(factor)
    else:
        raise AttributeError("Histogram object has no accessible bin data to rescale")

    self._scale = other
    return self._scale

