    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Get scale
    if other is None:
        return getattr(self, "_scale", None)

    # Set scale
    try:
        new_scale = float(other)
    except Exception as exc:
        raise TypeError("Scale must be a number") from exc

    # Current scale retrieval
    cur_scale = getattr(self, "_scale", None)
    if cur_scale is None:
        raise LenaValueError("Graph has no defined scale to rescale.")
    if cur_scale == 0:
        raise LenaValueError("Cannot rescale a graph with zero current scale.")

    # Determine scaling factor
    factor = new_scale / cur_scale

    # Rescale last coordinate and its error if present
    # Prefer numpy arrays if available, otherwise use lists
    coords = None
    errors = None

    if hasattr(self, "values") and isinstance(self.values, (list, tuple)):
        coords = self.values
    elif hasattr(self, "fields") and isinstance(self.fields, list):
        coords = self.fields

    if coords is not None:
        try:
            coords[-1] = coords[-1] * factor
        except Exception:
            # If coordinates are nested (e.g., a list of points), multiply element-wise
            coords[-1] = [c * factor for c in coords[-1]]

    if hasattr(self, "errors"):
        errors = self.errors
    elif hasattr(self, "err_fields"):
        errors = self.err_fields

    if errors is not None:
        try:
            errors[-1] = errors[-1] * factor
        except Exception:
            errors[-1] = [e * factor for e in errors[-1]]

    # Update internal scale
    self._scale = new_scale
    return None

