    elif get_coordinate == "right":
        coord_func = lambda bin_: _get_attr(bin_, "high_edge")
    elif get_coordinate == "middle":
        coord_func = lambda bin_: (_get_attr(bin_, "low_edge") + _get_attr(bin_, "high_edge")) / 2
    else:
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

    points = []
    for bin_ in hist.bins:
        coord = coord_func(bin_)
        val = make_value(bin_)
        if not isinstance(val, tuple):
            val = (val,)
        point = {field_names[0]: coord}
        for name, v in zip(field_names[1:], val):
            point[name] = v
        points.append(point)

    graph = {"points": points}
    if scale is True:
        graph["scale"] = getattr(hist, "scale", None)
    elif scale is not None:
        graph["scale"] = scale
    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """Verify that *candidate* might correctly provide *iface*."""
    errors = []

    # 1. Check that candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    f"{candidate!r} does not provide {iface.__name__}"
                )
        except Exception as exc:
            errors.append(
                f"Error checking providedBy for {candidate!r} and {iface.__name__}: {exc}"
            )

    # 2. Check methods and attributes
    for name, val in iface.items():
        is_method = getattr(val, "_isMethod", False)
        is_attribute = getattr(val, "_isAttribute", False) or getattr(val, "_isProperty", False)

        # Skip non-method/non-attribute members
        if not (is_method or is_attribute):
            continue

        # Does candidate define the member?
        if not hasattr(candidate, name):
            errors.append(f"{candidate!r} is missing member {name!r}")
            continue

        # If it's a method, check signature
        if is_method:
            candidate_method = getattr(candidate, name)
            if not callable(candidate_method):
                errors.append(f"{candidate!r}.{name!r} is not callable")
                continue
            try:
                iface_sig = inspect.signature(val)
                cand_sig = inspect.signature(candidate_method)
            except Exception as exc:
                errors.append(
                    f"Error inspecting signatures for {candidate!r}.{name!r}: {exc}"
                )
                continue
            # Compare parameter names and kind
            iface_params = list(iface_sig.parameters)
            cand_params = list(cand_sig.parameters)
            if len(iface_params) != len(cand_params):
                errors.append(
                    f"Signature mismatch for {candidate!r}.{name!r}: expected {iface_sig}, got {cand_sig}"
                )
                continue
            for i, (ip, cp) in enumerate(zip(iface_params, cand_params)):
                ip_obj = iface_sig.parameters[ip]
                cp_obj = cand_sig.parameters[cp]
                if ip_obj.kind != cp_obj.kind or ip_obj.default is not cp_obj.default:
                    errors.append(
                        f"Parameter mismatch in {candidate!r}.{name!r} at position {i+1}: expected {ip_obj}, got {cp_obj}"
                    )
                    break

    # 3. Report errors
    if not errors:
        return True
    if len(errors) == 1:
        raise zope.interface.Invalid(errors[0])
    raise zope.interface.Invalid("; ".join(errors))

def _verify(iface, candidate, tentative=False, vtype=None):
    # Ensure the candidate claims to provide the interface unless tentative
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"{candidate!r} does not provide {iface!r}")

    errors = []

    # Inspect required members defined on the interface
    for name, member in iface.__dict__.items():
        if name.startswith("__"):
            continue
        # Attributes
        if isinstance(member, zope.interface.Attribute):
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute {name!r} in {candidate!r}")
        # Methods
        elif isinstance(member, zope.interface.Method):
            if not hasattr(candidate, name):
                errors.append(f"Missing method {name!r} in {candidate!r}")
            else:
                cand_attr = getattr(candidate, name)
                try:
                    iface_sig = zope.interface.signature(member)
                    cand_sig = zope.interface.signature(cand_attr)
                    if iface_sig != cand_sig:
                        errors.append(
                            f"Signature mismatch for {name!r}: expected {iface_sig!r} got {cand_sig!r}"
                        )
                except Exception:
                    # If we cannot retrieve signatures, skip mismatch checking
                    pass

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        raise zope.interface.Invalid("\n".join(errors))

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    from inspect import signature, Parameter
    from zope.interface import Invalid

    errors = []

    # 1. Check that candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    f"Candidate {candidate!r} does not declare that it provides {iface}
                    interface."
                )
        except Exception as exc:
            errors.append(f"Could not determine if candidate provides the interface: {exc}")

    # 2. Iterate over interface attributes (excluding private ones)
    defined_names = set(
        name for name in dir(iface) if not name.startswith("_")
    )

    for name in defined_names:
        iface_attr = getattr(iface, name, None)

        # Skip if attribute is a descriptor that doesn't produce a value directly
        try:
            if hasattr(iface, name):
                # Determine if interface defines a method or attribute
                # Method: callable and defined as interface method
                # Attribute: non-callable
                if callable(iface_attr):
                    # Check candidate has a callable with same name
                    if not hasattr(candidate, name):
                        errors.append(
                            f"Candidate {candidate!r} does not define required method '{name}'."
                        )
                        continue
                    cand_method = getattr(candidate, name)
                    if not callable(cand_method):
                        errors.append(
                            f"Candidate {candidate!r} defines '{name}' as non-callable, "
                            f"but interface expects a method."
                        )
                        continue

                    # Compare signatures if possible
                    try:
                        iface_sig = signature(iface_attr)
                        cand_sig = signature(cand_method)
                        # Simple check: same number of parameters (excluding self)
                        iface_params = [
                            p for p in iface_sig.parameters.values()
                            if p.kind in (Parameter.POSITIONAL_OR_KEYWORD, Parameter.KEYWORD_ONLY)
                        ]
                        cand_params = [
                            p for p in cand_sig.parameters.values()
                            if p.kind in (Parameter.POSITIONAL_OR_KEYWORD, Parameter.KEYWORD_ONLY)
                        ]
                        if len(iface_params) != len(cand_params):
                            errors.append(
                                f"Method '{name}' signature mismatch: "
                                f"interface expects {len(iface_params)} args, "
                                f"candidate has {len(cand_params)}."
                            )
                    except Exception:
                        # Skip signature comparison if introspection fails
                        pass
                else:
                    # Attribute: check existence and basic type if specified
                    if not hasattr(candidate, name):
                        errors.append(
                            f"Candidate {candidate!r} does not define required attribute '{name}'."
                        )
                    else:
                        # If vtype provided, check type compatibility
                        if vtype is not None:
                            actual = getattr(candidate, name)
                            if not isinstance(actual, vtype):
                                errors.append(
                                    f"Attribute '{name}' type mismatch: expected {vtype}, "
                                    f"got {type(actual)}."
                                )
        except Exception as exc:
            errors.append(f"Error inspecting interface attribute '{name}': {exc}")

    # 3. Raise or return
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        raise Invalid(errors)

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.
    """
    import inspect
    from zope.interface import Invalid

    errors = []

    # 1. Verify the candidate declares that it provides the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise Invalid(
                    f"{candidate!r} does not provide the interface {iface!r}"
                )
        except Exception as e:
            raise Invalid(
                f"Failed to determine interface provision for {candidate!r}: {e}"
            ) from e

    # Helper to get required method names from the interface
    def _get_required_methods():
        # The zope.interface interface object stores methods in its __dict__
        # Filter items that are descriptor objects with __call__ (i.e. funcs, property, MethodDescriptor)
        methods = {}
        for name, value in iface.__dict__.items():
            # Skip any non-method entries
            if hasattr(value, "__call__") and not getattr(value, "__signature__", None):
                methods[name] = value
        return methods

    # Helper to get required attribute names from the interface
    def _get_required_attrs():
        attrs = {}
        for name, value in iface.__dict__.items():
            # Natural attributes that are not methods
            if not hasattr(value, "__call__"):
                attrs[name] = value
        return attrs

    # 2. Verify all required methods are present and have correct signatures
    required_methods = _get_required_methods()
    for name, iface_method in required_methods.items():
        if not hasattr(candidate, name):
            errors.append(f"Missing required method: {name}")
            continue
        cand_method = getattr(candidate, name)
        if not callable(cand_method):
            errors.append(f"Attribute {name} is not callable")
            continue
        # Try to compare signatures using inspect if possible
        if hasattr(iface_method, "__signature__") and hasattr(cand_method, "__signature__"):
            iface_sig = iface_method.__signature__
            cand_sig = cand_method.__signature__
        else:
            try:
                iface_sig = inspect.signature(iface_method)
            except Exception:
                iface_sig = None
            try:
                cand_sig = inspect.signature(cand_method)
            except Exception:
                cand_sig = None
        if iface_sig and cand_sig:
            if iface_sig != cand_sig:
                errors.append(
                    f"Signature mismatch for method {name}: "
                    f"expected {iface_sig}, got {cand_sig}"
                )

    # 3. Verify all required attributes are present
    required_attrs = _get_required_attrs()
    for name, _ in required_attrs.items():
        if not hasattr(candidate, name):
            errors.append(f"Missing required attribute: {name}")

    # 4. Raise aggregated errors if any
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            message = "\n".join(errors)
            raise Invalid(f"Multiple interface violations:\n{message}")

    return True

def verifyObject(iface, candidate, tentative=False):
    import inspect, zope.interface
    errors = []

    # 1. Check that the candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"Candidate {candidate!r} does not declare that it provides {iface!r}")
        except zExceptions:
            # If providedBy itself raises, treat as failure
            errors.append(f"Candidate {candidate!r} does not declare that it provides {iface!r}")

    # Helper to fetch required attributes and methods from interface
    def required_attrs():
        # Interface may expose _required_attrs or __required_attrs__
        return getattr(iface, "_required_attrs", getattr(iface, "__required_attrs__", set()))

    def required_methods():
        # Interface may expose methods as attributes; gather callable ones
        methods = {}
        for name in dir(iface):
            if name.startswith("_"):
                continue
            attr = getattr(iface, name)
            # In Zope Interface, interface methods are instances of InterfaceClassMethod
            # We consider any callable that is defined on the interface itself
            if callable(attr) and getattr(attr, "__isabstractmethod__", False):
                methods[name] = attr
        return methods

    # 2. Verify that all required attributes exist
    for name in required_attrs():
        if not hasattr(candidate, name):
            errors.append(f"Candidate {candidate!r} is missing required attribute '{name}'")

    # 3. Verify that all required methods exist and have matching signatures
    for name, iface_method in required_methods().items():
        if not hasattr(candidate, name):
            errors.append(f"Candidate {candidate!r} is missing required method '{name}'")
            continue
        cand_method = getattr(candidate, name)
        if not callable(cand_method):
            errors.append(f"Candidate {candidate!r}.{name!r} is not callable")
            continue
        # try to compare signatures
        try:
            iface_sig = inspect.signature(iface_method)
            cand_sig = inspect.signature(cand_method)
            if iface_sig != cand_sig:
                errors.append(
                    f"Signature mismatch for method '{name}': interface expects {iface_sig}, candidate provides {cand_sig}"
                )
        except ValueError:
            # If signature can't be inspected, skip
            pass

    # 4. Raise Invalid with collected errors
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            msg = "Verification failed for candidate {cand!r}:\n" + "\n".join(errors)
            exc = zope.interface.Invalid(msg)
            exc.errors = errors  # attach list of individual errors if desired
            raise exc
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # If candidate is a class, check subclass relationship
    if isinstance(candidate, type):
        try:
            if issubclass(candidate, iface):
                return True
        except Exception:
            # If iface is not a class or other error occurs, treat as tentative
            pass
        return tentative
    # If candidate is an instance, check instance relationship
    try:
        if isinstance(candidate, iface):
            return True
    except Exception:
        # If iface is not usable with isinstance, treat as tentative
        pass
    return tentative

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    Raises AttributeError or TypeError when verification fails unless
    tentative=True, in which case it returns False. On success it returns
    True.  The function accepts either a class or an instance as *candidate*.
    """
    inspect = __import__('inspect')

    # Resolve candidate to a class type
    if inspect.isclass(candidate):
        cand_cls = candidate
    else:
        cand_cls = candidate.__class__

    # Simple subclass check
    try:
        if issubclass(cand_cls, iface):
            return True
    except Exception as exc:
        if tentative:
            return False
        raise TypeError(f"Failed to check subclass relationship: {exc}") from exc

    # Build list of required attributes/methods
    required_names = []

    # Prefer abstractmethods if iface is an ABC
    if hasattr(iface, "__abstractmethods__"):
        required_names = list(iface.__abstractmethods__)
    else:
        for name, member in inspect.getmembers(iface):
            if name.startswith('_'):
                continue
            if (
                inspect.isfunction(member)
                or inspect.ismethoddescriptor(member)
                or inspect.isbuiltin(member)
            ):
                required_names.append(name)

    missing = []
    mismatched = []

    for name in required_names:
        if not hasattr(cand_cls, name):
            missing.append(name)
            continue

        iface_attr = getattr(iface, name)
        cand_attr = getattr(cand_cls, name)

        # Helper to determine kind of attribute
        def kind_of(attr):
            if inspect.isfunction(attr):
                return "function"
            if inspect.ismethoddescriptor(attr):
                return "methoddescriptor"
            if isinstance(attr, staticmethod):
                return "staticmethod"
            if isinstance(attr, classmethod):
                return "classmethod"
            return "other"

        # Helper to unwrap static/class method
        def unwrap(attr):
            if isinstance(attr, (staticmethod, classmethod)):
                return attr.__func__
            return attr

        kind_iface = kind_of(iface_attr)
        kind_candidate = kind_of(cand_attr)

        if kind_iface != kind_candidate:
            mismatched.append((name, f"expected kind '{kind_iface}', got '{kind_candidate}'"))
            continue

        # Compare signatures if possible
        try:
            sig_iface = inspect.signature(unwrap(iface_attr))
            sig_cand = inspect.signature(unwrap(cand_attr))
            if sig_iface != sig_cand:
                mismatched.append((name, f"signature mismatch {sig_iface} vs {sig_cand}"))
        except (ValueError, TypeError):
            # Some builtins may not provide signatures; ignore
            pass

    if missing or mismatched:
        if tentative:
            return False
        parts = []
        if missing:
            parts.append(f"missing attributes/methods: {missing}")
        if mismatched:
            parts.append(f"mismatched attributes: {mismatched}")
        raise AttributeError("; ".join(parts))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    Returns True if candidate satisfies the interface, otherwise
    returns False or raises an exception depending on *tentative*.
    """
    if not isinstance(iface, type):
        raise TypeError(f"iface must be a class or type, got {type(iface).__name__}")
    # Resolve the candidate's class (handle instance or class)
    candidate_cls = candidate if isinstance(candidate, type) else type(candidate)
    # Basic subclass check
    if not issubclass(candidate_cls, iface):
        if tentative:
            return False
        raise TypeError(f"{candidate_cls.__name__} does not subclass {iface.__name__}")
    # Check that all public members of iface are present on candidate
    for name in dir(iface):
        if name.startswith('_'):
            continue
        if not hasattr(candidate_cls, name):
            if tentative:
                return False
            raise AttributeError(
                f"{candidate_cls.__name__} is missing required attribute '{name}' from {iface.__name__}"
            )
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(candidate, type):
        raise TypeError(f"candidate {candidate!r} must be a class")
    # If candidate is a subclass of iface, it already satisfies the interface.
    if isinstance(iface, type):
        if issubclass(candidate, iface):
            return
        # Collect public members defined on the interface
        required = [name for name in dir(iface) if not name.startswith("_")]
        for name in required:
            if not hasattr(candidate, name):
                raise AssertionError(f"Candidate {candidate.__name__} is missing required attribute '{name}'")
            iface_attr = getattr(iface, name)
            cand_attr = getattr(candidate, name)
            # If both attributes are callables, ensure the candidate implements it
            if callable(iface_attr) and callable(cand_attr):
                if not tentative:
                    try:
                        import inspect
                        sig_iface = inspect.signature(iface_attr)
                        sig_cand = inspect.signature(cand_attr)
                        # Compare the number of required positional arguments
                        iface_params = [
                            p for p in sig_iface.parameters.values()
                            if p.default is p.empty and p.kind in (inspect.Parameter.POSITIONAL_OR_KEYWORD, inspect.Parameter.POSITIONAL_ONLY)
                        ]
                        cand_params = [
                            p for p in sig_cand.parameters.values()
                            if p.default is p.empty and p.kind in (inspect.Parameter.POSITIONAL_OR_KEYWORD, inspect.Parameter.POSITIONAL_ONLY)
                        ]
                        if len(cand_params) < len(iface_params):
                            raise AssertionError(
                                f"Method {name} on {candidate.__name__} has fewer required arguments ({len(cand_params)}) "
                                f"than required by interface ({len(iface_params)})"
                            )
                    except Exception:
                        # If signature inspection fails, skip detailed check
                        pass
    else:
        raise TypeError("iface must be a class or type")

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    Returns True if candidate appears to implement the interface, otherwise False.
    """
    import inspect

    # If candidate is the same type as iface, it's trivially valid
    if candidate is iface:
        return True

    # If concrete subclass of iface it's automatically valid
    if isinstance(candidate, type) and issubclass(candidate, iface):
        return True

    # Gather all non-private, non-dunder members from iface that are callable
    iface_members = {}
    for name, member in inspect.getmembers(iface):
        if name.startswith('_'):
            continue
        if inspect.isfunction(member) or inspect.ismethod(member):
            iface_members[name] = member

    # If iface has no callable members, consider it valid
    if not iface_members:
        return True

    # Now check each required member against candidate
    missing = []
    for name, iface_member in iface_members.items():
        cand_member = getattr(candidate, name, None)
        if cand_member is None:
            missing.append(name)
            continue
        if not (inspect.isfunction(cand_member) or inspect.ismethod(cand_member)):
            missing.append(name)
            continue

        # Optionally compare signatures if candidate is not tentative
        if not tentative:
            try:
                iface_sig = inspect.signature(iface_member)
                cand_sig = inspect.signature(cand_member)
                if iface_sig != cand_sig:
                    missing.append(name)
            except (ValueError, TypeError):
                # If signatures cannot be compared, assume mismatch
                missing.append(name)

    return not missing  # True if no missing members, else False

def determineMetaclass(bases, explicit_mc=None):
    """
    Determine metaclass from one or more base classes and an optional explicit __metaclass__.
    Mimics the logic of Python's type.__new__ when creating a new class.
    """
    # Start with the explicit metaclass if one is provided
    if explicit_mc is not None:
        mc = explicit_mc
    else:
        # If no explicit metaclass, use the metaclass of the first base
        # or the default type if there are no bases
        if bases:
            mc = type(bases[0])
        else:
            mc = type

    # Resolve any conflicts between the metaclasses of the bases
    for base in bases:
        base_meta = type(base)
        if mc is None:
            mc = base_meta
            continue

        # If the metaclasses are mutually incompatible, raise an error
        if not issubclass(base_meta, mc) and not issubclass(mc, base_meta):
            raise TypeError(
                f"metaclass conflict: {mc.__name__} vs {base_meta.__name__}"
            )

        # Prefer the more derived metaclass
        if issubclass(base_meta, mc):
            mc = base_meta

    return mc

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is None:
        if not bases:
            return type
        metas = [type(b) for b in bases]
        chosen = metas[0]
        for m in metas[1:]:
            if issubclass(chosen, m):
                pass
            elif issubclass(m, chosen):
                chosen = m
            else:
                raise TypeError(f"metaclass conflict among base classes: {chosen} vs {m}")
        for m in metas:
            if not issubclass(chosen, m):
                raise TypeError(f"metaclass conflict: {chosen} is not a subclass of {m}")
        return chosen
    else:
        if not bases:
            return explicit_mc
        metas = [type(b) for b in bases]
        for m in metas:
            if not issubclass(explicit_mc, m):
                raise TypeError(f"metaclass conflict: {explicit_mc} is not a subclass of {m}")
        return explicit_mc

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, validate it against base metaclasses
    if explicit_mc is not None:
        for base in bases:
            # type(base) is the metaclass of the base
            if not issubclass(type(base), explicit_mc):
                raise TypeError(
                    f"metaclass conflict: the explicit metaclass {explicit_mc.__name__!r} "
                    f"must be a subclass of the metaclasses of the base classes"
                )
        return explicit_mc

    # No bases: the default metaclass is `type`
    if not bases:
        return type

    # Determine the most derived metaclass among the bases
    mcls = type(bases[0])
    for base in bases[1:]:
        basem = type(base)
        if issubclass(basem, mcls):
            mcls = basem
        elif not issubclass(mcls, basem):
            raise TypeError(
                "metaclass conflict: the metaclass of a derived class must be a "
                "(non‑strict) subclass of the metaclasses of all its bases"
            )
    return mcls

def determineMetaclass(bases, explicit_mc=None):
    """
    Determine the appropriate metaclass for new class creation.
    According to Python rules:
    1. If an explicit metaclass is provided, it must be compatible with all base metaclasses.
    2. If no explicit metaclass is provided, the most derived base metaclass is chosen.
    3. If bases are empty, the default 'type' metaclass is used.
    Raises TypeError on conflicts.
    """
    # Helper: produce a simple readable metaclass name
    def _meta_name(mc):
        return getattr(mc, "__name__", str(mc))

    # Case: explicit metaclass given
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass must be a class (type), got %r" % explicit_mc)
        # If there are no bases, explicit metaclass is returned
        for base in bases:
            if not isinstance(base, type):
                continue  # skip non-type bases
            base_mc = type(base)
            # explicit_mc must be a subclass of base_mc or vice versa
            if not issubclass(explicit_mc, base_mc) and not issubclass(base_mc, explicit_mc):
                raise TypeError(
                    "metaclass conflict: %s vs %s (explicit metaclass %s does not match base %s metaclass)" %
                    (_meta_name(explicit_mc), _meta_name(base_mc), _meta_name(explicit_mc), _meta_name(base_mc))
                )
        return explicit_mc

    # No explicit metaclass
    if not bases:
        return type

    # Determine the most derived base metaclass
    # Start with the metaclass of the first base
    candidate = type(bases[0])
    for base in bases[1:]:
        if not isinstance(base, type):
            continue
        base_mc = type(base)
        # If candidate is a subclass of base_mc, candidate is more derived
        if issubclass(base_mc, candidate):
            # base_mc is more derived, update candidate
            candidate = base_mc
        elif not issubclass(candidate, base_mc):
            # They are unrelated
            raise TypeError(
                "metaclass conflict: %s vs %s" %
                (_meta_name(candidate), _meta_name(base_mc))
            )
        # else: candidate is more derived; keep as is
    return candidate

