    Format a datetime in the way that D* nodes expect.
    """
    # D* nodes expect an ISO 8601 UTC string without microseconds
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    # Split the text into tags and non‑tag parts
    tag_split_re = re.compile(r'(<[^>]+>)')
    parts = tag_split_re.split(text)

    def add_attrs_to_tag(tag):
        """Add target and rel attributes to an opening <a> tag if missing."""
        m = re.match(r'^<a\b([^>]*)>', tag, re.IGNORECASE)
        if not m:
            return tag
        attrs = m.group(1)
        if 'target=' not in attrs:
            attrs += ' target="_blank"'
        if 'rel=' not in attrs:
            attrs += ' rel="noopener noreferrer"'
        return '<a' + attrs + '>'

    result_parts = []
    for i, part in enumerate(parts):
        if not part:
            continue
        if i % 2 == 1:        # tag part
            result_parts.append(add_attrs_to_tag(part))
        else:                 # text part (outside tags)
            def repl(match):
                url = match.group(0)
                return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'
            result_parts.append(re.sub(r'(https?://[^\s<>"\'()]+)', repl, part))
    return ''.join(result_parts)

def process_text_links(text):
    import re
    from bs4 import BeautifulSoup, NavigableString

    soup = BeautifulSoup(text, 'html.parser')

    # Add attributes to existing <a> tags
    for a in soup.find_all('a'):
        a['target'] = '_blank'
        a['rel'] = 'noopener noreferrer nofollow'

    # Regex to find plain URLs or www. references that are not already part of an attribute
    url_pattern = re.compile(
        r'(?<!["\'=])\b((?:http|https|ftp)://[^\s<>"\'\]]+|www\.[^\s<>"\'\]]+)',
        flags=re.IGNORECASE)

    def replace_url(match):
        url = match.group(0)
        href = url if url.lower().startswith(('http://', 'https://', 'ftp://')) else f'http://{url}'
        return f'<a href="{href}" target="_blank" rel="noopener noreferrer nofollow">{url}</a>'

    def process_node(node):
        for child in list(node.children):
            if isinstance(child, NavigableString):
                # Replace URLs only in text nodes, not inside existing tags
                new_text = url_pattern.sub(replace_url, str(child))
                if new_text != str(child):
                    child.replace_with(BeautifulSoup(new_text, 'html.parser'))
            else:
                process_node(child)

    process_node(soup)
    return str(soup)

