def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not tag:
        return False
    # Tag must start and end with an alphanumeric character
    if not (tag[0].isalnum() and tag[-1].isalnum()):
        return False
    # Allowed characters: alphanumerics, hyphen, underscore
    for ch in tag:
        if not (ch.isalnum() or ch in ("-", "_")):
            return False
    return True

