def test_tag(tag: str) -> bool:
    """
    Test a word whether it could be accepted as a tag.
    Accepts lowercase alphanumeric and hyphens, no spaces or other punctuation,
    no leading or trailing hyphens, no consecutive hyphens, length between 1 and 50.
    """
    if not isinstance(tag, str):
        return False
    if not tag:
        return False
    if len(tag) > 50:
        return False
    if tag[0] == '-' or tag[-1] == '-':
        return False
    if '--' in tag:
        return False
    if tag != tag.lower():
