def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if not sender_handle:
        raise ValueError("Sender handle is missing.")
    if not entity_handle:
        raise ValueError("Entity handle is missing.")
    if sender_handle != entity_handle:
        raise ValueError(
            f"Sender handle '{sender_handle}' does not match entity handle '{entity_handle}'."
        )
    return True

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Default path for NodeInfo document if not provided
    if document_path is None:
        document_path = "/nodeinfo/2.0"
    # Ensure document_path starts with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path
    # Strip trailing slash from base url to avoid double slash
    base = url.rstrip("/")
    href = base + document_path
    return {
        "links": [
            {
                # The rel corresponds to the NodeInfo schema version
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Determine the path to the well-known document
    path = document_path if document_path is not None else "/.well-known/nodeinfo"
    # Ensure the path starts with a slash
    if not path.startswith("/"):
        path = "/" + path
    # Build full href
    href = f"{url.rstrip('/')}{path}"
    # Return the NodeInfo .well-known JSON structure
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        doc_tree = etree.fromstring(doc.encode('utf-8'))
    except Exception as e:
        raise ValueError(f"Invalid XML document: {e}")

    # Find the Signature element
    signed_info = doc_tree.find('.//{http://www.w3.org/2000/09/xmldsig#}Signature')
    if signed_info is None:
        raise ValueError("No Signature element found in the document")

    # Compare SignatureValue with provided signature if provided
    if signature:
        sig_value_node = signed_info.find('.//{http://www.w3.org/2000/09/xmldsig#}SignatureValue')
        if sig_value_node is None:
            raise ValueError("SignatureValue element missing from Signature")
        if sig_value_node.text.strip() != signature.strip():
            return False

    # Setup the signature context
    ctx = xmlsec.SignatureContext()
    try:
        key = xmlsec.Key.from_memory(public_key, xmlsec.constants.KeyDataFormatCertPem)
    except Exception as e:
        raise ValueError(f"Failed to load public key: {e}")

    ctx.key = key

    # Verify the signature
    try:
        ctx.verify(signed_info)
        return True
    except xmlsec.VerificationError:
        return False
    except Exception as e:
        raise ValueError(f"Signature verification failed: {e}")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Attempt JSON parsing first
    try:
        data = json.loads(document)
        if isinstance(data, dict) and 'subject' in data:
            # Ensure aliases is a list
            aliases = data.get('aliases')
            if aliases is None:
                data['aliases'] = []
            elif not isinstance(aliases, list):
                data['aliases'] = [aliases]
            # Ensure links is a list
            links = data.get('links')
            if links is None:
                data['links'] = []
            elif not isinstance(links, list):
                data['links'] = [links]
            return data
    except json.JSONDecodeError:
        pass

    # If not JSON, try XRD parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        # If parsing fails, return empty dict
        return {}

    def localname(tag: str) -> str:
        return tag.split('}', 1)[-1] if '}' in tag else tag

    subject = None
    aliases: list[str] = []
    links: list[dict] = []

    for elem in root.iter():
        tag = localname(elem.tag)
        if tag == 'Subject':
            if elem.text:
                subject = elem.text.strip()
        elif tag == 'Alias':
            if elem.text:
                alias = elem.text.strip()
                if alias:
                    aliases.append(alias)
        elif tag == 'Link':
            rel = elem.attrib.get('rel')
            href = elem.attrib.get('href')
            link_dict: dict[str, str] = {}
            if rel:
                link_dict['rel'] = rel
            if href:
                link_dict['href'] = href
            # Include any additional attributes
            for k, v in elem.attrib.items():
                if k not in ('rel', 'href'):
                    link_dict[k] = v
            links.append(link_dict)

    return {'subject': subject, 'aliases': aliases, 'links': links}

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old)."""
    import json
    from xml.etree import ElementTree as ET
    try:
        data = json.loads(document)
        # Return a simplified dict containing common fields
        return {
            "aliases": data.get("aliases", []),
            "links": data.get("links", []),
            "subject": data.get("subject"),
        }
    except json.JSONDecodeError:
        # Try parsing as XRD (XML)
        try:
            root = ET.fromstring(document)
        except ET.ParseError as e:
            raise ValueError(f"Unable to parse webfinger document: {e}")

        # Detect namespace if present
        ns = ""
        if root.tag.startswith("{"):
            ns = root.tag[1:root.tag.index("}")]
        # Helper to qualify tags
        def q(tag):
            return f"{{{ns}}}{tag}" if ns else tag

        # Extract aliases
        aliases = [a.text for a in root.findall(q("Alias")) if a.text]

        # Extract links
        links = []
        for link in root.findall(q("Link")):
            link_dict = {k: v for k, v in link.attrib.items()}
            links.append(link_dict)

        return {
            "aliases": aliases,
            "links": links,
            "subject": root.attrib.get("xmlns")  # not really subject, placeholder
        }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json, xml.etree.ElementTree as ET
    document = document.strip()
    # Try JSON first
    if document.startswith('{') or document.startswith('['):
        try:
            return json.loads(document)
        except json.JSONDecodeError:
            pass  # fall back to XRD

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        # Invalid XML – return empty dict
        return {}

    # Remove namespace from tags for easier access
    def _strip_ns(element):
        if element.tag[0] == '{':
            element.tag = element.tag.split('}', 1)[1]
        for e in element:
            _strip_ns(e)

    _strip_ns(root)

    result = {}
    subject = root.findtext('subject')
    if subject:
        result['subject'] = subject

    links = []
    for link_elem in root.findall('Link'):
        link = {}
        for attr in ['rel', 'href', 'type', 'title']:
            val = link_elem.attrib.get(attr)
            if val:
                link[attr] = val
        # optionally capture templating attribute
        templating = link_elem.attrib.get('templating')
        if templating is not None:
            # Convert string to boolean if possible
            if templating.lower() in ('true', '1'):
                templating = True
            elif templating.lower() in ('false', '0'):
                templating = False
            link['templating'] = templating
        if link:
            links.append(link)

    if links:
        result['links'] = links

    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    def _strip_ns(tag: str) -> str:
        return tag.split('}', 1)[-1] if '}' in tag else tag

    # Try JSON parsing first
    try:
        result = json.loads(document)
        if isinstance(result, dict):
            return result
    except Exception:
        pass

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
    except Exception:
        return {}

    # If root is XRD
    if _strip_ns(root.tag).upper() != 'XRD':
        return {}

    # Extract subject
    subject_elem = root.find('.//Subject')
    subject = subject_elem.text if subject_elem is not None else None

    # Extract aliases
    aliases = []
    for alias_elem in root.findall('.//Alias'):
        if alias_elem.text:
            aliases.append(alias_elem.text)

    # Extract links
    links = []
    for link_elem in root.findall('.//Link'):
        link_attrs = {}
        for key, value in link_elem.attrib.items():
            link_attrs[key] = value
        links.append(link_attrs)

    return {
        'subject': subject,
        'aliases': aliases,
        'links': links
    }

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).
    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        if isinstance(data, dict) and 'subject' in data and 'links' in data:
            return data
    except Exception:
        pass

    try:
        root = ET.fromstring(document)
    except Exception:
        return {}

    # Strip XML namespaces to make tag access simpler
    for elem in root.iter():
        if '}' in elem.tag:
            elem.tag = elem.tag.split('}', 1)[1]

    subject_elem = root.find('Subject')
    subject = subject_elem.text if subject_elem is not None else None

    links = []
    for link_elem in root.findall('Link'):
        rel = link_elem.get('rel')
        href = link_elem.get('href')
        if rel is None or href is None:
            continue
        link = {'rel': rel, 'href': href}
        type_ = link_elem.get('type')
        if type_:
            link['type'] = type_
        links.append(link)

    return {'subject': subject, 'links': links}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        _, domain = handle.split("@", 1)
        if not domain:
            return None
    except ValueError:
        return None

    url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"
    try:
        response = requests.get(url, timeout=5)
        if response.status_code == 200:
            return response.text
    except Exception:
        pass
    return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document for the given handle.
    The handle should be in the form 'user@domain' or 'acct:user@domain'.
    Returns the document as a string if successful, otherwise returns None.
    """
    try:
        # Normalize handle to 'user@domain' format
        if not handle:
            return None
        if handle.startswith("acct:"):
            handle = handle[5:]
        if "@" not in handle:
            return None
        user, domain = handle.split("@", 1)
        # Build the WebFinger URL
        url = f"https://{domain}/.well-known/webfinger"
        params = {"resource": f"acct:{user}@{domain}"}
        # Perform the HTTP GET with a short timeout
        response = requests.get(url, params=params, timeout=5)
        if response.status_code == 200:
            return response.text
    except Exception:
        # Swallow all exceptions silently
        pass
    return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    if not isinstance(handle, str) or "@" not in handle:
