    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    import urllib.request, urllib.parse, urllib.error, json

    if '@' not in handle:
        raise ValueError("Handle must be in the form user@example.com")
    resource = f"acct:{handle}"
    encoded_resource = urllib.parse.quote(resource, safe='')
    host = handle.split('@', 1)[1]
    url = f"https://{host}/.well-known/webfinger?resource={encoded_resource}"
    request = urllib.request.Request(url, headers={"Accept": "application/jrd+json"})

    try:
        with urllib.request.urlopen(request, timeout=10) as response:
            if response.status != 200:
                raise ValueError(f"Failed to retrieve webfinger document. HTTP status: {response.status}")
            body = response.read().decode('utf-8')
            return json.loads(body)
    except urllib.error.HTTPError as e:
        raise ValueError(f"HTTPError retrieving webfinger: {e}") from e
    except urllib.error.URLError as e:
        raise ValueError(f"URLError retrieving webfinger: {e}") from e
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to parse JSON from webfinger response: {e}") from e

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve (e.g., "alice@example.com")
    :returns: dict containing 'subject', 'aliases', and 'links' mapping rel -> href
    """
    import requests

    if not isinstance(handle, str) or '@' not in handle:
        raise ValueError("handle must be a non-empty string of the form 'user@domain'")

    domain = handle.split('@', 1)[1]
    resource = f'acct:{handle}'
    url = f'https://{domain}/.well-known/webfinger'
    params = {'resource': resource}

    try:
        resp = requests.get(url, params=params, headers={'Accept': 'application/json'}, timeout=10)
    except requests.RequestException as exc:
        raise RuntimeError(f"Failed to retrieve webfinger for {handle}") from exc

    if resp.status_code != 200:
        raise RuntimeError(f"Webfinger request returned status {resp.status_code} for {handle}")

    try:
        data = resp.json()
    except ValueError as exc:
        raise RuntimeError(f"Non‑JSON response for {handle}") from exc

    links = {}
    for link in data.get('links', []):
        rel = link.get('rel')
        href = link.get('href')
        if rel and href:
            links[rel] = href

    return {
        'subject': data.get('subject'),
        'aliases': data.get('aliases', []),
        'links': links
    }

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host‑meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not isinstance(host, str):
        raise TypeError("host must be a string")

    # Build URL for the host‑meta resource
    if not host.startswith(("http://", "https://")):
        base = f"https://{host}"
    else:
        base = host.rstrip("/")
    url = f"{base}/.well-known/host-meta"

    try:
        import requests
        resp = requests.get(url, timeout=5)
        resp.raise_for_status()
    except Exception as exc:            # pragma: no cover
        raise RuntimeError(f"Unable to fetch host‑meta from {url}") from exc

    # Attempt to parse the response as an XRD instance
    try:
        # If the response is XML
        return XRD.from_xml(resp.text)
    except Exception:  # pragma: no cover
        try:
            # Try JSON fallback
            return XRD.from_json(resp.json())
        except Exception as exc:  # pragma: no cover
            raise RuntimeError("The host‑meta document could not be parsed as XRD") from exc

