def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments
    """
    keys_chain = [key] + list(keys)
    cur = dic
    for k in keys_chain[:-1]:
        if k not in cur or not isinstance(cur[k], dict):
            cur[k] = {}
        cur = cur[k]
    cur[keys_chain[-1]] = val
    return dic

def list_of_file_names(settings_dirs, spec_option):
    """
    Create a new IniType complex type
    """
    import os
    if isinstance(settings_dirs, str):
        settings_dirs = [settings_dirs]
    files = []
    for d in settings_dirs:
        if not os.path.isdir(d):
            continue
        for entry in os.listdir(d):
            full_path = os.path.join(d, entry)
            if os.path.isfile(full_path):
                if spec_option:
                    # if spec_option is a file extension like '.ini'
                    if entry.lower().endswith(spec_option.lower()):
                        files.append(full_path)
                else:
                    files.append(full_path)
    return sorted(files)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Collect file paths matching the spec_option pattern from each directory in settings_dirs.
    file_names = []
    for dir_path in settings_dirs:
        try:
            # list all entries in the directory
            for entry in os.listdir(dir_path):
                # filter entries that match the spec_option pattern
                if fnmatch.fnmatch(entry, spec_option):
                    file_names.append(os.path.join(dir_path, entry))
        except OSError:
            # Skip directories that cannot be accessed
            continue
    return file_names

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file paths found in the given directories that match
    the optional specifier pattern. If spec_option is None, all files are
    returned. Directories are skipped and the results are sorted.
    """
    import os
    from pathlib import Path
    # Ensure settings_dirs is iterable
    if isinstance(settings_dirs, (str, Path)):
        dirs = [settings_dirs]
    else:
        dirs = settings_dirs
    result = []
    # Normalize pattern: if spec_option is a glob pattern, use glob
    use_glob = False
    if spec_option:
        use_glob = True
        pattern = spec_option
    else:
        pattern = None
    for d in dirs:
        d = Path(d)
        if not d.is_dir():
            continue
        if use_glob:
            # Resolve pattern relative to directory
            for path in d.glob(pattern):
                if path.is_file():
                    result.append(str(path.resolve()))
        else:
            for entry in d.iterdir():
                if entry.is_file():
                    result.append(str(entry.resolve()))
    return sorted(result)

