def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        # Retrieve and remove the include directive
        includes = parser_dict.pop('include', [])
        if not isinstance(includes, list):
            includes = [includes]

        def _merge(dest, src):
            """Recursively merge src into dest."""
            for key, val in src.items():
                if key in dest and isinstance(dest[key], dict) and isinstance(val, dict):
                    _merge(dest[key], val)
                else:
                    dest[key] = val

        for path in includes:
            # Resolve file path relative to current working directory
            full_path = os.path.join(os.getcwd(), path)
            with open(full_path, 'r', encoding='utf-8') as f:
                try:
                    inc_data = yaml.safe_load(f) or {}
                except Exception:
                    inc_data = {}
            _merge(parser_dict, inc_data)

        return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # No work if parser_dict is not a dict
    if not isinstance(parser_dict, dict):
        return parser_dict

    # Key that may contain include directives
    include_keys = ["include", "include_dict", "groups_include"]
    include_paths = []

    # Collect all include paths from any of the supported keys
    for key in include_keys:
        if key in parser_dict:
            val = parser_dict.pop(key)
            if isinstance(val, (list, tuple)):
                include_paths.extend(val)
            else:
                include_paths.append(val)

    # If there is no include directive, simply return the dictionary
    if not include_paths:
        return parser_dict

    # Resolve include paths relative to the file that contains parser_dict
    # We assume that self.spec_file holds the full path of the current spec file.
    current_dir = os.path.dirname(self.spec_file)

    for inc in include_paths:
        inc_path = os.path.join(current_dir, inc)
        if not os.path.isfile(inc_path):
            continue  # skip missing includes silently

        with open(inc_path, "r", encoding="utf-8") as fp:
            try:
                inc_dict = yaml.safe_load(fp)
            except Exception:
                continue  # ignore files that can't be parsed

        # Recursively resolve includes inside the included file
        inc_dict = self._include_groups(inc_dict)

        # Merge groups from the included file
        inc_groups = inc_dict.pop("groups", {})
        if isinstance(inc_groups, dict):
            parser_dict.setdefault("groups", {}).update(inc_groups)

        # Merge other top‑level keys that are not overridden by this file
        for k, v in inc_dict.items():
            if k not in parser_dict and k != "groups":
                parser_dict[k] = v

    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    import os, json
    try:
        import yaml  # type: ignore
    except ImportError:
        yaml = None

    # Helper to load a file (JSON or YAML)
    def _load_file(path):
        _, ext = os.path.splitext(path)
        with open(path, "r", encoding="utf-8") as f:
            if ext.lower() == ".json":
                return json.load(f)
            elif yaml is not None:
                return yaml.safe_load(f)
            else:
                raise RuntimeError(f"Cannot parse file {path}: unsupported format and yaml not available")

    # Recursively process a dict (or list) to resolve nested includes
    def _process(item):
        if isinstance(item, dict):
            # Resolve nested dictionaries first
            for k, v in list(item.items()):
                item[k] = _process(v)
            # Handle include directive if present
            if "include" in item:
                includes = item.pop("include")
                if not isinstance(includes, list):
                    includes = [includes]
                for inc in includes:
                    if isinstance(inc, str):
                        inc_path = inc
                    elif isinstance(inc, dict):
                        inc_path = inc.get("file") or inc.get("path") or inc.get("name")
                    else:
                        continue
                    if not inc_path:
                        continue
                    # Resolve relative path against the spec's base directory if set
                    if not os.path.isabs(inc_path):
                        base_dir = getattr(self, "_base_dir", ".")
                        inc_path = os.path.join(base_dir, inc_path)
                    included = _load_file(inc_path)
                    # Merge included content into current dictionary
                    if isinstance(included, dict):
                        item.update(_process(included))
                    else:
                        # If included content is not a dict, wrap it under a key
                        item.setdefault("included", []).append(included)
        elif isinstance(item, list):
            return [_process(v) for v in item]
        return item

    return _process(parser_dict)

