def get_spec_defaults(self):
    """
    Resolve arguments' values from the specification and any additional sources
    (such as provided defaults or environment variables). The resolved values
    are merged into ``self.args`` and returned as a dictionary.
    """
    # Prepare a mutable copy of the user‑supplied arguments
    resolved = dict(getattr(self, "args", {}))

    # 1. Merge any predefined defaults on the object itself (e.g. self.defaults)
    obj_defaults = getattr(self, "defaults", {})
    if isinstance(obj_defaults, dict):
        for key, val in obj_defaults.items():
            if key not in resolved:
                resolved[key] = val

    # 2. Pull defaults from the specification (OpenAPI style)
    spec = getattr(self, "spec", {})
    if isinstance(spec, dict):
        # Path / query / header parameters
        for param in spec.get("parameters", []):
            pname = param.get("name")
            if not pname:
                continue
            if pname in resolved:
                continue
            schema = param.get("schema", {})
            if "default" in schema:
                resolved[pname] = schema["default"]

        # Request body defaults
        request_body = spec.get("requestBody", {})
        content = request_body.get("content", {})
        for media_type in content.values():
            schema = media_type.get("schema", {})
            if "default" in schema and "body" not in resolved:
                resolved["body"] = schema["default"]
                break

    # 3. Environment variables (last resort)
    for key in list(resolved.keys()):
        env_key = key.upper()
        if env_key in os.environ and resolved[key] is None:
            resolved[key] = os.environ[env_key]

    # Update the object's args with the resolved values
    self.args = resolved
    return resolved

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    # Deprecated options mapped to their replacements
    # Example:
    #     'old_option': 'new_option',
    return {}

def get_deprecated_args(self):
    """Return a mapping from deprecated option names to their replacements."""
    return {
        'old_option_name': 'new_option_name',
        'legacy_enabled': 'enable_feature',
        'using_legacy': 'use_new_feature'
    }

def get_deprecated_args(self):
    """
    Return a dictionary mapping deprecated option names to their replacement option names.
    """
    return {
        "old_option": "new_option",
        "legacy_flag": "modern_flag",
    }

def validate_arg_deprecation(self, cli_args, answer_file_args):
    import sys
    deprecated = getattr(self, "deprecated_args", {})
    if not deprecated:
        return
    for source, args_dict in [("command line", cli_args), ("answer file", answer_file_args)]:
        for old_arg, new_arg in deprecated.items():
            if old_arg in args_dict:
                sys.stderr.write(
                    f"WARNING: Argument '{old_arg}' from {source} is deprecated; "
                    f"use '{new_arg}' instead.\n"
                )

def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        # Determine deprecated arguments mapping. Keys are deprecated
        # argument names, values are optional suggestions for new names.
        deprecated_map = getattr(self, "deprecated_args", {})
        if isinstance(deprecated_map, list):
            # If a list is provided, treat elements as deprecated names with no suggestion.
            deprecated_map = {name: None for name in deprecated_map}
        if not isinstance(deprecated_map, dict):
            # No deprecation information available, nothing to validate.
            return
        for old_arg, new_arg in deprecated_map.items():
            used_in_cli = old_arg in cli_args and cli_args[old_arg] is not None
            used_in_ans = old_arg in answer_file_args and answer_file_args[old_arg] is not None
            if used_in_cli or used_in_ans:
                message = f"Argument '{old_arg}' is deprecated and will be removed in a future release."
                if new_arg:
                    message += f" Use '{new_arg}' instead."
                print(message)

def get_parser_option_specs(self, command_name):
        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        # Retrieve the parser instance for the requested command
        parser, _ = self._get_parser_and_labels(command_name)

        # If the parser exposes a dedicated method to list its option specs, use it
        if hasattr(parser, 'get_option_specs'):
            return parser.get_option_specs()

        # Fall back to inspecting the parser's attributes (common with argparse/Click)
        if hasattr(parser, 'option_specifiers'):
            return parser.option_specifiers

        # If it's an argparse.Namespace, return its dict of attributes
        if hasattr(parser, '__dict__') and hasattr(parser, 'parse_known_args'):
            return vars(parser)

        # Unable to determine options format
        raise AttributeError(f"Parser for command '{command_name}' does not expose option specs.")

def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    parser = getattr(self, 'parser', None)
    if parser is None:
        return []

    # Attempt to find a subparser for the requested command
    if hasattr(parser, 'choices') and command_name in parser.choices:
        subparser = parser.choices[command_name]
        # argparse stores optionals in 'optionals' attribute
        return getattr(subparser, 'optionals', [])

    # Fallback: use any stored per-command option mapping
    return getattr(self, '_command_options', {}).get(command_name, [])

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Retrieve the command descriptor; assume commands is a dict mapping names to descriptors
    cmd = getattr(self, 'commands', {}).get(command_name)
    if cmd is None:
        raise KeyError(f"Command '{command_name}' not found.")
    # Try common keys for option collections
    options = cmd.get('options') or cmd.get('args') or cmd.get('parameters') or {}
    if not isinstance(options, dict):
        raise TypeError(f"Expected options mapping for command '{command_name}', got {type(options).__name__}.")
    spec = options.get(argument_name)
    if spec is None:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'.")
    return spec

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    if not hasattr(self, 'command_specs'):
        raise AttributeError("Missing 'command_specs' attribute on instance.")
    if command_name not in self.command_specs:
        raise KeyError(f"Command '{command_name}' not registered.")
    command_spec = self.command_specs[command_name]
    if argument_name not in command_spec:
        raise KeyError(f"Option '{argument_name}' not found for command '{command_name}'.")
    return command_spec[argument_name]

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Retrieve the command specification; raise an informative error if missing
    command_spec = self._commands.get(command_name)
    if command_spec is None:
        raise KeyError(f"Unknown command '{command_name}'")

    # Fetch the options mapping; support common attribute or dict forms
    options = getattr(command_spec, "options", None)
    if options is None:
        options = getattr(command_spec, "opts", None)
    if options is None:
        options = command_spec.get("options") if isinstance(command_spec, dict) else {}

    # Look up the specific option
    option_spec = options.get(argument_name)
    if option_spec is None:
        raise KeyError(f"Unknown option '{argument_name}' for command '{command_name}'")

    return option_spec

def get_silent_args(self, args):
    """
    Return the names of arguments that are considered "silent" – i.e. those
    whose value is either None, False, an empty string, or otherwise falsy.
    The input `args` may be a mapping or an object with attributes.
    """
    silent = []

    # If args is a dictionary-like object, iterate over items.
    if isinstance(args, dict):
        for key, value in args.items():
            if value in (None, False, ""):
                silent.append(key)
        return silent

    # Otherwise, treat args as an object and inspect its attributes.
    for attr in dir(args):
        if attr.startswith("_"):
            continue
        try:
            value = getattr(args, attr)
        except AttributeError:
            continue
        if value in (None, False, ""):
            silent.append(attr)

    return silent

def get_silent_args(self, args):
    """Return the names of arguments that are considered silent
    (None, empty string, or False)."""
    if not isinstance(args, dict):
        return []
    silent_keys = []
    for key, value in args.items():
        if value is None or value == '' or value is False:
            silent_keys.append(key)
    return silent_keys

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # If no arguments provided, return an empty list
    if not args:
        return []

    # If args are passed as a dictionary, return keys that start with an underscore
    if isinstance(args, dict):
        return [key for key in args.keys() if isinstance(key, str) and key.startswith("_")]

    # If args are passed as a list or tuple of strings, filter by leading underscore
    if isinstance(args, (list, tuple)):
        return [arg for arg in args if isinstance(arg, str) and arg.startswith("_")]

    # For any other type, attempt to iterate and filter string items
    try:
        return [item for item in args if isinstance(item, str) and item.startswith("_")]
    except TypeError:
        # If args is not iterable or not a suitable type, return an empty list
        return []

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")
    required = getattr(self, 'required', getattr(self, 'requires', []))
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")
    missing = [key for key in getattr(self, 'required_args', [])
               if key not in args or args[key] is None]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    required = getattr(self, 'required_args', [])
    missing = [name for name in required if name not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec: the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    conditionally_required = []

    for opt in options_spec:
        opt_name = opt.get('name')
        if not opt_name:
            continue

        required_when = opt.get('required_when')
        if required_when is None:
            continue

        matched = False
        try:
            if callable(required_when):
                # If it's a function, call it with args
                matched = bool(required_when(args))
            elif isinstance(required_when, dict):
                # All key/value pairs must match the current args
                matched = True
                for key, value in required_when.items():
                    if isinstance(value, bool):
                        # value True means key must be present, False means absent
                        if value and key not in args:
                            matched = False
                            break
                        if not value and key in args:
                            matched = False
                            break
                    else:
                        if args.get(key) != value:
                            matched = False
                            break
            elif isinstance(required_when, (list, tuple)):
                # All items in the list must evaluate to True
                matched = all(self._get_conditionally_required_args(
                    command_name, [{'name': key, 'required_when': cond}], args
                ) for key, cond in required_when)
            elif isinstance(required_when, str):
                # Treat string as a flag that must be present
                matched = required_when in args or args.get(required_when) is not None
            else:
                # Fallback: any truthy value means requirement applies
                matched = bool(required_when)
        except Exception:
            matched = False

        if matched:
            conditionally_required.append(opt_name)

    return conditionally_required

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        required = set()
        # Determine which spec(s) apply to the given command_name
        for spec in options_spec:
            # If spec defines a command and it doesn't match, skip it
            if 'command' in spec and spec['command'] != command_name:
                continue
            arg_specs = spec.get('args', []) if isinstance(spec, dict) else []
            for arg_spec in arg_specs:
                name = arg_spec.get('name')
                cond = arg_spec.get('required_when')
                if not cond:
                    continue
                matched = False
                try:
                    if callable(cond):
                        matched = bool(cond(args))
                    elif isinstance(cond, str):
                        # Evaluate the condition string in a context where `args` is available
                        matched = bool(eval(cond, {}, {'args': args}))
                    else:
                        # Unsupported condition type; ignore
                        continue
                except Exception:
                    # If evaluation fails, treat as not matched
                    continue
                if matched and name:
                    required.add(name)
        return list(required)

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        for opt in options_spec:
            if not isinstance(opt, dict):
                continue
            if 'required_when' not in opt:
                continue

            cond = opt['required_when']
            matched = False

            # If the condition is a string, interpret it as a command name.
            if isinstance(cond, str):
                matched = cond == command_name

            # If the condition is a list, treat it as a list of command names.
            elif isinstance(cond, (list, tuple)):
                matched = command_name in cond

            # If the condition is a dict, look for 'commands' and optional
            # argument/value checks.
            elif isinstance(cond, dict):
                cmds = cond.get('commands', ())
                if command_name in cmds:
                    arg_checks = cond.get('args')
                    if arg_checks:
                        # Ensure that every specified argument satisfies its
                        # expected value.  If args is not a mapping, skip this
                        # part of the check.
                        if isinstance(args, dict):
                            satisfied = all(
                                args.get(a_key) == a_val
                                for a_key, a_val in arg_checks.items()
                            )
                        else:
                            # Without a dict structure we cannot verify; assume
                            # satisfied.
                            satisfied = True
                        matched = satisfied
                    else:
                        matched = True

            if matched:
                name = opt.get('name')
                if name and name not in required:
                    required.append(name)

        return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    Return a list of argument names whose ``required_when`` condition
    matched the supplied ``args``.
    """
    required = []

    for opt in options_spec:
        cond = opt.get('required_when')
        if not cond:
            continue

        # Callable condition (function/lambda)
        if callable(cond):
            try:
                if cond(args):
                    required.append(opt['name'])
            except Exception:
                pass
            continue

        # Dictionary condition: {other_option: expected_value}
        if isinstance(cond, dict):
            matched = True
            for key, expected in cond.items():
                val = args.get(key)
                if isinstance(expected, (list, tuple)):
                    if val not in expected:
                        matched = False
                        break
                else:
                    if val != expected:
                        matched = False
                        break
            if matched:
                required.append(opt['name'])
            continue

        # List of (option, value) tuples condition
        if isinstance(cond, (list, tuple)):
            matched = True
            for item in cond:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    key, expected = item
                    val = args.get(key)
                    if isinstance(expected, (list, tuple)):
                        if val not in expected:
                            matched = False
                            break
                    else:
                        if val != expected:
                            matched = False
                            break
            if matched:
                required.append(opt['name'])
            continue

        # Single key string condition, requires presence of key in args
        if isinstance(cond, str):
            if cond in args:
                required.append(opt['name'])
            continue

    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # self.length_spec should be a mapping of argument names to maximum allowed lengths.
    # Example: self.length_spec = {'name': 50, 'email': 100}
    if not hasattr(self, 'length_spec') or not isinstance(self.length_spec, dict):
        return  # nothing to validate if no spec provided

    for key, value in args.items():
        max_len = self.length_spec.get(key)
        if max_len is None:
            # No length constraint for this argument
            continue

        # Determine the length based on the type of the value
        if isinstance(value, (str, list, tuple, dict)):
            length = len(value)
        elif isinstance(value, (int, float, bool)):
            # Scalars are considered length 1
            length = 1
        else:
            # For other objects, try to use the length attribute or skip
            try:
                length = len(value)
            except Exception:
                continue

        if length > max_len:
            raise ValueError(f"Argument '{key}' exceeds maximum allowed length of {max_len} (actual length: {length}).")

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # Expected: args is a dictionary mapping argument names to their values.
        # The class should keep a mapping of argument specifications (e.g., max_length).
        arg_specs = getattr(self, "arg_specs", {})
        for name, value in args.items():
            spec = arg_specs.get(name, {})
            max_len = spec.get("max_length")
            if max_len is None:
                continue  # No length constraint for this argument
            try:
                length = len(value)
            except TypeError:
                # If the value does not support len(), skip length validation
                continue
            if length > max_len:
                raise ValueError(
                    f"Argument '{name}' length {length} exceeds maximum allowed {max_len}"
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for key, value in args.items():
        if key in getattr(self, "choices", {}):
            allowed = self.choices[key]
            if isinstance(value, (list, tuple, set)):
                for item in value:
                    if item not in allowed:
                        raise ValueError(
                            f"Invalid choice for '{key}': {item}. "
                            f"Allowed choices are: {allowed}"
                        )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"Invalid choice for '{key}': {value}. "
                        f"Allowed choices are: {allowed}"
                    )

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Iterate over all defined arguments that may have a 'choices' attribute.
        for name, definition in getattr(self, "arguments", {}).items():
            # Skip checks for arguments not supplied.
            if name not in args:
                continue
            value = args[name]
            # Some argument definitions may store available choices in a 'choices' attribute.
            choices = getattr(definition, "choices", None)
            if choices is None:
                continue
            # Normalise choices to an iterable for 'in' checks.
            if isinstance(choices, (set, list, tuple)):
                if value not in choices:
                    raise ValueError(
                        f"Invalid value for argument '{name}': {value!r}. "
                        f"Expected one of {tuple(choices)}."
                    )
            else:
                # If choices is callable or a custom type, try calling it to validate.
                try:
                    if not choices(value):
                        raise ValueError
                except Exception:
                    raise ValueError(
                        f"Argument '{name}' value {value!r} does not satisfy the provided choices."
                    )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments as a dict.
    """
    # Iterate through each argument definition that specifies a set of
    # allowable choices and verify that the supplied value belongs to that
    # set. Any violation raises a ValueError with a clear error message.
    arg_defs = getattr(self, "arguments", {})
    for name, definition in arg_defs.items():
        if "choices" in definition:
            allowed = definition["choices"]
            value = args.get(name)
            # Support destinations that are sequences of values: ensure each
            # element is within the allowed set.
            if isinstance(value, (list, tuple)):
                if any(v not in allowed for v in value):
                    bad = [v for v in value if v not in allowed]
                    raise ValueError(
                        f"Argument '{name}' contains invalid choice(s) {bad}. "
                        f"Allowed values are {allowed}."
                    )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"Argument '{name}' must be one of {allowed}, got {value}."
                    )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. This method expects ``args`` to be a mapping where each value
                 is either a tuple/list ``(value, min, max)`` or a dictionary with keys
                 ``'value'`` , ``'min'`` and ``'max'``.  Values that are ``None`` are ignored.
    """
    # Iterate over each argument in the mapping
    for name, spec in args.items():
        # Skip invalid spec entries
        if spec is None:
            continue

        # Try to unpack a tuple/list spec of the form (value, min, max)
        if isinstance(spec, (list, tuple)) and len(spec) == 3:
            value, min_value, max_value = spec
        # Otherwise, try a dict with 'value', 'min', 'max' keys
        elif isinstance(spec, dict):
            if not {'value', 'min', 'max'}.issubset(spec):
                raise TypeError(f"Argument spec for '{name}' must contain 'value', 'min', and 'max' keys")
            value, min_value, max_value = spec['value'], spec['min'], spec['max']
        else:
            raise TypeError(f"Argument spec for '{name}' must be a tuple/list of (value, min, max) or a dict with 'value', 'min', 'max' keys")

        # Skip validation if the value is None
        if value is None:
            continue

        # Validate the value lies within the specified inclusive bounds
        if not (min_value <= value <= max_value):
            raise ValueError(
                f"Argument '{name}' has value {value!r} outside allowed range "
                f"({min_value!r} .. {max_value!r})"
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.
    :param args: The received arguments.
    """
    # Expect instance to have `min_value` and `max_value` attributes
    min_val = getattr(self, 'min_value', None)
    max_val = getattr(self, 'max_value', None)
    if min_val is None or max_val is None:
        raise AttributeError("`min_value` or `max_value` attribute is not defined on the instance")
    if not isinstance(args, dict):
        raise TypeError("`args` must be a mapping (dict) of argument names to values")
    for key, value in args.items():
        if not isinstance(value, (int, float)):
            raise TypeError(f"Argument '{key}' must be a numeric type (int or float)")
        if value < min_val or value > max_val:
            raise ValueError(f"Argument '{key}' with value {value} is outside "
                             f"the allowed range [{min_val}, {max_val}]")
    return True

def validate_min_max_args(self, args):
        """
        Check if value of arguments is between minimum and maximum values.
        Raises a ValueError if any argument falls outside its allowed range.
        """
        # If no specifications are defined, nothing to validate
        if not hasattr(self, 'arg_specs'):
            return

        for name, value in args.items():
            spec = self.arg_specs.get(name)
            if not spec:
                continue  # No min/max constraints for this argument

            min_val = spec.get('min')
            max_val = spec.get('max')

            if min_val is not None and value < min_val:
                raise ValueError(f"Argument '{name}' with value {value} is less than minimum allowed {min_val}.")

            if max_val is not None and value > max_val:
                raise ValueError(f"Argument '{name}' with value {value} exceeds maximum allowed {max_val}.")

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict")
    class ComplexArgument:
        def __init__(self, value):
            if spec_option.get('required', False) and value is None:
                raise ValueError(f"The option '{option_name}' is required for subcommand '{subcommand}'")
            if 'convert' in spec_option and callable(spec_option['convert']):
                try:
                    value = spec_option['convert'](value)
                except Exception as exc:
                    raise ValueError(f"Failed to convert option '{option_name}' for subcommand '{subcommand}': {exc}")
            if 'choices' in spec_option:
                if value not in spec_option['choices']:
                    raise ValueError(f"Invalid value '{value}' for option '{option_name}'. Allowed: {spec_option['choices']}")
            self.value = value
            self.description = spec_option.get('help', '')
            self.choices = spec_option.get('choices')
        def __repr__(self):
            return f"<{type_name} value={self.value!r}>"
        def __eq__(self, other):
            return isinstance(other, ComplexArgument) and self.value == other.value
    default = spec_option.get('default')
    return ComplexArgument(default)

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Base information for the complex type
    complex_type = {
        'subcommand': subcommand,
        'type_name': type_name,
        'option_name': option_name
    }

    # Merge the raw specification into the complexity definition
    if isinstance(spec_option, dict):
        complex_type.update(spec_option)

        # Handle nested complex fields recursively
        fields = spec_option.get('fields') if isinstance(spec_option, dict) else None
        if fields:
            complex_type['fields'] = {}
            for field_name, field_spec in fields.items():
                if isinstance(field_spec, dict) and field_spec.get('type') == 'complex':
                    nested_name = f"{type_name}_{field_name}"
                    complex_type['fields'][field_name] = self.create_complex_argumet_type(
                        subcommand, nested_name, field_name, field_spec
                    )
                else:
                    complex_type['fields'][field_name] = field_spec
    return complex_type

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
        """Build the complex argument type

        Designed to turn a specification into a custom parser that converts
        a string representation into a dataclass instance.
        """
        # Import inside the method to keep the module focused.
        from dataclasses import make_dataclass

        # The specification should provide a list of fields with optional defaults.
        # Expected format for each field: (name, type, default) where default is optional.
        fields = spec_option.get("fields", [])
        if not fields:
            # Nothing to parse – just return a function that passes the raw value.
            return lambda raw: raw

        # Dynamically create a dataclass with the given name and fields.
        # Defaults can be omitted, in which case the field is required.
        ComplexType = make_dataclass(type_name, fields)

        def parser(raw_value: str):
            """Parse a raw string into an instance of ComplexType."""
            # Expect the raw_value to be a comma-separated list of field=value pairs.
            # Example: "a=1,b=hello,c=3.5"
            values = {}
            for item in raw_value.split(","):
                item = item.strip()
                if not item:
                    continue
                if "=" not in item:
                    raise ValueError(f"Invalid token '{item}' for option '{option_name}'")
                key, val = item.split("=", 1)
                key = key.strip()
                val = val.strip()
                values[key] = val

            # Convert string values to the requested types.
            typed_values = {}
            for field_name, field_type, *rest in fields:
                if field_name not in values:
                    # If a value is missing and a default exists, skip conversion.
                    continue
                raw = values[field_name]
                try:
                    # Attempt conversion; support common types.
                    if field_type is bool:
                        # Typical truthy/falsy string handling.
                        typed_values[field_name] = raw.lower() in ("1", "true", "yes", "on")
                    else:
                        typed_values[field_name] = field_type(raw)
                except Exception as exc:
                    raise ValueError(
                        f"Cannot convert '{raw}' to {field_type} for field '{field_name}' "
                        f"in option '{option_name}': {exc}"
                    ) from exc

            return ComplexType(**typed_values)

        # Return the parser function that will produce the complex type instance.
        return parser

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Prepare dictionaries for the three categories
    control_args = {}
    nested_args = {}
    custom_args = {}

    # Normalize args into an iterable of (key, value) pairs
    if isinstance(args, dict):
        items = list(args.items())
    else:
        items = []
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                items.append((str(item[0]), item[1]))
            elif isinstance(item, str) and '=' in item:
                key, val = item.split('=', 1)
                items.append((key, val))
            else:
                # Treat as a flag (True)
                items.append((str(item), True))

    # Classify each argument
    for key, value in items:
        # Control arguments: explicit prefix or common flag names
        if key.startswith('control_') or key in ('debug', 'check', 'quiet'):
            control_args[key] = value
        # Custom arguments: explicit prefix
        elif key.startswith('custom_'):
            custom_args[key] = value
        # Otherwise nested arguments
        else:
            nested_args[key] = value

    # Merge custom arguments into nested; custom variables override nested values
    nested_args.update(custom_args)

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
        """
        Split input arguments into control, nested, and custom categories.

        :param args: A dictionary or iterable of (key, value) pairs.
        :return: (control_args, nested_args)
                 control_args: args that control IR behavior (not written to spec)
                 nested_args: args that go into the spec yml file (including custom vars)
        """
        # Determine the source of control and custom names
        control_names = set(self._control_args) if hasattr(self, "_control_args") else set()
        custom_names = set(self._custom_args) if hasattr(self, "_custom_args") else set()

        # Prepare the input as an iterable of (key, value) pairs
        if isinstance(args, dict):
            items = args.items()
        else:
            items = args

        control_args = {}
        nested_args = {}

        for key, value in items:
            if key in control_names:
                control_args[key] = value
            elif key in custom_names:
                # custom args are treated as nested args but flagged for future use
                nested_args[key] = value
            else:
                nested_args[key] = value

        return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars in the form ``key=value`` or a dictionary
    :return: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        return vars_dict
    if not extra_vars:
        return vars_dict

    for item in extra_vars:
        # Handle dict inputs directly
        if isinstance(item, dict):
            vars_dict.update(item)
        elif isinstance(item, str):
            if '=' in item:
                key, value = item.split('=', 1)
                key = key.strip()
                value = value.strip()
                # Attempt to evaluate Python literals for nicer types
                try:
                    import ast
                    parsed_value = ast.literal_eval(value)
                except Exception:
                    parsed_value = value
                vars_dict[key] = parsed_value
    return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")
    if not extra_vars:
        return vars_dict
    for item in extra_vars:
        if isinstance(item, dict):
            # Merge directly if the item is already a dict
            vars_dict.update(item)
        elif isinstance(item, str) and "=" in item:
            key, value = item.split("=", 1)
            # Try to interpret the value as JSON; fall back to raw string
            try:
                import json
                parsed_value = json.loads(value)
            except Exception:
                parsed_value = value
            vars_dict[key] = parsed_value
        else:
            raise ValueError(f"Unsupported extra var format: {item!r}")
    return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    ``extra_vars`` may be a list of strings ``'key=value'``, tuples/lists ``(key, value)``,
    dictionaries ``{'key': value}``, or a single dictionary. The function updates
    ``vars_dict`` in-place and returns it.
    """
    if not extra_vars:
        return vars_dict

    for item in extra_vars:
        if isinstance(item, dict):
            vars_dict.update(item)
        elif isinstance(item, (list, tuple)):
            if len(item) != 2:
                raise ValueError(f"Invalid pair {item!r} – expected a sequence of two items")
            key, value = item
            vars_dict[key] = value
        elif isinstance(item, str):
            if '=' not in item:
                raise ValueError(f"String extra-var must contain '=': {item!r}")
            key, value = item.split('=', 1)
            vars_dict[key] = value
        else:
            raise TypeError(f"Unsupported type for extra-var item: {type(item)}")

    return vars_dict

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not isinstance(vars_dict, dict):
            raise TypeError('vars_dict must be a dictionary')

        if not extra_vars:
            return vars_dict

        # If extra_vars is a dictionary, update directly
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # Handle iterable of items (list/tuple)
        # Each item may be a dict, or a string in "key=value" form
        if isinstance(extra_vars, (list, tuple)):
            items = extra_vars
        else:
            # Treat a single non-iterable item as one item
            items = [extra_vars]

        for item in items:
            if isinstance(item, dict):
                # Update with key/value pairs
                vars_dict.update(item)
            elif isinstance(item, str):
                if '=' in item:
                    key, val = item.split('=', 1)
                    vars_dict[key] = val
                else:
                    # If there's no '=', treat it as a flag that is set to True
                    vars_dict[item] = True
            else:
                # If the item is any other type, try to use it as a flag name
                try:
                    key = str(item)
                except Exception:
                    continue
                vars_dict[key] = True

        return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: Updated ``vars_dict`` with any new key/value pairs
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not extra_vars:
        return vars_dict
    for item in extra_vars:
        # Support items that are already dicts or tuples
        if isinstance(item, dict):
            vars_dict.update(item)
            continue
        if isinstance(item, (list, tuple)) and len(item) == 2:
            vars_dict[item[0]] = item[1]
            continue
        # Assume string of form key=value
        if isinstance(item, str) and "=" in item:
            key, value = item.split("=", 1)
            key = key.strip()
            value = value.strip()
            if key:
                vars_dict[key] = value
        else:
            # Silently ignore malformed items
            continue
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import json
    import os
    import subprocess

    # Build command
    cmd = ["ansible-playbook"]
    if isinstance(playbook_path, (list, tuple)):
        cmd += list(playbook_path)
    else:
        cmd.append(playbook_path)

    # Inventory
    # Prefer workspace.inventory_path if available
    if hasattr(ir_workspace, "inventory_path") and ir_workspace.inventory_path:
        cmd.extend(["-i", ir_workspace.inventory_path])
    # In some Infrared versions, inventory might be accessible via inventory()
    elif hasattr(ir_workspace, "inventory") and callable(ir_workspace.inventory):
        try:
            inv_path = ir_workspace.inventory()
            if inv_path:
                cmd.extend(["-i", inv_path])
        except Exception:
            pass

    # Verbosity
    if verbose:
        try:
            lvl = int(verbose)
        except Exception:
            lvl = 1
        if lvl > 0:
            cmd.append("-" + "v" * lvl)

    # Extra vars
    if extra_vars:
        cmd += ["--extra-vars", json.dumps(extra_vars)]

    # Additional ansible arguments
    if ansible_args:
        for key, val in ansible_args.items():
            flag = f"--{key}"
            if isinstance(val, bool):
                if val:
                    cmd.append(flag)
            elif isinstance(val, (list, tuple)):
                # Join lists with commas (common for tags, skip-tags)
                cmd.append(f"{flag}={','.join(str(v) for v in val)}")
            else:
                cmd.append(f"{flag}={val}")

    # Environment
    env = os.environ.copy()
    # Ensure Ansible always outputs colors for readability when running in terminal
    env.setdefault("ANSIBLE_FORCE_COLOR", "1")
    # If user wants to set stdout callback or other env vars via ansible_args
    # we consider anything starting with "env_" prefix
    if ansible_args:
        for key, val in ansible_args.items():
            if key.lower().startswith("env_"):
                env_key = key[4:].upper()
                env[env_key] = str(val)

    # Execute
    result = subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        env=env
    )

    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook exited with code {result.returncode}\n"
            f"Command: {' '.join(cmd)}\n"
            f"Stdout: {result.stdout}\n"
            f"Stderr: {result.stderr}"
        )

    return {
        "stdout": result.stdout,
        "stderr": result.stderr,
        "returncode": result.returncode
    }

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

      :param ir_workspace: An Infrared Workspace object represents the active
      workspace
      :param ir_plugin: An InfraredPlugin object of the current plugin
      :param playbook_path: the playbook to invoke
      :param verbose: Ansible verbosity level
      :param extra_vars: dict. Passed to Ansible as extra-vars
      :param ansible_args: dict of ansible-playbook arguments to plumb down
          directly to Ansible.
    """
    import subprocess
    import yaml

    cmd = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose:
        # Accept int or string (e.g. "2" or "vvv")
        vcount = 0
        if isinstance(verbose, int):
            vcount = verbose
        else:
            vcount = verbose.count("v")
        if vcount:
            cmd.append("-" + "v" * vcount)

    # Handle extra_vars
    if extra_vars:
        # Convert dict to YAML string
        try:
            ev_str = yaml.safe_dump(extra_vars, default_flow_style=True).strip()
        except Exception:
            ev_str = str(extra_vars)
        cmd.extend(["-e", ev_str])

    # Handle arbitrary ansible args
    if ansible_args:
        for key, value in ansible_args.items():
            # Convert key to command line format
            key_name = f"--{key.replace('_', '-')}"
            if isinstance(value, bool):
                if value:
                    cmd.append(key_name)
            elif isinstance(value, (list, tuple)):
                for v in value:
                    cmd.extend([key_name, str(v)])
            else:
                cmd.extend([key_name, str(value)])

    # Execute the command
    result = subprocess.run(
        cmd,
        capture_output=True,
        text=True
    )
    # Optionally, you might want to raise on error:
    if result.returncode != 0:
        raise RuntimeError(
            f"Ansible playbook failed with exit code {result.returncode}\n"
            f"STDOUT:\n{result.stdout}\nSTDERR:\n{result.stderr}"
        )
    return result

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # A mapping of parser_name to a dict of parameter names and the desired type.
        # This should be defined elsewhere in the class; use an empty dict if unavailable.
        type_map = getattr(self, '_arg_type_map', {})
        parser_map = type_map.get(parser_name, {})

        # In-place conversion to avoid modifying the dictionary during iteration
        for key, val in list(values_dict.items()):
            target_type = parser_map.get(key)
            if not target_type:
                continue  # no conversion defined for this key

            try:
                if target_type is bool:
                    if isinstance(val, str):
                        # Treat common truthy/falsey strings
                        values_dict[key] = val.lower() in ("true", "1", "yes", "y", "on")
                    else:
                        values_dict[key] = bool(val)
                elif target_type is list:
                    if isinstance(val, str):
                        # Split commas and strip whitespace, ignore empty items
                        values_dict[key] = [item.strip() for item in val.split(",") if item.strip()]
                    else:
                        # Ensure it's a list
                        values_dict[key] = list(val)
                else:
                    # For int, float, str, or any callable type
                    values_dict[key] = target_type(val)
            except Exception:
                # If conversion fails, keep the original string value
                pass

        return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict in place.
        Attempts common conversions: booleans, integers, floats, and comma‑separated lists.
        """
        def _convert_value(val):
            # Preserve None or non‑string types
            if not isinstance(val, str):
                return val
            s = val.strip()
            if s == '':
                return None
            # Boolean conversion
            lowered = s.lower()
            if lowered in ('true', 'false'):
                return lowered == 'true'
            # Integer / float conversion
            try:
                if '.' in s:
                    return float(s)
                return int(s)
            except ValueError:
                pass
            # List conversion on comma separated values
            if ',' in s:
                return [item.strip() for item in s.split(',')]
            return val

        # The parser_name could be used in future for custom casting rules,
        # but currently we perform generic heuristics.
        for key in list(values_dict.keys()):
            values_dict[key] = _convert_value(values_dict[key])

        return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to the correct types by modifying values_dict in place.

        By default all the values are strings.

        :param parser_name: The command name, e.g. 'main', 'virsh', 'ospd', etc.
        :param values_dict: The dictionary with argument names and string values.
        """
        # Retrieve type mapping for this parser, if any. It maps arg name -> expected type.
        type_map = getattr(self, 'arg_type_map', {}).get(parser_name, {})
        if not type_map:
            return

        for key, val in list(values_dict.items()):
            if key not in type_map:
                continue
            expected_type = type_map[key]
            try:
                if val is None:
                    continue

                # Handle booleans specially (strings -> bool)
                if expected_type is bool:
                    if isinstance(val, str):
                        values_dict[key] = val.lower() in ("1", "true", "yes", "y", "t")
                    else:
                        values_dict[key] = bool(val)

                # Handle lists (comma separated strings)
                elif expected_type is list:
                    if isinstance(val, str):
                        values_dict[key] = [item.strip() for item in val.split(",") if item.strip()]
                    else:
                        values_dict[key] = list(val)

                # General conversion
                else:
                    values_dict[key] = expected_type(val)
            except Exception as exc:
                raise ValueError(
                    f"Failed to cast argument '{key}' from value '{val}' "
                    f"to type '{expected_type.__name__}': {exc}"
                ) from exc

        # No return value; values_dict is mutated in place.

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc.
    :param values_dict: The dictionary of arguments.
    """
    # Retrieve the mapping of argument names to type‑converters for this parser.
    type_mapping = getattr(self, "_arg_type_map", {})
    parser_map = type_mapping.get(parser_name, {})

    # If there is no specific mapping for this parser, or values_dict is empty, do nothing.
    if not isinstance(values_dict, dict) or not values_dict or not parser_map:
        return

    for arg_name, cast_func in parser_map.items():
        # Skip arguments that are not present in the provided dictionary.
        if arg_name not in values_dict:
            continue

        value = values_dict[arg_name]
        # Leave None values untouched.
        if value is None:
            continue

        try:
            if cast_func is bool:
                # Normalize common truthy/falsy string representations.
                values_dict[arg_name] = str(value).strip().lower() in ("true", "1", "yes", "y")
            else:
                values_dict[arg_name] = cast_func(value)
        except Exception as exc:
            raise ValueError(
                f"Argument '{arg_name}' could not be cast to {cast_func.__name__} for parser '{parser_name}'"
            ) from exc
    # No explicit return; values_dict is modified in place.

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    Looks for a spec file named 'spec.yaml', 'spec.yml', or 'spec.json' inside the given
    plugin directory. The file is parsed with PyYAML or the standard json module
    and the resulting structure is flattened into a single‑level dictionary where
    nested keys are joined with a dot ('.').  Lists are flattened by index.

    :param plugin_dir: A path to the plugin's directory.
    :return: A flat dictionary containing the plugin's properties.
    """
    from pathlib import Path
    import json

    try:
        import yaml
    except Exception:
        yaml = None

    plugin_path = Path(plugin_dir)
    spec_file = None

    for fname in ("spec.yaml", "spec.yml", "spec.json"):
        candidate = plugin_path / fname
        if candidate.is_file():
            spec_file = candidate
            break

    if not spec_file:
        return {}

    with spec_file.open("r", encoding="utf-8") as f:
        if spec_file.suffix in {".yaml", ".yml"} and yaml:
            data = yaml.safe_load(f)
        else:
            data = json.load(f)

    def _flatten(value, prefix=""):
        """
        Recursively flatten a nested dictionary or list.
        Keys in dictionaries are joined with '.', lists are indexed.
        """
        items = {}

        if isinstance(value, dict):
            for k, v in value.items():
                key = f"{prefix}.{k}" if prefix else k
                items.update(_flatten(v, key))
        elif isinstance(value, list):
            for idx, v in enumerate(value):
                key = f"{prefix}.{idx}" if prefix else str(idx)
                items.update(_flatten(v, key))
        else:
            items[prefix] = value

        return items

    return _flatten(data if isinstance(data, (dict, list)) else {})

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Determine the spec file path (prefer JSON, fall back to YAML if available)
    spec_file = None
    for candidate in ("plugin.json", "plugin.yml", "plugin.yaml", "spec.json", "spec.yaml"):
        potential = os.path.join(plugin_dir, candidate)
        if os.path.isfile(potential):
            spec_file = potential
            break
    if not spec_file:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load the spec
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.endswith(".json"):
                data = json.load(f)
            else:
                # Attempt to load YAML
                try:
                    import yaml
                except ImportError:
                    raise ValueError("YAML spec found but pyyaml is not installed")
                data = yaml.safe_load(f)
    except Exception as exc:
        raise ValueError(f"Failed to load spec file '{spec_file}': {exc}") from exc

    # Helper function to flatten nested dictionaries
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            elif isinstance(v, list):
                # Flatten lists by including the index in the key
                for idx, item in enumerate(v):
                    if isinstance(item, dict):
                        items.update(_flatten(item, f"{new_key}{sep}{idx}", sep=sep))
                    else:
                        items[f"{new_key}{sep}{idx}"] = item
            else:
                items[new_key] = v
        return items

    return _flatten(data)

