                items.update(_flatten(value, new_key))
            else:
                items[new_key] = value
        return items

    # Expect the plugin spec to be stored in 'spec.json' inside the plugin_dir
    spec_path = os.path.join(plugin_dir, "spec.json")
    if not os.path.isfile(spec_path):
        raise FileNotFoundError(f"Plugin spec file not found: {spec_path}")

    with open(spec_path, "r", encoding="utf-8") as f:
        spec_data = json.load(f)

    return _flatten(spec_data)

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Look for a spec file named 'plugin.json' in the plugin directory
    spec_path = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.exists(spec_path):
        # If the spec file does not exist, return an empty dict
        return {}

    # Load the plugin spec from the JSON file
    with open(spec_path, 'r', encoding='utf-8') as f:
        try:
            spec_data = json.load(f)
        except json.JSONDecodeError:
            # If JSON parsing fails, return an empty dict
            return {}

    def _flatten(current, parent_key=''):
        """
        Recursively generate a flat dictionary from nested data.
        Dictionaries become dot‑separated keys.
        Lists become comma‑separated strings.
        """
        flattened = {}
        for key, value in (current or {}).items():
            # Build the new key by concatenating the parent key
            new_key = f"{parent_key}.{key}" if parent_key else key

            if isinstance(value, dict):
                flattened.update(_flatten(value, new_key))
            elif isinstance(value, list):
                # Convert lists to comma‑separated strings
                flattened[new_key] = ','.join(str(item) for item in value)
            else:
                flattened[new_key] = value
        return flattened

    # Return the flattened spec dictionary
    return _flatten(spec_data)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Find the plugin spec file (YAML or JSON)
    spec_names = [
        "plugin.yaml", "plugin.yml", "spec.yaml", "spec.yml",
        "plugin.json", "spec.json",
    ]
    import os
    spec_path = None
    for name in spec_names:
        candidate = os.path.join(plugin_dir, name)
        if os.path.isfile(candidate):
            spec_path = candidate
            break
    if not spec_path:
        return {}

    # Load the spec file
    if spec_path.lower().endswith((".yaml", ".yml")):
        try:
            import yaml
        except ImportError:
            raise RuntimeError("pyyaml is required to parse YAML spec files")
        with open(spec_path, "r", encoding="utf-8") as f:
            try:
                spec = yaml.safe_load(f)
            except Exception as e:
                raise RuntimeError(f"Failed to parse YAML spec: {e}")
    else:
        with open(spec_path, "r", encoding="utf-8") as f:
            try:
                import json
                spec = json.load(f)
            except Exception as e:
                raise RuntimeError(f"Failed to parse JSON spec: {e}")

    # Helper to flatten the nested structure
    def _flatten_dict(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items() if isinstance(d, dict) else []:
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten_dict(v, new_key, sep=sep))
            elif isinstance(v, list):
                for idx, item in enumerate(v):
                    indexed_key = f"{new_key}[{idx}]"
                    if isinstance(item, dict):
                        items.update(_flatten_dict(item, indexed_key, sep=sep))
                    else:
                        items[indexed_key] = item
            else:
                items[new_key] = v
        return items

    return _flatten_dict(spec) if isinstance(spec, dict) else {}

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    if os.getenv('CONFIG_PATH') is None:
        os.environ['CONFIG_PATH'] = os.path.join(os.getcwd(), 'config.yaml')

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if not os.getenv("CONFIG_PATH"):
        # Prefer instance attribute if provided
        config_path = getattr(self, "config_path", None)
        if not config_path:
            # Default to a config.json in the same directory as this module
            config_path = os.path.join(os.path.dirname(__file__), "config.json")
        # Store the absolute path in the environment
        os.environ["CONFIG_PATH"] = os.path.abspath(config_path)

def inject_config(self):
    if "CONFIG_PATH" not in os.environ:
        os.environ["CONFIG_PATH"] = "./config.yaml"

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError(f"Root {root!r} not a prefix of path {path!r}")
    stripped = path[len(root):]
    return stripped.lstrip('/\\')
